// ==========================================
// ★ K 의 방 — S등급 직업 갈림길 · 치유
// 요리사 · 치유사 · 약사 · 의원 · 수도사
// ==========================================

// ------------------------------------------
// 요리사 (cook) · 자원 없음
// ------------------------------------------
kJob('cook', 'S', [

{ at:'S', t:'쉬는 자리 — 씹는 소리',
  x:`겨우 앉았다. 식량을 꺼냈다. 말린 고기다.<br><br>
    말린 고기는 씹는 소리가 난다. 질겅질겅. 조용한 데서는 그 소리가 꽤 멀리 간다.<br>
    여기 것들은 소리로 사냥한다. 아까 본 것은 숨소리만 듣고도 고개를 돌렸다.<br><br>
    배는 채워야 한다. 소리 없이. 부엌에서 오래 산 손은 음식을 조용하게 만드는 법도 안다.`,
  o:[
    { l:'① 고기를 물에 불려 잘게 찢는다.', k:'fix', dc:23, wake:1,
      ok:`말린 고기를 물에 담가 불렸다. 퍼지면 손끝으로 잘게 찢었다. 실처럼.<br><br>씹을 것이 없는 밥이다. 혀로 누르면 넘어간다. 다들 입을 다문 채 삼켰다. 아무 소리도 안 났다.<br>벽 너머에서 무언가가 한참 귀를 기울이다 갔다. 들을 것이 없었다.<br><br>질긴 것을 무르게 하는 건 늘 하던 일이다. 소리를 무르게 하는 법을 손이 새로 알았다. 같은 물, 같은 손이다.`,
      ng:`불리는데 물그릇이 돌에 닿았다. 달그락.<br><br>벽 너머의 것이 멈췄다. 이쪽도 멈췄다. 불린 고기를 입에 문 채 다들 한참 굳어 있었다.<br>그것이 벽을 한 번 길게 긁고 갔다. 손톱이 아니라 자 같은 것으로.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 한 입씩 직접 넣어 주고 입을 다물게 한다.', k:'heal', dc:24,
      ok:`한 사람씩 앞에 앉혔다. 한 입 크기로 떼어 혀 위에 올려 주고, 턱을 손으로 받쳐 다물게 했다.<br><br>삼킬 때까지 다음 것을 주지 않았다. 빨리 먹으면 소리가 난다. 급한 손부터 늦췄다.<br>다섯을 다 먹이는 데 오래 걸렸다. 그동안 아무것도 오지 않았다. 느린 밥이 조용한 밥이다.`,
      ng:`셋째가 급하게 삼키다 사레가 들렸다.<br><br>기침을 손으로 틀어막았다. 막은 손가락 사이로 소리가 샜다. 켁. 켁.<br>어둠 저쪽에서 돌 구르는 소리가 났다. 이쪽으로 오는 소리다. 밥을 덮고 다 같이 자리를 옮겼다.`,
      win:{ exp:16, dream:2, hp:8 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S', t:'어둠 — 피 냄새',
  x:`하나가 어깨를 찢겼다. 천으로 묶었는데 배어 나온다.<br><br>
    피 냄새는 걷는 내내 따라온다. 여기 것들은 피 냄새를 몇 굽이 밖에서도 맡는다.<br>
    지혈은 치유 쪽 일이다. 냄새는 부엌 일이다. 부엌에서는 냄새를 겹치고 덮고 지운다. 매일.<br><br>
    등 뒤 어둠에서 공기 마시는 소리가 났다. 킁. 한 번.`,
  o:[
    { l:'① 기름 쩐내로 피 냄새를 덮는다.', k:'hide', dc:24,
      ok:`냄비 바닥에 눌어붙은 묵은 기름때를 천에 묻혀 태웠다. 쩐내가 확 퍼진다.<br><br>그 천을 지나온 길에 걸어 두고 반대로 꺾었다. 피 냄새 위에 쩐내가 덮인다. 오래된 냄새는 새 냄새를 가린다.<br>등 뒤의 킁킁 소리가 천 앞에서 한참 머물렀다. 그동안 두 굽이를 벌었다.`,
      ng:`쩐내가 퍼지긴 했다. 그런데 쩐내도 결국 먹는 냄새다.<br><br>킁킁 소리가 둘이 됐다. 하나는 피를, 하나는 기름을 따라온다.<br>천을 버리고 뛰었다. 뒤에서 천 찢는 소리가 났다. 아주 잠깐 벌었을 뿐이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 피 밴 천을 소금에 절여 다시 묶는다.', k:'heal', dc:23, wake:1,
      ok:`묶은 천을 풀어 소금을 박박 비벼 넣고 다시 감았다. 그 사람이 이를 물었다. 쓰리다. 쓰려야 한다.<br><br>소금은 피를 굳히고 냄새를 죽인다. 고기를 절일 때와 같다. 한 굽이를 가고 코를 대 봤다. 소금내뿐이다.<br>등 뒤의 숨소리가 길을 잃었다. 킁. 킁. 제자리에서.<br><br>간을 치던 손이 상처에 간을 쳤다. 절이는 일은 상하지 않게 하는 일이다. 고기든 사람이든.`,
      ng:`소금이 모자랐다. 반만 절여졌다.<br><br>반은 여전히 피 냄새다. 반으로도 그것들은 충분했다.<br>밤새 세 번 자리를 옮겼다. 옮길 때마다 그 사람 어깨가 한 번씩 더 벌어졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-16 } },
    { l:'③ 피 밴 천을 벗겨 멀리 던져 버린다.', k:'evade', dc:23,
      ok:`천을 새것으로 갈고, 피 밴 것은 돌에 감아 바람 불어가는 쪽으로 멀리 던졌다.<br><br>어둠 저쪽에서 돌 떨어지는 소리. 이어서 여럿이 그쪽으로 몰려가는 소리가 났다.<br>냄새가 싸우는 동안 조용히 빠졌다. 미끼는 부엌 밖에서도 미끼다.`,
      ng:`던진 돌이 가까운 벽에 맞고 되돌아 굴렀다. 발치까지.<br><br>피 냄새가 이쪽 발밑에서 다시 핀다. 어둠 속의 것이 곧장 왔다.<br>천을 걷어차고 뛰었다. 뒤에서 천을 찢고 씹는 소리가 났다. 씹고 나면 더 찾을 것이다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'S', t:'쉬는 자리 — 먹지 않는 사람',
  x:`식량을 돌렸다. 하나가 제 몫을 그대로 들고만 있다.<br><br>
    못 먹겠다고 한다. 넘어가지 않는다고. 아까 본 것이 자꾸 생각난다고 한다.<br>
    무서우면 목이 먼저 잠긴다. 부엌에서 오래 일하면 안다. 그런데 안 먹은 몸은 뛰지 못한다.<br><br>
    여기서 뛰지 못하는 몸은 제일 먼저 없어지는 몸이다.`,
  o:[
    { l:'① 더운물에 꿀을 풀어 먼저 쥐여 준다.', k:'bond', dc:23,
      ok:`물을 데워 꿀을 반 숟갈 풀었다. 그릇째 손에 쥐여 줬다. 마시라는 말은 안 했다.<br><br>손이 따뜻해지니 한 모금 넘긴다. 단것은 잠긴 목을 연다. 한 그릇을 비우고 나서 제 몫의 고기를 집었다.<br>다 먹고 그 사람이 물었다. 이 단 건 아껴 둔 것 아니냐고. 아껴 둔 것 맞다. 이럴 때 쓰려고.`,
      ng:`그릇을 쥐여 줬는데 손이 떨려 반을 쏟았다.<br><br>단내가 바닥에 퍼진다. 단내는 멀리 간다. 피 냄새 다음으로.<br>쏟은 자리를 흙으로 덮고 자리를 옮겼다. 그 사람은 끝내 못 먹었다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 국물만 내서 억지로라도 떠먹인다.', k:'heal', dc:24, wake:1,
      ok:`말린 고기를 잘게 찢어 더운물에 우렸다. 씹을 것 없는 국물이다. 숟가락으로 떠서 입에 댔다.<br><br>한 술. 삼킬 때까지 기다렸다. 또 한 술. 약 먹이듯 셌다. 열두 술에 그릇이 비었다.<br>국물이 들어가니 고기도 들어간다. 그 사람 손이 떨리다 멎었다.<br><br>밥을 약처럼 먹이는 법이 손에 붙었다. 몇 술이 사람을 일으키는지 세는 버릇. 그 셈이 생겼다.`,
      ng:`셋째 술에서 그 사람이 왈칵 게웠다.<br><br>소리가 컸다. 게운 냄새는 더 컸다. 급히 흙을 덮었지만 늦었다.<br>어둠 저쪽에서 긴 것이 지나가며 한 번 멈췄다. 이쪽을 세는 것처럼.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'S', t:'통로 — 길목의 것',
  x:`앞 길목에 무언가 엎드려 있다. 숨소리가 느리다. 자는 게 아니다. 기다리는 숨이다.<br><br>
    돌아갈 길은 없다. 지나가야 한다.<br>
    봇짐에 짐승 고기 한 덩이가 있다. 아껴 온 것이다.<br><br>
    고기는 먹이고, 먹이는 자리를 바꾼다. 상 차리는 자리가 곧 사람 모이는 자리다. 짐승도 같다.`,
  o:[
    { l:'① 고기를 바람 불어가는 쪽으로 멀리 던진다.', k:'sense', dc:24,
      ok:`손가락에 침을 묻혀 바람을 읽었다. 왼쪽 틈으로 공기가 빠진다.<br><br>고기를 그쪽으로 힘껏 던졌다. 퍽. 냄새가 바람을 타고 틈으로 흘러간다.<br>엎드린 것이 고개를 들더니 소리 없이 그쪽으로 미끄러져 갔다. 빈 길목을 하나씩 지났다. 상은 저쪽에 차려졌다.`,
      ng:`바람을 잘못 읽었다. 고기 냄새가 이쪽으로 되돌아왔다.<br><br>엎드린 것이 고개를 들었다. 고기가 아니라 고기 든 손을 봤다.<br>고기를 길에 놓고 뒷걸음쳤다. 그것이 고기를 다 먹을 때까지 벽에 붙어 있었다. 먹고 나서도 한참 이쪽을 봤다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 고기에 쓴 약초를 쟁여 넣어 굴린다.', k:'fix', dc:25,
      ok:`고기에 칼집을 내고 제일 쓴 약초를 꾹꾹 쟁였다. 겉은 멀쩡한 고기다. 길목으로 굴렸다.<br><br>그것이 한입에 물었다. 그리고 뱉었다. 캑캑대며 머리를 흔든다.<br>그 뒤로 그것은 이쪽 냄새가 나는 것을 입에 대지 않았다. 맛없는 먹이로 적히는 것. 그것도 사는 법이다.`,
      ng:`쓴맛을 느끼기는 한 모양이다. 그런데 뱉지 않았다. 삼켰다.<br><br>그리고 이쪽을 봤다. 더 달라는 눈이다. 쓴 것도 먹는 입에는 간 맞출 방법이 없다.<br>그것이 어슬렁어슬렁 따라오기 시작했다. 한 굽이를 뛰어서 겨우 떼어 냈다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S', t:'물가 — 마실 물',
  x:`물이 떨어졌다. 다들 입술이 텄다.<br><br>
    어둠 속에 웅덩이가 있다. 넓고, 검고, 조용하다. 물 냄새는 거의 맞다. 거의.<br>
    부엌에서는 물부터 가린다. 국이 되는 물과 탈이 나는 물. 그리고 여기서는 하나 더 가려야 한다.<br><br>
    물이 조용한 것과 물속이 조용한 것은 다른 얘기다.`,
  o:[
    { l:'① 조금 떠서 끓여 김 냄새를 맡는다.', k:'sense', dc:23, wake:1,
      ok:`가장자리에서 반 그릇만 떠 왔다. 작은 불에 끓였다. 김이 오를 때 코를 댔다.<br><br>흙내 밑에 비린내가 한 줄 지나간다. 이 물엔 사는 것이 있다. 큰 것이.<br>마실 물은 끓여서 챙기고, 웅덩이에는 아무도 못 다가가게 했다. 물을 뜨러 간 게 아니라 물에게 물어보러 간 셈이다.<br><br>김 냄새로 물속을 읽는 코. 국 끓이던 코가 이제 물 아래까지 맡는다.`,
      ng:`끓이는 김 냄새가 물가에 퍼졌다.<br><br>웅덩이 한가운데가 소리 없이 부풀었다 가라앉았다. 숨이다. 물 밑에서 쉬는 숨.<br>불을 발로 덮고 그릇째 들고 뛰었다. 반 그릇이 출렁여 반의 반이 됐다.`,
      win:{ exp:22, dream:3, item:'맑은 물' }, lose:{ mind:-15, spirit:-18 } },
    { l:'② 가장자리 웃물만 살살 떠 담는다.', k:'steady', dc:24,
      ok:`병 주둥이를 수면에 눕혀 웃물만 받았다. 물결 하나 안 내고.<br><br>세 병을 채우는 데 한참 걸렸다. 급한 손들이 등 뒤에서 발을 굴렀지만 속도를 안 바꿨다.<br>물러날 때까지 웅덩이는 잔잔했다. 잔잔한 채로 두고 오는 것이 이 물가의 예의다.`,
      ng:`둘째 병에서 손이 미끄러졌다. 병이 반쯤 잠기며 꿀럭 소리를 냈다.<br><br>웅덩이 저쪽에서 물결이 한 줄 일었다. 이쪽으로 오는 물결이다.<br>병을 쥔 채 물러났다. 물가에 남은 발자국이 천천히 물에 잠겼다. 수면이 발자국을 읽는 것처럼.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ hp:-26, spirit:-16 } },
    { l:'③ 엎드려서 바로 들이켠다.', k:'luck', dc:25,
      doom:{ title:'수면 아래', what:'물속의 것에게 붙들려 끌려 들어갑니다', dc:19, sec:45,
        text:`목이 너무 말랐다. 엎드려 입을 댔다. 물은 차고 달다.<br><br>두 모금째에 물맛이 변했다. 비리다. 수면 바로 밑에서 무언가가 입 쪽으로 올라오고 있었다.<br>긴 것이 목을 감는다. 차갑고 미끈하다. 숨 쉴 새도 없이 얼굴부터 물로 끌려 들어간다.<br><br>물은 소리를 삼킨다. 첨벙 소리 한 번이 전부다.`,
        dieText:`웅덩이가 다시 잔잔해졌다.<br><br>가장자리에 빈 물병 하나가 떠 있다. 물은 여전히 차고 달다.<br>이 물가에서는 엎드린 자세가 제일 위험한 자세다. 그걸 아는 사람이 하나 줄었다.` },
      ok:`엎드리다가 수면에 비친 게 보였다. 이쪽 얼굴 옆에 다른 것이 비친다. 물 밑에서 올려다보는 것.<br><br>입 대신 모자를 물에 던졌다. 수면이 모자째 접히며 삼켰다.<br>뒤로 굴러 물러났다. 목마름은 남았지만 목은 남았다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'쉬는 자리 — 마지막 소금',
  x:`소금 주머니를 털었다. 바닥에 한 줌 남았다.<br><br>
    상처 씻을 물에도 소금이 들어가야 하고, 밥에도 들어가야 한다. 한 줌으로는 하나다.<br>
    싱거운 밥은 힘이 덜 나고, 맹물로 씻은 상처는 덧난다.<br><br>
    부엌의 셈은 늘 이렇다. 모자라는 것을 어디에 치는가.`,
  o:[
    { l:'① 반은 상처 씻을 물에 푼다.', k:'heal', dc:23, wake:1,
      ok:`반을 덜어 끓인 물에 풀었다. 소금물로 상처 셋을 씻었다. 다들 쓰리다고 욕을 했다.<br><br>남은 반으로는 국에 간을 했다. 싱겁다. 싱거운 대로 다 비웠다.<br>이틀 뒤에도 상처 셋이 다 말랐다. 덧난 데가 없다. 욕하던 입들이 조용했다.<br><br>간을 친다는 말을 다시 배웠다. 밥에도 치고 살에도 친다. 소금의 두 쓰임이 한 손에 들어왔다.`,
      ng:`푸는데 주머니가 터졌다. 반이 흙바닥에 쏟아졌다.<br><br>흙 섞인 소금은 상처에 못 쓴다. 남은 것으로 씻을 물만 겨우 만들었다.<br>그날 밥은 맹밥이었다. 맹밥 먹은 걸음은 반 박자 늦다. 여기서 반 박자는 크다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 눈물만큼씩 아껴 끝까지 간만 한다.', k:'fix', dc:24,
      ok:`손톱 끝으로 집어 한 그릇에 세 톨씩. 간이라기보다 기별이다.<br><br>그래도 혀는 그 세 톨을 찾아낸다. 맛이 있으면 넘어가고, 넘어가면 힘이 된다.<br>주머니 바닥의 소금이 사흘을 갔다. 사흘이면 여기서는 한 생이다.`,
      ng:`아낀다고 아꼈는데 둘째 날 주머니째 잃어버렸다.<br><br>쉬던 자리에 두고 왔다. 돌아갈 수는 없는 자리다.<br>그 뒤로는 내내 맹밥이다. 다들 말수가 줄었다. 싱거운 밥상은 조용하다. 좋은 조용함이 아니다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S', t:'어둠 — 불 없는 밤',
  x:`오늘은 불을 못 피운다. 다들 안다.<br><br>
    아까 지나간 것은 빛을 보고 돌아왔다. 두 번이나.<br>
    찬 몸에 찬 날것이 들어가면 속에서 힘을 뺏긴다. 데운 것 한 입이 필요한 밤이다.<br><br>
    불 없이 데우는 법. 부엌 밖에서는 그런 것도 부엌 일이 된다.`,
  o:[
    { l:'① 낮에 데워 둔 돌을 꺼내 고기를 올린다.', k:'fix', dc:24, wake:1,
      ok:`걷는 동안 품에 넣어 데워 둔 돌 두 개를 꺼냈다. 아직 미지근하다.<br><br>돌 사이에 고기를 끼우고 천으로 감쌌다. 한참 뒤에 풀었다. 데워졌다. 겨우, 그러나 분명히.<br>미지근한 고기 한 점씩. 속에서부터 떨림이 멎었다.<br><br>불을 몸에 지니고 다니는 법을 배웠다. 부엌이 등에 업히는 날의 요령이다.`,
      ng:`돌이 다 식어 있었다. 품이 아니라 봇짐에 넣고 걸은 탓이다.<br><br>찬 돌에 찬 고기. 데워지는 건 아무것도 없다.<br>날것을 그냥 돌렸다. 밤새 이 딱딱 부딪는 소리를 서로 손으로 막아 줬다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 날것을 양념에 무쳐 넘긴다.', k:'heal', dc:23,
      ok:`약초 뭉치에서 매운 잎을 골라 비볐다. 날고기에 묻혔다.<br><br>매운 것은 속에서 덥다. 한 점씩 씹자 귀 뒤가 후끈해진다. 불 없이 낸 불이다.<br>다들 콧물을 훌쩍이며 웃었다. 소리 안 나게. 그런 웃음도 힘이 된다.`,
      ng:`매운 잎이 아니라 쓴 잎을 집었다. 어두워서.<br><br>쓴 날고기는 벌이다. 다들 꾸역꾸역 넘겼다.<br>하나가 속이 뒤집혀 밤새 식은땀을 흘렸다. 요리사 손이 어두우면 밥이 벌이 된다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S', t:'사체 — 손질',
  x:`싸움이 끝났다. 큰 것 하나가 쓰러져 있다.<br><br>
    고기다. 며칠 치 고기. 그런데 여기 짐승의 살에는 딴것이 세 들어 사는 수가 있다.<br>
    칼을 잡은 손이 제일 먼저 묻는 것. 이 살은 살뿐인가.<br><br>
    서두르면 안 된다. 그리고 여기서는 오래 서 있어도 안 된다. 사체 냄새는 초대장이다.`,
  o:[
    { l:'① 결을 따라 갈라 살빛부터 본다.', k:'gaze', dc:24,
      ok:`결을 따라 길게 갈랐다. 살빛을 봤다. 맑은 분홍이면 살이고, 잿빛이 섞이면 딴것이 지나간 자리다.<br><br>뒷다리 쪽만 맑다. 그쪽만 발라냈다. 앞쪽은 잿빛 길이 실처럼 나 있었다. 통째로 버렸다.<br>빠른 칼 열 번보다 바른 칼 세 번이다. 보따리가 묵직해졌다.`,
      ng:`가르는데 칼끝이 물컹한 주머니를 건드렸다.<br><br>터졌다. 시큼한 것이 확 끼친다. 살 속에 고여 있던 것이다.<br>튄 자리가 화끈거린다. 고기는 한 점도 못 챙기고 물러났다. 사체가 등 뒤에서 부글거렸다.`,
      win:{ exp:20, dream:3, item:'짐승 고기' }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 냄새로 성한 데만 골라 도려 낸다.', k:'heal', dc:23,
      ok:`코를 바짝 대고 훑었다. 성한 살은 쇠 냄새가 나고, 아닌 데는 단내가 돈다. 살면서 안 나는 단내.<br><br>단내 나는 데를 피해 성한 데만 네모나게 도려 냈다.<br>소금을 쳐 천에 감았다. 짐이 무거워졌다. 좋은 무게다.`,
      ng:`냄새가 다 섞여 있었다. 사체가 식으며 냄새가 뭉개진 것이다.<br><br>가린다고 가렸는데 한 덩이에서 단내가 났다. 챙긴 것을 다 풀어 다시 맡고, 반을 버렸다.<br>그러는 사이 멀리서 발소리들이 모여들기 시작했다. 사체 상속자들이다.`,
      win:{ exp:18, dream:2, item:'짐승 고기' }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'쉬는 자리 — 이상한 허기',
  x:`하나가 제 몫을 다 먹고 남의 몫을 본다.<br><br>
    아까도 그랬다. 먹어도 먹어도 허기진다고 한다. 눈이 퀭하다.<br>
    무서워서 먹는 허기가 있고, 몸이 축나서 먹는 허기가 있다. 그리고 여기에는 셋째 허기가 있다.<br>
    속에 든 것이 대신 배고픈 허기.<br><br>
    밥을 주는 손이 제일 먼저 알아챈다. 늘 그렇다.`,
  o:[
    { l:'① 그 사람 국에만 쓴 약초를 짙게 푼다.', k:'fix', dc:25,
      ok:`그 사람 그릇에만 제일 쓴 잎을 우렸다. 모르게.<br><br>한 술 뜨더니 얼굴을 확 구긴다. 뭐가 이렇게 쓰냐고 성을 낸다.<br>쓴맛을 아는 혀는 제 혀다. 속에 딴것이 들었으면 쓴 줄도 모르고 넘긴다. 그냥 겁에 질려 먹던 허기였다.<br><br>미안하다고 하고 새로 떠 줬다. 그 사람은 두 그릇째에서 숟가락을 놓았다. 배가 부르다고. 그 말이 반가웠다.`,
      ng:`그 사람이 쓴 국을 아무렇지 않게 비웠다. 표정 하나 없이.<br><br>그리고 그릇을 내밀었다. 더 달라고. 쓴 줄을 모른다.<br>국자를 쥔 손이 차가워졌다. 그날 밤 그 사람 자리를 불 쪽에서 제일 먼 데로 옮겼다. 이유는 말하지 못했다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 먹는 속도를 손으로 눌러 늦춘다.', k:'steady', dc:23,
      ok:`그 사람 숟가락 위에 손을 얹었다. 천천히. 한 술 넘기면 다음 술.<br><br>빨리 먹는 배는 부른 줄을 모른다. 느리게 먹이자 열 술에서 숨을 내쉰다.<br>배가 부르다고 한다. 허기가 멎는 허기면 아직 사람 허기다. 손을 떼고 등을 한 번 쓸어 줬다.`,
      ng:`손을 얹자 그 사람이 손목을 탁 쳐 냈다.<br><br>눈빛이 사납다. 먹는 걸 건드리지 말라고. 목소리가 평소보다 반 키 낮다.<br>물러났다. 그 사람은 제 몫을 다 먹고 빈 그릇 바닥을 오래 핥았다. 다들 못 본 척했다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-16, spirit:-20 } },
    { l:'③ 한밤에 식량 자루 쪽으로 가는 그를 따라간다.', k:'hide', dc:25,
      doom:{ title:'밤참', what:'허기진 것에게 물려 어둠 속으로 끌려갑니다', dc:19, sec:40,
        text:`한밤에 그 사람이 일어났다. 식량 자루 쪽으로 간다. 발소리를 죽이고 따라갔다.<br><br>그 사람이 자루 앞에 쪼그려 앉아 있다. 그런데 자루를 풀지 않는다. 냄새만 맡는다. 길게. 짐승처럼.<br>이름을 부르자 고개가 돌아온다. 턱이 사람 턱보다 많이 벌어져 있다.<br><br>어깨를 물렸다. 그대로 어둠 쪽으로 끌려간다. 그 사람 힘이 아니다. 끌려가며 본 식량 자루는 멀쩡했다. 밤참은 자루가 아니었다.`,
        dieText:`아침에 그 사람은 제자리에서 눈을 떴다. 아무것도 기억하지 못했다.<br><br>배가 부르다고 했다. 처음으로.<br>식량 자루는 그대로다. 사람 수만 하나 줄었다.` },
      ok:`따라가다 멈췄다. 그 사람 그림자가 둘로 보였다. 하나는 사람 모양, 하나는 아닌 모양.<br><br>부르는 대신 돌을 반대쪽으로 던졌다. 그 사람이, 아니 그것이 소리 쪽으로 홱 돌았다.<br>그 틈에 일행을 다 깨웠다. 불을 켜자 그 사람은 제자리에 누워 있었다. 신발에 흙이 묻은 채.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'어둠 — 배 속의 소리',
  x:`숨도 못 쉬는 길목이다. 벽 하나 너머에서 그것들이 오간다.<br><br>
    그때 누군가의 배가 울었다. 꼬르륵. 길게.<br>
    굶은 배는 주인 말을 안 듣는다. 그리고 여기 것들 귀는 그 소리를 안다. 속이 빈 것의 소리. 약한 것의 소리.<br><br>
    벽 너머의 오가던 발이 멎었다.`,
  o:[
    { l:'① 허리띠를 당겨 배를 조여 준다.', k:'fix', dc:23,
      ok:`소리 난 사람 허리띠를 두 칸 당겨 조였다. 배가 눌리면 소리가 죽는다. 부엌 바쁠 때 끼니 거르던 요령이다.<br><br>남은 사람들 것도 말없이 한 칸씩 조였다.<br>벽 너머 발이 한참 서 있다 다시 걸었다. 멀어지는 쪽으로. 배들은 조용했다.`,
      ng:`조이는데 허리띠 쇠가 벽에 긁혔다. 끼익.<br><br>꼬르륵보다 나쁜 소리다. 벽 너머가 조용해졌다. 듣는 조용함이다.<br>셋을 세고 다 같이 뛰었다. 등 뒤 벽에서 무언가 벽을 타 넘는 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 씹을 것을 하나씩 입에 물린다.', k:'bond', dc:24,
      ok:`말린 고기를 가늘게 찢어 하나씩 입에 물렸다. 삼키지 말고 물고만 있으라고 손짓했다.<br><br>입에 먹을 것이 물리면 배가 속는다. 운다던 배들이 조용해졌다.<br>길목을 다 지나고 나서야 다들 그것을 씹었다. 제일 맛있는 한 점이었다고 나중에들 말했다.`,
      ng:`물리다가 한 사람이 급하게 삼켰다. 꿀꺽.<br><br>빈 데로 넘어간 밥은 더 크게 운다. 꼬르륵. 아까보다 길게.<br>벽 너머에서 긁는 소리가 답했다. 이쪽 벽을. 안쪽에서 다 들린다는 뜻이다.`,
      win:{ exp:20, dream:3, mind:6 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S', t:'갈림길 — 냄새의 결',
  x:`길이 둘로 갈린다. 어느 쪽이든 어둡다.<br><br>
    한쪽에서는 오래 묵은 피 냄새가 난다. 마르고 삭은 냄새다.<br>
    다른 쪽에서는 아무 냄새도 안 난다. 깨끗하다. 너무 깨끗하다.<br><br>
    부엌 바닥은 닦는 사람이 있어야 깨끗하다. 길도 그렇다. 냄새가 없는 길은 누가 치우는 길이다.`,
  o:[
    { l:'① 냄새 없는 쪽이 더 나쁘다고 말한다.', k:'sense', dc:24, wake:1,
      ok:`일행을 세우고 말했다. 묵은 피 냄새는 오래된 일이고, 냄새 없는 건 지금도 치우는 놈이 있다는 뜻이다.<br><br>제 집을 치우는 것들이 있다. 먹고, 핥고, 흔적을 지우는. 깨끗한 길이 그 집 앞마당이다.<br>피 냄새 쪽으로 갔다. 마른 얼룩만 밟았다. 산 것은 아무것도 없었다.<br><br>냄새로 길의 나이를 읽는 코가 생겼다. 무엇이 났는가가 아니라, 언제 났는가를 맡는 코다.`,
      ng:`말은 했는데 반이 못 믿었다. 피 냄새 쪽이 더 무섭다는 것이다.<br><br>갈라져 가자는 말까지 나왔다. 어둠 속에서 패가 갈리는 것. 그게 제일 나쁘다.<br>결국 다 같이 피 냄새 쪽으로 갔지만, 걷는 내내 뒤쪽 반이 자꾸 돌아봤다. 믿음이 상한 밥상은 오래 간다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 냄새 없는 쪽으로 앞장선다.', k:'luck', dc:25,
      doom:{ title:'씻긴 길', what:'길 끝의 것에게 붙들려 끌려갑니다', dc:18, sec:45,
        text:`깨끗한 쪽이 빠른 길처럼 보였다. 앞장섰다.<br><br>바닥이 매끈하다. 벽도 매끈하다. 핥아서 낸 매끈함이라는 걸 반쯤 가서 알았다.<br>길 끝이 막혀 있다. 막힌 게 아니라 들어차 있다. 그것이 몸을 펴자 길이 좁아졌다.<br><br>혀 같은 것이 발목을 감았다. 바닥에 끌리며 안쪽으로 당겨진다. 치워진 길 위라 붙잡을 것 하나 없다.`,
        dieText:`그 길은 다음 날도 깨끗했다.<br><br>바닥에 긁힌 자국 하나 없이. 그래서 깨끗한 길이다.<br>치우는 것이 안에 살고 있으니까.` },
      ok:`반쯤 가다 걸음을 멈췄다. 바닥이 너무 매끈하다. 설거지한 그릇처럼.<br><br>그릇이 깨끗한 건 쓰는 입이 있어서다. 소름이 목까지 올라왔다.<br>소리 없이 손을 들어 돌렸다. 다 빠져나올 때까지 길 끝의 어둠이 숨을 참고 있었다. 이쪽도 참았다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'표본실 — 밀봉 상자',
  x:`창고 선반에 식량 상자들이 쌓여 있다. 연구소 사람들 먹던 것이다.<br><br>
    반은 뜯겼고 반은 밀봉이 남았다. 뜯은 자국이 사람 손 같지 않다.<br>
    밀봉이 성하면 안의 것도 성하다. 부엌 창고의 첫째 규칙이다.<br><br>
    둘째 규칙도 있다. 부푼 통은 열지 않는다.`,
  o:[
    { l:'① 뚜껑 눌림을 하나씩 확인한다.', k:'fix', dc:23,
      ok:`통조림 뚜껑을 하나씩 눌러 봤다. 오목하게 들어간 것만 골랐다. 눌려 있으면 안이 비었다. 공기가. 상한 것은 숨을 만들어 뚜껑을 민다.<br><br>성한 것 여덟 통. 말린 것 한 꾸러미.<br>뜯긴 상자들 쪽은 손도 안 댔다. 뜯은 입이 침을 발라 놓은 것들이다.`,
      ng:`누르다가 하나가 손 밑에서 피식 새었다. 바늘구멍이 나 있던 통이다.<br><br>새어 나온 냄새가 지독했다. 상한 냄새가 아니다. 안에서 무언가 자란 냄새다.<br>통을 떨어뜨렸다. 바닥에 쏟아진 것이 꿈틀, 했다. 챙긴 것 없이 창고를 나왔다.`,
      win:{ exp:20, dream:2, item:'말린 고기' }, lose:{ hp:-26, spirit:-16 } },
    { l:'② 부푼 통만 골라 구석으로 치운다.', k:'heal', dc:24, wake:1,
      ok:`부푼 통들을 먼저 가려냈다. 열지 않고, 흔들지 않고, 하나씩 구석으로 옮겼다. 숨 쉬는 것 다루듯.<br><br>부푼 통 열둘. 그중 둘은 손바닥에 대자 미지근했다. 통조림은 미지근하면 안 된다.<br>성한 것만 챙겨 나왔다. 문을 닫는데 구석에서 통 하나가 혼자 달그락했다.<br><br>먹을 것과 살아 있는 것을 가르는 손. 부엌 손이 여기서는 그 일부터 한다는 걸 알았다.`,
      ng:`옮기다가 부푼 통 하나가 손안에서 터졌다.<br><br>뚜껑이 튀고 안의 것이 손목에 감겼다. 지렁이 같은데 차다. 털어 내고 발로 밟았다.<br>밟힌 것이 터지며 신 냄새가 퍼졌다. 바닥이 그 자리만 하얗게 일어났다. 손목에 감겼던 자리가 밤새 가려웠다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'S1', t:'배양실 — 단내',
  x:`수조가 줄지어 선 방이다. 반은 깨졌고 반은 차 있다.<br><br>
    찬 수조의 액이 단내를 풍긴다. 조청 같은, 깊고 무거운 단내.<br>
    다들 허기져 있다. 누가 침을 삼켰다.<br><br>
    단내 중에는 살 삭는 단내가 있다. 부엌에서는 그걸 혀보다 먼저 코로 배운다.`,
  o:[
    { l:'① 한 방울 찍어 손등에 올려 본다.', k:'sense', dc:24,
      ok:`새끼손가락으로 한 방울 찍어 손등에 올렸다. 혀는 마지막이다. 늘.<br><br>손등이 금세 간질간질하다. 이어서 따끔하다. 먹는 것이 아니다. 먹이는 것이다. 여기 들어 있던 것들한테 주던 밥.<br>손등을 씻고 일행을 물렸다. 남의 밥상에서는 얻어먹는 게 아니다. 특히 상 주인이 집에 있을 때는.`,
      ng:`한 방울이 손등에서 둥글게 모이더니 살을 파고들었다.<br><br>덴 것처럼 화끈하다. 급히 씻었는데 동전만 하게 벌겋다.<br>단내가 아직도 코에 남아 있다. 허기가 그 냄새를 자꾸 밥이라고 우긴다. 그게 제일 무섭다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 수조 둘레의 자국부터 본다.', k:'gaze', dc:23,
      ok:`수조 가장자리를 살폈다. 테두리에 긁힌 자국이 수없이 나 있다. 안쪽에서 바깥으로.<br><br>그릇 가를 긁는 건 바닥까지 먹겠다는 입이다. 이 수조들은 그릇이고, 그릇을 비운 입들은 밖에 있다.<br>그리고 빈 그릇 앞에는 입이 돌아온다. 밥때가 되면. 그 전에 방을 나왔다.`,
      ng:`자국을 보느라 수조에 너무 가까이 붙었다.<br><br>액 속에서 무언가가 유리에 붙었다. 빨판 같은 것이 이쪽 얼굴 높이에. 유리 안쪽에서.<br>물러나는데 등이 다른 수조에 닿았다. 그 수조에서도 통 하고 소리가 났다. 안쪽에서.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } },
    { l:'③ 병을 꺼내 그 액을 받아 담는다.', k:'luck', dc:26,
      doom:{ title:'밥때', what:'환기구에서 내려온 것에게 채여 올라갑니다', dc:19, sec:40,
        text:`먹을 건 못 돼도 미끼는 된다. 병 주둥이를 수조에 걸치고 기울였다.<br><br>액이 꿀럭꿀럭 병으로 든다. 단내가 방 안에 진하게 퍼진다.<br>천장 환기구 덮개가 소리 없이 열렸다. 단내는 밥 냄새였고, 밥 냄새가 나면 오는 것이 있었다.<br><br>어깨에 갈고리 같은 것이 박혔다. 몸이 붕 뜬다. 병이 바닥에 떨어져 깨지는 게 아래로 보였다. 환기구 테두리가 가까워진다.`,
        dieText:`배양실 바닥에 깨진 병과 엎어진 단내가 남았다.<br><br>천장 환기구에서 한동안 빠는 소리가 났다.<br>단내가 걷히자 소리도 걷혔다. 수조는 하나 더 비어 있었다.` },
      ok:`병을 걸치려다 멈췄다. 수조 수면에 둥근 파문이 돋는다. 천장에서 뭔가 떨어진 것이다. 침이다.<br><br>고개를 들지 않았다. 천천히 병을 거두고 뒷걸음으로 문을 넘었다.<br>문을 닫자마자 방 안에서 무거운 것이 바닥에 내려서는 소리가 났다. 단내는 저것 몫이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'냉동고 — 언 것들',
  x:`냉동고 문이 반 뼘 열려 있다. 안에서 찬 김이 흘러나온다.<br><br>
    갈고리에 언 덩이들이 걸려 있다. 절반은 식량이고 절반은 표본이다. 꼬리표가 다 떨어져 섞였다.<br>
    언 고기는 겉만 봐서는 모른다. 그러나 서리는 안다. 서리는 어는 동안의 일을 다 적어 둔다.<br><br>
    죽어서 언 것과 얼면서 죽은 것은 서리가 다르다.`,
  o:[
    { l:'① 서리 결을 보고 고른다.', k:'gaze', dc:24,
      ok:`덩이마다 서리를 살폈다. 곱게 앉은 서리는 가만히 언 것이고, 결이 일어선 서리는 얼며 몸부림친 것이다.<br><br>고운 서리 두 덩이만 내렸다. 갈라 보니 결 고운 살이다. 식량 쪽이다.<br>결 일어선 것들은 갈고리째 뒀다. 그것들 밑 바닥에만 긁힌 자국이 있었다. 안쪽에서 바깥쪽으로.`,
      ng:`고른 덩이를 녹이는데 살 속에서 거뭇한 게 비쳤다.<br><br>표본 쪽이었다. 서리를 잘못 읽었다.<br>도로 얼릴 수도 없다. 멀리 내다 버렸다. 버린 자리에서 밤새 질척거리는 소리가 났다. 녹는 소리치고는 너무 컸다.`,
      win:{ exp:20, dream:3, item:'짐승 고기' }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 찬 김 속에서 숨서리를 찾는다.', k:'sense', dc:25, wake:1,
      ok:`냉동고 안 공기를 봤다. 찬 김이 한 자리에서만 둥글게 피었다 스러진다. 규칙 있게.<br><br>숨이다. 언 것들 사이에서 무언가 숨을 쉰다. 다 얼지 않은 것이 있다.<br>그쪽 덩이들은 버리고 문가의 것만 챙겨 소리 없이 물러났다. 문은 열린 반 뼘 그대로 뒀다. 닫는 소리가 깨우는 소리다.<br><br>김 서리는 부엌의 글자다. 끓는 것도 읽고, 어는 것도 읽고, 이제 숨는 것도 읽는다.`,
      ng:`숨서리를 찾다가 이쪽 입김이 먼저 깊이 들어갔다.<br><br>안쪽 어둠에서 입김이 마주 나왔다. 길고, 느리게.<br>덩이 하나를 안은 채 뒷걸음쳤다. 문턱에서 발이 미끄러져 엉덩방아를 찧었다. 안쪽 입김이 빨라졌다. 문을 어깨로 밀어 닫고 뛰었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S1', t:'조리실 — 식은 솥',
  x:`연구소 조리실이다. 솥이 그대로 걸려 있다.<br><br>
    안에 든 것은 식었다. 그런데 국자가 솥 가운데 반듯이 꽂혀 있다. 식은 국에 꽂힌 국자는 기울기 마련이다.<br>
    누가 세워 둔 것이다. 아니면 무엇이.<br><br>
    부엌은 쓰는 사람을 닮는다. 이 부엌은 아직 누가 쓴다.`,
  o:[
    { l:'① 솥 바닥 눌은 자국을 읽는다.', k:'gaze', dc:23,
      ok:`국자를 빼고 솥 바닥을 긁어 봤다. 눌은 테가 세 겹이다. 세 번 데우고 세 번 식힌 솥이다. 착륙 뒤에도 누가 데워 먹었다.<br><br>찬장을 보니 그릇 하나만 씻겨 엎어져 있다. 한 사람. 숨어 사는 한 사람이 있다.<br>솥 옆에 말린 고기 한 쪽을 두고 나왔다. 부엌 쓰는 값이다. 선반 뒤 어둠이 조금 움직인 것 같았다.`,
      ng:`긁는데 솥 바닥이 아니라 솥 밑에서 소리가 났다. 긁는 소리에 답하듯.<br><br>솥 받침 아래 바닥 타일이 들려 있다. 그 밑이 비어 있다.<br>국자를 든 채 물러났다. 부엌을 쓰는 게 사람이라고만 생각한 게 잘못이다.`,
      win:{ exp:20, dream:3, item:'소금 덩이' }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 찬장을 뒤져 쓸 것을 챙긴다.', k:'luck', dc:24,
      ok:`찬장을 소리 없이 열었다. 기름, 마른 향신료, 그리고 안쪽 깊이 꿀단지 하나.<br><br>연구소 사람들도 단것은 숨겨 놓고 먹었다. 어디나 같다.<br>단지째 챙겼다. 뚜껑에 먼지가 없다. 누가 최근에 열었다는 뜻이지만, 그 생각은 조리실을 나와서 했다.`,
      ng:`찬장 안쪽으로 손을 깊이 넣는데 손끝에 닿는 것이 선반이 아니다.<br><br>미지근하고, 매끈하다. 그리고 손끝을 마주 더듬는다.<br>손을 뺐다. 찬장 안쪽 어둠에서 병들이 저희끼리 달그락거렸다. 빈손으로 문을 닫았다. 꽉.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S1', t:'표본실 — 알이 든 살',
  x:`선반 아래에서 고기 궤짝을 찾았다. 소금에 절인 큰 덩이들이다.<br><br>
    멀쩡해 보인다. 냄새도 절은 냄새뿐이다.<br>
    그런데 이 건물에서는 멀쩡한 살에 딴것이 씨를 치는 수가 있다. 겉에서는 안 보인다.<br><br>
    칼을 잡은 손이 할 일이 있다. 얇게 썰면 보인다. 뭐든.`,
  o:[
    { l:'① 얇게 저며 불빛에 비춰 본다.', k:'heal', dc:24, wake:1,
      ok:`한 덩이를 종잇장처럼 저몄다. 등불에 비췄다. 살결 사이에 좁쌀만 한 점이 줄지어 비친다. 결을 따라. 심은 것처럼.<br><br>점 박힌 덩이들을 다 가려냈다. 궤짝 맨 아래 두 덩이만 깨끗했다.<br>깨끗한 것만 챙겼다. 점 박힌 것들은 소금을 더 퍼붓고 뚜껑을 못질했다.<br><br>얇게 썰수록 잘 보인다. 칼이 눈이 되는 순간이 있다. 그 순간이 손에 남았다.`,
      ng:`저미다가 칼끝이 점 하나를 갈랐다.<br><br>점이 터지며 실 같은 것이 칼날을 타고 올라왔다. 칼을 던졌다.<br>궤짝째 버리고 물러났다. 궤짝 안에서 소금 쓸리는 소리가 한참 났다. 저희끼리 자리를 바꾸는 소리.`,
      win:{ exp:22, dream:3, item:'짐승 고기' }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 통째로 버리자고 잘라 말한다.', k:'steady', dc:23,
      ok:`허기진 눈들이 궤짝에 붙어 있다. 잘라 말했다. 여기 살은 안 먹는다. 출처 모르는 고기는 굶는 것만 못하다.<br><br>원망 소리가 나왔지만 밀어붙였다. 대신 봇짐의 마지막 말린 고기를 풀었다.<br>이틀 뒤 복도에서 그 궤짝을 다시 봤다. 누가 끌고 간 자국과 함께. 뚜껑이 안쪽에서 뜯겨 있었다.`,
      ng:`말은 했는데 밤에 한 사람이 몰래 한 점을 베어 먹었다.<br><br>새벽부터 그 사람이 식은땀을 흘린다. 배가 꾸륵거리는데 제 배 소리 같지 않다고 한다.<br>쓴 약초를 달여 다 게우게 했다. 게운 것 속에 점 같은 것이 섞여 있었다. 움직이는 점이.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ hp:-26, mind:-18 } }
  ] },

{ at:'S1', t:'환기구 아래 — 더운 밥 한 끼',
  x:`다친 사람이 사흘째 찬 것만 먹었다. 몸이 상처보다 추위에 진다.<br><br>
    더운 국 한 그릇이면 살릴 수 있다. 끓이면 냄새가 난다.<br>
    이 건물의 냄새는 환기구를 탄다. 환기구는 다 이어져 있다. 둥지까지.<br><br>
    그러니까 이건 불 피우는 일이 아니다. 냄새를 어디로 보낼지 정하는 일이다.`,
  o:[
    { l:'① 격실 문을 닫아 바람 길부터 끊는다.', k:'fix', dc:25,
      ok:`작은 격실을 골라 문을 닫았다. 환기구 덮개는 젖은 천으로 틀어막았다. 공기가 죽은 방이 됐다.<br><br>그 안에서 빠르게 끓였다. 김이 천장에 맺혀 도로 떨어진다. 냄새가 방을 못 나간다.<br>다친 사람이 더운 국을 넘겼다. 사흘 만에 얼굴에 핏기가 돈다. 그릇을 다 비우고 나서 천을 걷고 문을 열었다. 복도는 모르고 지나간 한 끼다.`,
      ng:`문을 닫는데 경첩이 길게 울었다. 끼이익.<br><br>건물 어딘가에서 같은 소리가 답했다. 쇠 우는 소리. 더 큰 것이.<br>불도 못 피우고 격실에서 숨만 죽였다. 복도를 무거운 것이 지나갔다. 두 번. 다친 사람은 그날도 찬 것을 먹었다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 소독약 냄새 밑에서 끓인다.', k:'hide', dc:24, wake:1,
      ok:`소독약이 엎어져 코를 찌르는 방을 골랐다. 그 냄새 한가운데에 솥을 걸었다.<br><br>국 냄새가 소독약에 깔려 죽는다. 독한 냄새는 순한 냄새의 지붕이 된다.<br>환기구로는 소독약 냄새만 올라갔다. 그건 저것들도 싫어하는 냄새다.<br><br>부엌 밖의 냄새로 부엌 냄새를 가리는 법. 거꾸로 쓰는 간이다. 코가 하나 더 늘어난 셈이다.`,
      ng:`소독약 냄새에 이쪽 눈이 먼저 맵다. 눈물이 줄줄 난다.<br><br>간을 봐야 하는데 혀도 코도 마비됐다. 국이 짠지 싱거운지 모르겠다.<br>끓이긴 끓였다. 소금 국이 됐다. 다친 사람이 반도 못 넘기고 그릇을 놓았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-16 } },
    { l:'③ 환기구 바로 밑에서 후딱 끓여 치운다.', k:'luck', dc:26,
      doom:{ title:'냄새 길', what:'환기구 속으로 끌려 올라갑니다', dc:20, sec:35,
        text:`시간이 없다. 환기구고 뭐고 가장 가까운 자리에 솥을 걸고 불을 댕겼다.<br><br>국이 끓는다. 좋은 냄새다. 그 냄새가 곧장 환기구로 빨려 올라가는 게 눈에 보였다. 김이 한 줄로.<br>국자를 든 채 올려다본 순간 환기구에서 팔이 내려왔다. 팔이라고 부를 수밖에 없는 것이.<br><br>멱살이 잡혔다. 발이 바닥에서 떨어진다. 끓는 솥이 점점 작아진다. 환기구 테두리에 어깨가 끼었다가, 뼈 소리와 함께 통과했다.`,
        dieText:`환기구 아래 솥은 그대로 끓고 있었다.<br><br>일행이 불을 껐다. 국은 아무도 먹지 않았다.<br>그날 밤 환기구에서 국 냄새가 도로 내려왔다. 식은 국 냄새에 섞여서, 다른 냄새도.` },
      ok:`솥을 걸다가 환기구에서 바람이 거꾸로 부는 걸 느꼈다. 빨아들이는 바람이다. 숨처럼. 규칙 있게.<br><br>불을 안 댕기고 솥을 거뒀다. 숨 쉬는 관 밑에서는 밥을 안 짓는다.<br>세 방 건너 구석에서 작게 끓였다. 다친 사람이 더운 것을 넘겼다. 늦었지만 넘겼다.`,
      win:{ exp:22, dream:3, hp:6 } }
  ] },

{ at:'S1', t:'급수관 — 물 긷기',
  x:`벽을 따라 급수관이 지나간다. 연구소의 물이다.<br><br>
    꼭지가 군데군데 달렸다. 물만 있으면 끓이고 씻고 살 수 있다.<br>
    문제는 소리다. 빈 관은 울린다. 건물 전체가 관으로 이어져 있고, 관 소리는 어디서든 들린다.<br><br>
    물 긷는 일이 목숨 거는 일이 되는 데가 있다. 여기가 그렇다.`,
  o:[
    { l:'① 꼭지를 천으로 감싸 소리 없이 연다.', k:'fix', dc:23,
      ok:`꼭지에 천을 두껍게 감고 반의반 바퀴씩 돌렸다. 물이 실처럼 가늘게 나온다. 천을 타고 소리 없이.<br><br>병 세 개를 채우는 데 오래 걸렸다. 조급한 만큼 더 천천히 했다.<br>잠글 때도 반의반 바퀴씩. 관은 끝까지 조용했다. 조용한 물이 제일 맛있는 물이다.`,
      ng:`셋째 병에서 손이 지쳐 꼭지를 너무 돌렸다.<br><br>관이 울었다. 쿵, 쿠웅. 수격이다. 울림이 벽을 타고 건물 끝까지 달려갔다.<br>그리고 건물 끝에서 무언가가 관을 두 번 두드렸다. 답장이다. 병을 안고 뛰었다.`,
      win:{ exp:20, dream:2, item:'맑은 물' }, lose:{ hp:-26, mind:-14 } },
    { l:'② 관을 손끝으로 짚어 물 찬 데를 찾는다.', k:'sense', dc:24,
      ok:`관에 손바닥을 대고 따라 걸었다. 빈 관은 가볍게 떨고, 물 찬 관은 묵직하게 조용하다.<br><br>물 찬 가지관을 찾았다. 제일 낮은 꼭지에서 받으면 울리지도 않는다.<br>거기서 병을 다 채웠다. 두드려 보지 않고도 아는 것. 그게 손끝의 일이다.`,
      ng:`짚어 가는데 관이 미지근해졌다. 물은 미지근할 수 있다. 그런데 이 미지근함은 자리를 옮긴다. 손바닥을 따라서.<br><br>관 속에서 무언가가 같이 걷고 있다.<br>손을 뗐다. 관 안쪽에서 손 뗀 자리를 톡, 톡, 두드렸다. 물은 다른 데서 받기로 했다.`,
      win:{ exp:18, dream:3, item:'맑은 물' }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S2', t:'잠긴 양치 숲 — 물고기',
  x:`양치 숲 절반이 물에 잠겼다. 무릎 깊이의 검은 물이다.<br><br>
    물속에 고기 그림자가 지나다닌다. 굵다. 한 마리면 두 끼다.<br>
    물에 들어가면 잡을 수 있다. 그리고 이 물은 큰 것의 마당이다. 물에 들어간 것들이 어떻게 됐는지는 아까 봤다.<br><br>
    물가에서 물속 것을 잡는 법. 그게 오늘 부엌의 숙제다.`,
  o:[
    { l:'① 물가에 손낚시를 걸어 두고 물러난다.', k:'fix', dc:23,
      ok:`고사리 줄기를 꼬아 줄을 내고, 미끼를 달아 물가 뿌리에 묶었다. 세 군데.<br><br>물러나 기다렸다. 반나절에 두 줄이 당겨졌다. 굵은 놈들이다.<br>발 한 번 안 적시고 두 끼를 벌었다. 부엌은 기다릴 줄 아는 쪽이 이긴다.`,
      ng:`한 줄이 당겨지는데 당기는 힘이 고기 힘이 아니다.<br><br>묶어 둔 뿌리째 뽑혀 물속으로 끌려 들어갔다. 줄도, 미끼도, 뿌리도.<br>물 밑에서 그것들을 씹는 소리가 났다. 낚시가 아니라 상납이 됐다.`,
      win:{ exp:20, dream:2, item:'민물고기' }, lose:{ hp:-26, mind:-14 } },
    { l:'② 큰물에서 끊긴 웅덩이만 골라 뜬다.', k:'sense', dc:24, wake:1,
      ok:`물을 읽었다. 큰물과 이어진 데는 물빛이 살아 있고, 끊긴 웅덩이는 물빛이 고요하다.<br><br>끊긴 웅덩이에 갇힌 고기들이 있다. 큰 것이 못 들어오는 얕은 그릇.<br>천으로 떠냈다. 세 마리. 끊긴 물에서만 떴다.<br><br>물에도 안방과 마당이 있다. 그 금을 보는 눈이 생겼다. 물고기보다 값진 소득이다.`,
      ng:`끊긴 줄 알았던 웅덩이가 밑으로 이어져 있었다.<br><br>천을 넣는 순간 웅덩이 전체가 한 뼘 꺼졌다. 밑에서 무언가 지나간 것이다.<br>천만 버리고 물러났다. 웅덩이가 다시 차오르는데, 고기들은 한 마리도 돌아오지 않았다. 고기들은 알고 있던 것이다.`,
      win:{ exp:22, dream:3, item:'민물고기' }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S2', t:'울타리 — 먹이 주던 자리',
  x:`울타리 안쪽에 쇠 기둥과 도르래가 서 있다. 녹슨 먹이대다.<br><br>
    옛날에 여기서 먹이를 내렸다. 기둥 아래 뼈가 무더기로 쌓여 있다.<br>
    무리 짓는 것들은 때를 기억한다. 부엌 개도 밥때는 안 잊는다. 하물며 저것들이다.<br><br>
    뼈 무더기는 부엌의 장부다. 읽을 줄 알면 다 적혀 있다.`,
  o:[
    { l:'① 뼈 무더기로 밥때를 읽는다.', k:'gaze', dc:24,
      ok:`울타리 밖에서 뼈를 살폈다. 맨 위 뼈에만 이슬이 안 앉았다. 밤사이 뒤집힌 뼈다. 저것들은 밤에 와서 장부를 뒤진다.<br><br>그럼 낮이 빈다. 해 있을 때 먹이대 옆을 빠르게 지났다.<br>지나고 나서 돌아보니 숲 그늘에 눈들이 줄지어 있었다. 밥때를 기다리는 눈. 장부는 틀리지 않았다.`,
      ng:`뼈를 보느라 바람을 등졌다. 이쪽 냄새가 숲으로 흘러간 것이다.<br><br>숲 그늘에서 낮게 부르는 소리가 났다. 저희끼리 주고받는 소리.<br>밥때가 아니라도 밥이 오면 나오는 법이다. 울타리를 따라 한참을 뛰었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 도르래에 고기를 걸어 때 아닌 밥을 준다.', k:'bond', dc:25,
      ok:`아껴 온 짐승 고기를 도르래에 걸고 녹슨 줄을 당겼다. 끼릭, 끼릭. 먹이대가 수십 년 만에 상을 차렸다.<br><br>숲에서 그것들이 쏟아져 나왔다. 기둥 아래로. 어릴 때 배운 소리는 몸이 먼저 기억한다.<br>그것들이 기둥을 에워싼 사이 반대쪽으로 다 건넜다. 한 끼 값으로 길 하나를 샀다. 부엌에서는 남는 장사다.`,
      ng:`줄을 당기는데 그것들이 고기 쪽으로 가지 않았다.<br><br>고기는 쳐다도 안 보고 줄을 따라 눈을 옮긴다. 줄 끝의 손까지.<br>매달린 밥보다 밥 주는 손을 기억하는 것들이다. 영리하다. 제일 나쁜 종류로. 고기를 버리고 뛰었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, spirit:-18 } },
    { l:'③ 뼈 무더기에서 쓸 것을 찾아 들어간다.', k:'luck', dc:25,
      doom:{ title:'장부 도둑', what:'수풀 속으로 물려 끌려갑니다', dc:19, sec:40,
        text:`뼈 사이에 쇠붙이들이 보였다. 칼, 고리, 통조림. 먹이와 같이 떨어진 것들이다. 울타리를 넘어 들어갔다.<br><br>통조림 두 개를 주웠을 때 뼈 무더기 꼭대기가 무너졌다. 무너진 게 아니다. 일어난 것이다. 무더기 속에서 자던 것이.<br>종아리를 물렸다. 이빨이 뼈까지 닿는다.<br><br>그대로 수풀 쪽으로 끌려간다. 뼈 무더기는 저것들의 곳간이었다. 곳간 도둑은 어느 부엌에서든 용서가 없다.`,
        dieText:`먹이대 아래 뼈 무더기가 한 뼘 높아졌다.<br><br>맨 위의 뼈는 아직 희지 않다.<br>무리는 곳간을 지킨다. 오늘 밤도 하나가 그 위에서 잔다.` },
      ok:`울타리에 손을 얹고 멈췄다. 뼈 무더기 밑동이 느리게 오르내리고 있었다. 숨이다.<br><br>곳간에는 곳간지기가 있다. 자는 지기를 넘어 담을 일이 아니다.<br>손에 닿는 데 떨어진 통조림 하나만 막대로 끌어당겨 챙겼다. 지기는 깨지 않았다.`,
      win:{ exp:20, dream:3, item:'말린 고기' } }
  ] },

{ at:'S2', t:'풀밭 — 둥지의 알',
  x:`양치 덤불 가운데 둥지가 있다. 흙과 줄기를 눌러 쌓은 둥근 둑.<br><br>
    안에 알이 여남은 개 모여 있다. 하나가 솥만 하다. 한 알이면 다섯이 먹는다.<br>
    둥지는 비어 있다. 지금은.<br><br>
    알 도둑은 어느 마당에서든 제일 미움받는 도둑이다. 그리고 어미들은 센다. 제 알을.`,
  o:[
    { l:'① 가장자리의 식은 알 하나만 집는다.', k:'hide', dc:25, wake:1,
      ok:`알마다 손등을 대 봤다. 가운데 것들은 미지근하다. 산 알이다. 가장자리 하나만 차다.<br><br>식은 알은 어미가 굴려 낸 알이다. 품기를 포기한 것. 그건 세지 않는다.<br>그 하나만 안고 나왔다. 저녁에 쪄서 나눴다. 다섯이 배불렀다.<br><br>버린 것과 지키는 것을 손등으로 가리는 법. 남의 부엌에서 얻어 올 수 있는 건 버린 것까지다. 그 금을 배웠다.`,
      ng:`차다고 집은 알이 품에서 미지근해졌다. 식은 게 아니라 갓 식는 중이었다.<br><br>둥지 쪽에서 긴 울음이 났다. 세는 소리다.<br>알을 둑 위에 도로 올려놓고 덤불을 굴러 나왔다. 울음이 밤새 풀밭을 돌았다. 하나, 둘, 세는 것처럼.`,
      win:{ exp:22, dream:3, hp:8 }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 알에 손대려는 일행을 막아선다.', k:'steady', dc:23,
      ok:`큰 알에 손을 뻗는 일행 앞을 막아섰다. 어미는 센다고. 수가 줄면 냄새로 따라온다고.<br><br>배고픈 눈들과 한참 버텼다. 물러선 건 그쪽이다.<br>덤불을 빠져나가며 돌아보니 어미가 돌아와 있었다. 집채만 한 것이 알마다 코를 대고 있다. 세고 있다. 수는 맞았다.`,
      ng:`막는 사이 다른 하나가 작은 알 하나를 품에 넣었다. 뒤늦게 알았다.<br><br>그날 밤부터 울음이 따라왔다. 야영지 둘레를 돌며. 수를 아는 울음이다.<br>알을 들판 한가운데 내놓고 반대로 뛰었다. 알은 돌려줬는데 울음은 사흘을 더 따라왔다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S2', t:'물가 — 흔들리는 물',
  x:`큰물 가에 섰다. 물통을 채워야 한다.<br><br>
    수면에 둥근 물결이 번진다. 멀리서. 일정한 간격으로.<br>
    큰 것이 물속을 걷고 있다. 걸음마다 물이 흔들린다.<br><br>
    끓기 직전의 물도 이렇게 흔들린다. 부엌에서는 그 물을 눈으로 잰다. 여기서도 재면 된다.`,
  o:[
    { l:'① 물결 간격으로 때를 잰다.', k:'sense', dc:24, wake:1,
      ok:`물결을 셌다. 아홉을 세면 한 물결. 걸음이 느리고 고르다. 물결과 물결 사이가 비는 때다.<br><br>그 사이마다 물통 하나씩. 들어갔다 나오고, 들어갔다 나오고. 넷을 채웠다.<br>다섯째를 뜨려는데 간격이 당겨졌다. 일곱. 그만 떴다.<br><br>솥을 보던 눈이 호수를 본다. 끓는 것과 걷는 것은 같은 글자로 적힌다. 흔들림으로.`,
      ng:`세던 물결이 갑자기 멎었다.<br><br>멎은 게 더 나쁘다. 걸음을 멈췄다는 건 서서 듣고 있다는 뜻이다.<br>물통 둘만 들고 엎드려 기었다. 등 뒤에서 물이 산더미로 갈라지는 소리가 났다. 이쪽 아니고 고기 떼 쪽이었다. 이번엔.`,
      win:{ exp:22, dream:3, item:'맑은 물' }, lose:{ hp:-28, mind:-16 } },
    { l:'② 큰물은 포기하고 잎의 빗물을 받는다.', k:'fix', dc:23,
      ok:`물가에서 물러났다. 양치 잎 넓은 것들을 골라 잎끝마다 병을 매달았다.<br><br>밤새 이슬과 빗물이 잎 고랑을 타고 병으로 떨어졌다. 똑. 똑.<br>아침에 병 셋이 찼다. 느린 물이다. 느려서 아무도 안 죽는 물이다.`,
      ng:`매단 병들이 밤바람에 서로 부딪쳤다. 딸그락. 딸그락.<br><br>새벽에 보니 병이 다 바닥에 떨어져 있다. 떨어뜨린 건 바람이 아니다. 잎마다 긁힌 자국이 있다.<br>작은 것들이 다녀갔다. 물은 쏟아졌고, 이쪽 자리가 알려졌다.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ mind:-15, spirit:-16 } }
  ] },

{ at:'S2', t:'고사리 밭 — 먹는 순',
  x:`허리 높이 고사리가 끝없이 펼쳐졌다. 순이 한창이다.<br><br>
    옛 세상 풀이다. 먹는 것과 못 먹는 것이 반반. 이름을 아는 풀이 하나도 없다.<br>
    이름을 모르면 손이 묻는다. 부엌의 오랜 법이다. 꺾어 보고, 맡아 보고, 그다음이 혀다.<br><br>
    서두를 것 없다. 밭은 넓고, 넓은 밭에는 밭 주인이 있기 마련이지만.`,
  o:[
    { l:'① 꺾어서 진부터 본다.', k:'gaze', dc:23,
      ok:`순을 하나씩 꺾었다. 맑은 진이 나는 것과 뿌연 진이 나는 것. 뿌연 쪽은 꺾인 자리가 부글거리며 거품을 낸다.<br><br>맑은 진 쪽만 땄다. 한 아름.<br>삶아서 우려내고 간을 했다. 옛 세상 나물도 나물은 나물이다. 다들 두 그릇씩 먹었다.`,
      ng:`뿌연 진이 손등에 떨어졌다.<br><br>닿은 자리가 지글, 하고 하얗게 일었다. 데인 것처럼.<br>급히 씻었는데 동전만 한 자국이 남았다. 이 밭의 풀은 제 몸을 제가 지킨다. 딴 것 없이 손만 다쳤다.`,
      win:{ exp:20, dream:2, item:'산나물' }, lose:{ hp:-28, mind:-14 } },
    { l:'② 짐승이 뜯은 자리만 골라 딴다.', k:'sense', dc:24,
      ok:`밭을 둘러봤다. 군데군데 순이 뭉텅이로 뜯긴 자리가 있다. 이빨 자국이 둥글다. 풀 먹는 입이다.<br><br>그놈들이 먹은 풀이면 사람도 먹는다. 뜯긴 자리 둘레에서만 땄다.<br>맛을 가리는 건 혀만이 아니다. 먼저 먹은 입을 찾는 눈도 간을 본다.`,
      ng:`뜯긴 자리에서 한참 따는데 발밑 땅이 울렸다.<br><br>풀 먹는 것들이 몰려오는 소리가 아니다. 풀 먹는 것들을 먹는 것이 오는 소리다.<br>좋은 풀밭은 좋은 사냥터다. 그 생각을 너무 늦게 했다. 나물 반을 흘리며 뛰었다.`,
      win:{ exp:20, dream:3, item:'산나물' }, lose:{ hp:-30, spirit:-16 } }
  ] },

{ at:'S2', t:'승강기 앞 — 남은 식량',
  x:`낡은 승강기가 보이는 둔덕이다. 저기까지 마지막 들판 하나.<br><br>
    승강기는 부르면 올라오는 데 한참 걸린다고 했다. 기다리는 동안이 제일 길다.<br>
    봇짐의 식량을 셌다. 다 짊어지고는 못 뛴다.<br><br>
    부엌의 마지막 일은 늘 같다. 남은 것을 어떻게 쓰고 갈 것인가.`,
  o:[
    { l:'① 지금 다 먹인다.', k:'fix', dc:23,
      ok:`둔덕 그늘에서 남은 것을 다 풀었다. 아끼던 것까지. 지금부터는 뱃속에 든 것만 제 것이다.<br><br>다들 꾸역꾸역 먹었다. 배가 차니 손 떨림이 멎는다.<br>봇짐이 반으로 줄었다. 가벼운 짐과 부른 배. 뛰는 데는 그 둘이면 된다.`,
      ng:`먹이는 데 너무 오래 걸렸다. 해가 기울었다.<br><br>그늘이 길어지자 들판 저쪽 수풀도 길어졌다. 길어진 수풀이 움직였다.<br>마지막 몇 입은 뛰면서 삼켰다. 체한 채로 뛰는 건 굶고 뛰는 것보다 나쁘다.`,
      win:{ exp:20, dream:2, hp:8 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 식량 반을 바람맞이에 뿌려 코를 묶는다.', k:'heal', dc:25, wake:1,
      ok:`식량 반을 덜어 바람 불어오는 쪽 멀리, 셋으로 나눠 뿌렸다. 냄새 나는 것부터.<br><br>들판의 코들이 그쪽으로 몰렸다. 셋으로 갈라져서. 서로 으르렁대며.<br>그 사이 들판을 질러 승강기에 붙었다. 먹이는 손은 사람만 먹이는 게 아니다. 길도 먹인다.<br><br>밥이 방패가 되는 걸 봤다. 부엌칼보다 긴 칼이 부엌에 있었다.`,
      ng:`뿌린 자리가 너무 가까웠다.<br><br>코들이 몰려온 자리가 길목과 겹쳤다. 밥상을 길 위에 차린 셈이다.<br>빙 돌아 두 배를 뛰었다. 식량은 반이 됐는데 길은 두 배가 됐다. 밑지는 셈은 부엌에서 제일 아픈 셈이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-18 } },
    { l:'③ 흘린 식량 자루를 주우러 돌아간다.', k:'luck', dc:26,
      doom:{ title:'떨어진 자루', what:'들판의 것에게 물려 수풀로 끌려갑니다', dc:20, sec:35,
        text:`들판 한가운데서 자루 하나를 흘렸다. 사흘 치 식량이다. 돌아섰다.<br><br>자루까지는 금방이었다. 자루를 쥐는 순간 양치 수풀이 양쪽에서 접혔다. 흘린 자루는 흘린 게 아니었다. 놓아 둔 것이었다. 저것들 몫으로 치면.<br>장딴지에 이빨이 박힌다. 자루를 쥔 채 수풀로 끌려간다.<br><br>무리 사냥은 부엌과 같다. 미끼를 놓고, 때를 맞추고, 상을 차린다. 오늘 상에 오른 게 이쪽일 뿐이다.`,
        dieText:`들판 가운데 식량 자루만 남았다.<br><br>그것들은 자루를 열 줄 모른다. 열 필요가 없었다.<br>자루는 다음 미끼로 그 자리에 그대로 놓였다. 수풀이 다시 잠잠해졌다.` },
      ok:`돌아서다 멈췄다. 자루 둘레의 양치 끝이 바람 없이 흔들렸다.<br><br>바람 없이 흔들리는 수풀은 수풀이 아니다. 자루는 이미 미끼다. 이쪽이 놓은 게 아니라 저쪽이 쓰는.<br>자루를 버렸다. 사흘 치보다 다리 두 짝이 비싸다. 그 셈은 금방 끝났다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S2', t:'승강기 — 올라가는 동안',
  x:`쇠창살 승강기가 끼익끼익 올라간다. 느리다.<br><br>
    좁은 통 안에 다섯 사람의 땀내와 피 냄새가 고였다. 바닥 창살 밑으로 들판이 멀어진다.<br>
    멀어지는 들판 가장자리에 그것들이 모여들고 있다. 올려다보면서.<br><br>
    다 끝난 게 아니다. 부엌은 상을 물릴 때까지가 부엌이다.`,
  o:[
    { l:'① 마지막 꿀을 한 숟갈씩 돌린다.', k:'bond', dc:23, wake:1,
      ok:`아껴 온 꿀단지를 꺼냈다. 한 숟갈씩. 다들 손이 떨려서 숟가락이 이에 부딪혔다.<br><br>단것이 들어가자 떨림이 가라앉는다. 단맛은 몸한테 이제 괜찮다고 말해 주는 맛이다.<br>창살 아래 들판이 작아질 때까지 다들 숟가락을 물고 있었다.<br><br>흔들리는 쇠 바구니 안에서도 상은 차려진다. 손바닥 위에서도. 부엌이 장소가 아니라는 걸 여기서 배웠다.`,
      ng:`떨리는 손에서 단지가 미끄러졌다. 창살 틈으로.<br><br>아래로, 아래로, 떨어져서 퍽. 그것들이 단지로 몰리는 게 보였다.<br>핥고, 부수고, 그리고 일제히 위를 올려다봤다. 단 걸 준 손을 기억하겠다는 눈으로. 승강기는 아직 반도 못 올라갔다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 피 밴 겉옷들을 벗겨 아래로 던진다.', k:'heal', dc:24,
      ok:`피 밴 겉옷과 붕대 겉감을 다 걷었다. 상처는 새 천으로 다시 쌌다. 걷은 것들을 뭉쳐 들판 멀리 던졌다.<br><br>냄새가 통째로 떨어져 나갔다. 그것들이 옷 뭉치를 에워싸는 게 내려다보였다.<br>승강기 안에는 이제 땀내뿐이다. 땀내는 쫓아올 만한 냄새가 아니다. 상을 물렸다. 깨끗하게.`,
      ng:`던진 옷이 바람에 날려 승강기 창살에 걸렸다. 바깥쪽에.<br><br>피 냄새가 승강기에 매달려 같이 올라간다. 아래서 그것들이 쇠 기둥에 앞발을 걸었다.<br>막대로 한참을 밀어 겨우 떨궜다. 그동안 기둥 타는 소리가 두 번, 세 번 가까워졌다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ hp:-26, spirit:-16 } }
  ] }

]);

// ------------------------------------------
// 치유사 (healer) · 마력
// ------------------------------------------
kJob('healer', 'S', [

{ at:'S', t:'쉬는 자리 — 상처를 세는 밤',
  x:`앉자마자 상처부터 셌다. 버릇이다.<br><br>
    벤 것 둘, 긁힌 것 넷, 물린 것 하나. 그런데 물린 자국이 이상하다.<br>
    이빨 자국이 두 줄이 아니라 한 바퀴다. 둥글게. 무는 입이 아니라 무언가를 박는 입이다.<br><br>
    물린 사람은 언제 물렸는지 모른다고 한다. 그게 제일 나쁜 대답이다.`,
  o:[
    { l:'① 마력을 실처럼 넣어 자국 밑을 훑는다.', k:'gaze', dc:24, cost:{ mana:28 },
      ok:`손끝에 마력을 모아 실만큼 가늘게 뽑았다. 둥근 자국 밑으로 흘려 넣었다.<br><br>살 밑에 좁쌀만 한 것이 하나 박혀 있다. 딱딱하고, 아주 느리게 따뜻해지는 중이다.<br>마력으로 감아 당겼다. 바늘 끝 같은 것이 빠져나왔다. 핏방울과 함께. 불에 던지자 탁, 하고 튀었다.<br><br>박은 입은 다시 온다. 박은 자리를 찾으러. 이제 찾을 것이 없다.`,
      ng:`마력 실이 자국 밑에서 뚝 끊겼다. 무언가가 실을 잘랐다.<br><br>안에 있는 것이 마력을 안다. 피하고, 자른다.<br>자국 둘레를 천으로 단단히 눌러 두는 수밖에 없었다. 밤새 그 사람 팔이 혼자 꿈틀, 꿈틀, 했다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 둥근 자국을 통째로 째고 씻어 낸다.', k:'heal', dc:23, wake:1,
      ok:`달군 칼로 둥근 자국을 따라 얕게 쨌다. 그 사람이 이를 물었다. 아프면 산 살이다.<br><br>맑은 물로 안을 씻자 좁쌀만 한 것이 물에 쓸려 나왔다. 아직 여물지 않은 것이다.<br>그다음에 마력으로 닫았다. 빈 살은 금방 닫힌다.<br><br>닫기 전에 비우는 것. 그 순서가 손에 새겨졌다. 여기서는 모든 상처가 주머니일 수 있다. 주머니부터 턴다.`,
      ng:`째는데 자국이 칼을 피해 미끄러졌다. 살갗이 밀린 게 아니라 자국이 움직였다.<br><br>세 번을 긋고 세 번을 놓쳤다. 그사이 자국이 어깨 쪽으로 반 뼘 올라갔다.<br>그 사람 눈에 겁이 가득하다. 괜찮다고 말했다. 괜찮지 않은 걸 둘 다 안다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ hp:-28, spirit:-20 } }
  ] },

{ at:'S', t:'어둠 — 빛나는 손',
  x:`어둠 속에서 하나가 피를 흘린다. 지금 닫아야 한다.<br><br>
    문제는 마력이다. 마력을 쓰면 손끝이 빛난다. 여린 빛이지만 이 어둠에서는 등불이다.<br>
    여기 것들은 빛으로도 온다. 아까 불씨 하나에 둘이 왔다.<br><br>
    빛나지 않게 고치는 법. 아니면 빛나도 안 보이게 고치는 법. 둘 중 하나는 있어야 한다.`,
  o:[
    { l:'① 겉옷 속에 손을 넣고 더듬어 닫는다.', k:'heal', dc:24, wake:1,
      ok:`겉옷을 상처 위에 덮고 그 밑으로 손을 넣었다. 눈 대신 손끝으로 상처 가장자리를 읽었다.<br><br>마력의 빛이 옷 속에서만 돌았다. 밖에서 보면 어둠뿐이다.<br>보지 않고 닫은 첫 상처다. 매듭은 좀 비뚤지만 피는 멎었다.<br><br>눈으로 하던 일을 손끝이 넘겨받았다. 어둠 속 상처는 손끝으로 읽는다. 그 글을 오늘 처음 읽었다.`,
      ng:`옷 속이라 상처 끝을 못 찾았다. 반만 닫혔다.<br><br>반에서 피가 계속 밴다. 옷까지 적시며.<br>결국 다 닫긴 했는데 피 냄새가 퍼질 만큼 퍼졌다. 어둠 저쪽에서 코 고는 소리 같은 것이 멎었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 마력을 빛 아래로 눌러 쓴다.', k:'steady', dc:25, cost:{ mana:30 },
      ok:`마력을 손끝에 모으되 타오르지 않게 눌렀다. 깊은 숨으로, 끓기 전의 물처럼.<br><br>빛이 손톱 밑에서만 가물거렸다. 반딧불이만큼도 안 된다.<br>느리게, 어둡게, 상처를 닫았다. 평소의 세 배가 걸렸고 아무것도 오지 않았다.`,
      ng:`누르던 마력이 한순간 튀었다. 손끝이 번쩍, 했다.<br><br>찰나였다. 그런데 어둠 저쪽에서 무언가가 그 찰나에 고개를 돌렸다. 눈이 빛을 되쏘았다. 둘.<br>상처를 반만 닫고 다 같이 자리를 옮겼다. 피 흘리는 사람을 부축한 채로.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'③ 빛나는 손을 미끼로 반대쪽에 흘린다.', k:'hide', dc:25,
      ok:`왼손에 마력을 모아 환하게 켰다. 그리고 그 손만 바위 틈에 밀어 넣고 흔들었다. 빛이 틈으로 새어 저쪽 벽에 어른거린다.<br><br>어둠 속의 것이 그 어른거림 쪽으로 미끄러져 갔다.<br>그사이 오른손으로 상처를 닫았다. 빛은 저쪽, 일은 이쪽. 손이 둘이라 다행이다.`,
      ng:`빛을 본 것이 어른거림이 아니라 빛의 뿌리 쪽으로 왔다. 곧장.<br><br>왼손을 빼고 굴렀다. 바위 틈에 무언가 박히는 소리가 났다. 손 있던 자리에.<br>상처는 뛰면서 눌렀다. 누른 손가락 사이로 피가 새어 나왔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-16 } }
  ] },

{ at:'S', t:'걸음 — 저는 다리',
  x:`하나가 다리를 전다. 발목이 부었다.<br><br>
    여기 것들은 무리를 통째로 안 본다. 저는 것부터 본다. 느린 것, 처지는 것, 박자가 다른 것.<br>
    아까부터 뒤쪽 어둠이 그 사람 박자에 맞춰 따라오고 있다.<br><br>
    상처를 고치는 게 아니라 걸음을 고쳐야 한다. 지금은.`,
  o:[
    { l:'① 마력으로 발목을 굳혀 박자부터 맞춘다.', k:'heal', dc:24, cost:{ mana:27 }, wake:1,
      ok:`부은 발목에 마력을 감아 부목처럼 굳혔다. 낫는 건 아니다. 그냥 안 꺾이게.<br><br>그 사람 걸음이 박자를 되찾았다. 절뚝임이 사라지자 뒤쪽 어둠이 혼란스러워졌다. 점찍은 것이 무리 속으로 사라졌으니까.<br>따라오던 기척이 반 굽이쯤에서 떨어져 나갔다.<br><br>치료에는 순서가 있다. 낫게 하는 것보다 급한 게 있다. 사냥감 표를 떼는 것. 그 순서를 여기서 배웠다.`,
      ng:`굳힌 마력이 반 굽이 만에 풀렸다. 절뚝임이 돌아왔다.<br><br>돌아온 절뚝임은 전보다 눈에 띈다. 박자가 한 번 맞았다 깨졌으니까.<br>뒤쪽 기척이 간격을 반으로 줄였다. 그 사람을 가운데 세우고 밤새 걸었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 모두의 걸음을 저는 박자에 맞춘다.', k:'bond', dc:23,
      ok:`앞사람부터 말을 돌렸다. 다 같이 왼발을 끌라고.<br><br>다섯이 다 절뚝이며 걸었다. 뒤쪽 어둠이 박자를 세다 멈췄다. 다 저는 무리에는 점찍을 것이 없다.<br>기척이 떨어져 나간 뒤에도 한참을 그렇게 걸었다. 우스운 걸음이 목숨을 건졌다.`,
      ng:`박자를 맞추다 둘이 발이 엉켜 넘어졌다. 요란하게.<br><br>넘어진 둘이 제일 느린 것이 됐다. 뒤쪽 기척이 둘로 갈라졌다.<br>부축해 일으켜 뛰었다. 절뚝이는 척이 진짜 절뚝임이 될 뻔했다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S', t:'쉬는 자리 — 오르는 열',
  x:`물린 사람한테서 열이 난다. 이마가 끓는다.<br><br>
    헛소리를 시작했다. 작게. 여기서 헛소리는 소리다. 소리는 부른다.<br>
    열은 몸이 싸우는 소리다. 몸이 이기면 내리고, 지면 오른다.<br><br>
    이 열은 아직 안 정해졌다. 저울 가운데 있다. 손을 얹어야 한다.`,
  o:[
    { l:'① 마력을 찬물처럼 돌려 열을 내린다.', k:'heal', dc:24, cost:{ mana:32 },
      ok:`목덜미와 손목에 손을 대고 마력을 차게 돌렸다. 몸속의 열이 마력을 타고 손바닥으로 빠져나온다.<br><br>손바닥이 데일 듯 뜨거워질 때마다 바닥에 짚어 식혔다. 돌에 김이 서렸다.<br>새벽녘에 열이 꺾였다. 헛소리가 잠꼬대가 되고, 잠꼬대가 숨소리가 됐다. 저울이 이쪽으로 기울었다.`,
      ng:`열을 뽑는데 열이 따라 나오지 않는다. 몸이 열을 움켜쥐고 있다.<br><br>몸이 아는 것이다. 이 열이 꺼지면 안에 든 것이 이긴다는 걸.<br>뽑기를 멈추고 물수건만 갈았다. 밤새. 열은 몸한테 맡기고 소리만 맡았다. 입을 막는 손이 미안했다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 입에 천을 물리고 열이 일을 끝내게 둔다.', k:'steady', dc:23,
      ok:`열을 안 건드리기로 했다. 몸이 싸우는 중이면 싸우게 둔다. 대신 소리를 막았다. 입에 천을 물리고 손을 잡았다.<br><br>그 사람이 땀으로 목욕을 했다. 세 번 옷을 갈아입혔다.<br>아침에 열이 저절로 내렸다. 그 사람이 물었다. 내가 뭐라고 했냐고. 아무 말도 못 했다고 답했다. 사실이다. 천 덕분에.`,
      ng:`한밤에 그 사람이 천을 뱉었다. 그리고 또렷하게 말했다. 여기 있다고. 크게.<br><br>제 목소리가 아니었다. 열에 들뜬 목소리도 아니었다.<br>급히 입을 막고 자리를 옮겼다. 옮긴 자리에서 그 사람이 울었다. 방금 그 말을 제 귀로 들었다고 했다.`,
      win:{ exp:18, dream:3, spirit:6 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'S', t:'바닥 — 숨이 멎은 사람',
  x:`하나가 쓰러졌다. 숨이 없다.<br><br>
    방금까지 걸었다. 긁힌 상처 하나뿐이었다. 그 긁힌 자리가 검게 번져 있다.<br>
    숨이 멎고 얼마 안 됐다. 돌아올 수 있는 시간이다. 짧지만.<br><br>
    그리고 여기는 트인 자리다. 쓰러진 것 둘레에 모여 앉은 무리. 저것들이 제일 좋아하는 그림이다.`,
  o:[
    { l:'① 그 자리에서 가슴을 누르며 마력을 밀어 넣는다.', k:'heal', dc:25, cost:{ mana:35 }, wake:1,
      ok:`무릎을 꿇고 가슴을 눌렀다. 하나, 둘, 셋. 누를 때마다 마력을 심장으로 밀었다. 불씨 살리듯.<br><br>넷을 셀 때 일행에게 등을 맡겼다. 지켜 달라고. 보는 일은 저들 몫, 살리는 일은 이쪽 몫.<br>아홉째에 그 사람이 숨을 토했다. 검게 번지던 것도 숨과 함께 멎었다.<br><br>쪼개서 맡기는 법을 배웠다. 살리는 손은 둘레를 볼 수 없다. 둘레를 내주고 손에만 있는 것. 그게 이 일의 자세다.`,
      ng:`다섯째에 숨이 돌아오지 않았다. 열째에도.<br><br>마력이 심장에서 자꾸 미끄러진다. 무언가가 먼저 자리를 잡고 있다.<br>열다섯째에 그 사람이 숨을 쉬었다. 돌아는 왔다. 그런데 눈 뜨는 데 반나절이 걸렸고, 그동안 번갈아 업고 걸었다. 트인 자리를 세 번 지나며.`,
      win:{ exp:24, dream:4, hp:6 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 먼저 바위 뒤로 끌고 가서 살린다.', k:'evade', dc:24,
      ok:`겨드랑이를 끼고 바위 뒤까지 끌었다. 여섯 걸음. 길어야 숨 두 번 치는 시간이다.<br><br>가려진 자리에서 가슴을 눌렀다. 마력을 밀었다. 일곱째에 숨이 터졌다.<br>바위 너머로 들판을 봤다. 아까 그 자리에 벌써 그림자 둘이 와 있었다. 쓰러졌던 자리의 냄새를 맡으며.`,
      ng:`끄는 데 너무 걸렸다. 바위 뒤에 눕혔을 때는 입술이 파랬다.<br><br>눌렀다. 밀었다. 스물을 셌다.<br>스물하나에 겨우 숨이 붙었다. 붙긴 붙었는데 가늘다. 끌던 여섯 걸음이 자꾸 생각난다. 그 여섯 걸음이 맞았는지.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-18 } },
    { l:'③ 들쳐 업고 뛰면서 살릴 자리를 찾는다.', k:'luck', dc:25,
      doom:{ title:'트인 자리', what:'업힌 사람째 덮쳐져 끌려갑니다', dc:19, sec:45,
        text:`업었다. 숨 없는 몸은 생각보다 무겁다. 뛰었다. 가릴 데를 찾으며.<br><br>반도 못 가서 알았다. 숨 없는 것을 업고 뛰는 등은, 저것들 눈에 상처 입은 것 둘로 보인다는 걸.<br>옆에서 그림자가 덮쳤다. 업힌 무게째 넘어갔다.<br><br>끌려간다. 등에 업힌 사람과 한 덩이로. 놓을 수가 없다. 놓으면 이 사람은 두 번 죽는다.`,
        dieText:`들판에 업던 끈만 남았다.<br><br>둘을 한꺼번에 끌고 가는 자국이 수풀까지 이어졌다.<br>살리려던 사람과 살리던 사람. 저것들한테는 그냥 두 끼다.` },
      ok:`업고 세 걸음 뛰다 멈췄다. 이대로는 등이 과녁이다.<br><br>제일 가까운 움푹한 데로 미끄러져 들어갔다. 가린 데가 아니라 낮은 데. 그거면 됐다.<br>거기서 눌렀다. 밀었다. 여덟째에 등에서 숨소리가 났다. 업힌 채로 살아난 첫 사람이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'어둠 — 심장 소리',
  x:`벽에 붙어 숨을 죽였다. 저쪽 어둠에 그것이 서 있다.<br><br>
    숨은 죽일 수 있다. 심장은 못 죽인다. 겁에 질린 심장 다섯이 북처럼 뛴다.<br>
    이 어둠의 것들은 가슴속 북소리를 듣는다고 했다. 믿지 않았는데, 그것의 고개가 소리 따라 까딱이는 걸 보니 믿게 된다.<br><br>
    심장을 다루는 손은 여기 하나뿐이다.`,
  o:[
    { l:'① 한 사람씩 가슴에 손을 대어 박동을 늦춘다.', k:'heal', dc:25, cost:{ mana:33 }, wake:1,
      ok:`옆 사람 가슴에 손바닥을 댔다. 마력을 느리게, 느리게 돌렸다. 자장가 치는 박자로.<br><br>북 치던 심장이 걸음 박자로 내려온다. 한 사람, 또 한 사람. 다섯 심장이 다 낮아졌다.<br>그것의 고개가 까딱임을 멈췄다. 듣던 것이 사라졌으니까. 그것은 빈 어둠을 한참 노려보다 갔다.<br><br>심장을 빠르게 하는 법은 알고 있었다. 늦추는 법은 오늘 배웠다. 같은 손, 반대 방향. 치유는 양쪽으로 간다.`,
      ng:`넷째 사람 심장이 손 밑에서 오히려 뛰었다. 손이 닿아서. 놀라서.<br><br>북소리 하나가 유난히 커졌다. 그것의 고개가 딱 멈췄다. 넷째 쪽을 향해.<br>손을 뗀 채 다 같이 숨을 참았다. 그것이 세 걸음 다가왔다 돌아갔다. 셋째 걸음은 아직 꿈에 나온다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 제 심장 소리를 키워 저쪽으로 걷는다.', k:'hide', dc:25,
      ok:`제 심장에 마력을 때려 넣었다. 북처럼 울리게. 그리고 벽을 따라 옆으로 걸었다. 일행 반대쪽으로.<br><br>그것이 북소리를 따라왔다. 이쪽으로. 모퉁이 하나를 돌고, 마력을 끊고, 심장을 눌러 죽였다.<br>소리가 사라진 자리에서 그것이 한참 맴돌았다. 그사이 일행도, 이쪽도, 각자 어둠을 빠져나왔다.`,
      ng:`심장을 키우는 것까지는 됐다. 끊는 게 안 됐다.<br><br>겁이 마력보다 셌다. 심장이 제멋대로 뛴다. 북소리가 멎지 않는다.<br>그것이 간격을 좁혀 왔다. 결국 뛰었다. 심장 소리가 발소리보다 컸다. 일행이 반대쪽에서 돌을 던져 주지 않았으면 끝이었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'S', t:'쉬는 자리 — 곪는 상처',
  x:`이틀 전에 닫은 상처가 부풀었다. 가장자리가 벌겋다.<br><br>
    안에서 곪는 것이다. 닫은 자리를 다시 열어야 한다.<br>
    다시 여는 건 처음 여는 것보다 어렵다. 살이 아니라 믿음을 여는 일이라서. 그 사람은 이제 다 나은 줄 알았다.<br><br>
    그리고 고름 냄새는 피 냄새보다 멀리 간다. 여기서는.`,
  o:[
    { l:'① 솔직하게 말하고 다시 연다.', k:'heal', dc:23, wake:1,
      ok:`보여 줬다. 부푼 자리, 벌건 테두리. 안에서 곪았고, 열어야 하고, 아플 거라고.<br><br>그 사람이 한참 보다가 고개를 끄덕였다. 칼을 달구고, 열고, 짜내고, 씻었다. 비명 대신 신음 한 번.<br>고름은 천에 받아 바로 태웠다. 냄새까지 태웠다.<br><br>두 번 여는 상처는 말로 먼저 연다. 그걸 알았다. 살갗보다 먼저 열리는 게 있다.`,
      ng:`말을 꺼내자 그 사람이 팔을 뒤로 뺐다. 다 나았다고. 건드리지 말라고.<br><br>하루를 더 끌었다. 부푼 것이 손바닥만 해졌다.<br>결국 열긴 열었다. 하루 전이면 반 뼘이었을 칼자국이 한 뼘이 됐다. 미룬 값은 늘 살로 치른다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 마력으로 안쪽 고름만 삭인다.', k:'fix', dc:25, cost:{ mana:36 },
      ok:`열지 않기로 했다. 마력을 좁게 벼려 살갗 밑으로 넣고, 고인 것을 조금씩 태워 삭였다.<br><br>겉에서 보면 손을 얹고 있는 것뿐이다. 반나절을 그렇게 앉아 있었다.<br>부기가 숨 쉬듯 천천히 내려앉았다. 흉도 없고 냄새도 없다. 마력은 많이 썼다. 조용한 것은 비싸다.`,
      ng:`삭이던 마력이 너무 깊이 들어갔다. 성한 살까지 데웠다.<br><br>그 사람이 펄쩍 뛰었다. 속에서 덴 것이다.<br>결국 칼로 열었다. 처음부터 열 것을. 마력만 버리고 흉은 흉대로 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S', t:'통로 — 옮기면 안 되는 몸',
  x:`허리를 다친 사람이 있다. 움직이면 안 되는 상처다.<br><br>
    그런데 여기 머물러도 안 된다. 이 통로는 그것들이 오가는 길이다. 바닥의 긁힌 자국이 그렇게 말한다.<br>
    옮기면 부러진 데가 속을 찌른다. 안 옮기면 밤이 온다.<br><br>
    둘 다 안 되는 날이 있다. 그런 날이 치유사의 날이다.`,
  o:[
    { l:'① 마력으로 속을 받친 채 업는다.', k:'heal', dc:25, cost:{ mana:38 },
      ok:`부러진 자리 둘레에 마력을 평평하게 깔았다. 들것처럼. 살 안쪽에 대는 들것이다.<br><br>그대로 업었다. 걸음마다 마력 들것이 출렁임을 받아 낸다. 이쪽 마력이 출렁일 때마다 깎여 나간다.<br>통로 끝까지 받쳐 갔다. 내려놓고 보니 속은 다친 그대로, 더 다친 데는 없다. 마력은 바닥났다. 바꿀 만한 값이다.`,
      ng:`반쯤 갔을 때 마력 들것이 출렁 끊겼다.<br><br>업힌 사람이 숨을 삼켰다. 속 어딘가가 찔린 것이다.<br>그 자리에 내려 다시 깔고, 다시 업었다. 통로 끝에 닿았을 때 그 사람 이마가 식은땀으로 번들거렸다. 이쪽도.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 통로 바닥 긁힌 자국의 때를 읽는다.', k:'gaze', dc:24,
      ok:`엎드려 자국을 봤다. 긁힌 골에 먼지가 앉았다. 오늘 것이 아니다. 제일 새 자국도 이슬에 씻긴 지 오래다.<br><br>길을 바꾼 것이다, 그것들이. 이 통로는 버려진 길이다.<br>그럼 오늘 밤은 여기가 제일 안전하다. 다친 사람을 안 옮기는 쪽으로 정했다. 자국이 알려 준 답이다.`,
      ng:`자국은 오래됐다. 거기까지는 맞았다.<br><br>새벽에 안 것은, 길을 버린 이유다. 더 큰 것이 이 길을 차지했다는 것. 벽의 허물 자국이 그제야 보였다.<br>다친 사람을 담요째 끌고 기었다. 등 뒤 어둠이 허물 벗는 소리를 내는 동안.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S', t:'쉬는 자리 — 가려운 흉터',
  x:`오래전에 닫아 준 흉터가 가렵다고 한다. 지난달에 다친 자리다.<br><br>
    잘 닫힌 흉터였다. 그런데 지금 보니 흉터 가운데가 볼록하다.<br>
    닫을 때는 없던 볼록함이다. 닫힌 문 안쪽에 누가 들어와 산다.<br><br>
    이 땅에 들어온 뒤로 생긴 일이다. 여기서는 닫힌 살도 집이 된다.`,
  o:[
    { l:'① 흉터를 다시 열어 안을 본다.', k:'heal', dc:24, wake:1,
      ok:`달군 칼로 흉터 결을 따라 다시 열었다. 안에 쌀알만 한 것이 웅크리고 있다. 숨구멍을 흉터 쪽으로 내고.<br><br>마력으로 감아 꺼냈다. 꺼내자 그것이 몸을 폈다. 다리가 많다. 불에 던졌다.<br>빈 자리를 씻고 다시 닫았다. 이번 흉터는 평평하다.<br><br>제 손으로 닫은 자리는 제 손이 책임진다. 닫은 문을 다시 여는 손이 참 치유의 손이다. 그걸 이 흉터가 가르쳤다.`,
      ng:`여는데 볼록한 것이 흉터 밑을 떠나 옆으로 이사했다.<br><br>갈빗대 쪽으로. 더 못 쫓는 자리로.<br>연 자리만 도로 닫았다. 그 사람한테는 가려우면 바로 말하라고 했다. 가려움이 움직이면 더 빨리 말하라고.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 볼록한 데를 마력으로 지진다.', k:'break', dc:25, cost:{ mana:34 },
      ok:`열지 않고 끝내기로 했다. 손끝에 마력을 바늘처럼 벼려 볼록한 가운데를 지졌다.<br><br>흉터 밑에서 지직, 하는 느낌이 손끝에 왔다. 볼록함이 꺼졌다.<br>죽은 것은 몸이 알아서 삭인다. 그건 몸의 일이다. 들어온 것을 끝내는 게 이쪽 일이고.`,
      ng:`지지는 순간 그것이 흉터 밖으로 튀어 나왔다. 제 집이 더워지니까.<br><br>바닥에 떨어져 다리 많은 것이 쏜살같이 어둠으로 달아났다.<br>놓쳤다. 어둠 속 어딘가에서 저것이 다음 흉터를 찾을 것이다. 흉터 있는 사람이 여기 다섯이다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-18 } },
    { l:'③ 긁지 말라고만 하고 두고 본다.', k:'luck', dc:25,
      doom:{ title:'볼록한 것', what:'흉터 속 것이 깨어나 숙주째 끌고 갑니다', dc:19, sec:40,
        text:`긁지만 말라고 했다. 하루 더 보기로 했다. 함부로 여는 것도 탈이 나니까.<br><br>한밤에 그 사람이 벌떡 일어났다. 흉터에 손을 얹고. 가려움이 멎었다고 했다. 좋아할 일이 아니다. 다 자라면 안 가렵다.<br>그 사람 몸이 저 혼자 걷기 시작했다. 어둠 쪽으로. 흉터 속의 것이 집을 통째로 몰고 간다.<br><br>팔을 붙잡았다. 끌려간다. 사람 하나 힘이 아니다. 집이 비명을 질렀다. 제 발로 걸으면서.`,
        dieText:`어둠 속에서 흉터 터지는 소리가 났다. 작게.<br><br>다 자란 것은 집을 두고 떠난다.<br>빈집은 아침에 찾았다. 흉터만 열린 채.` },
      ok:`두고 보되 그냥 두지는 않았다. 잘 때 그 사람 흉터 위에 마력 실을 한 가닥 걸어 뒀다. 방울처럼.<br><br>한밤에 실이 당겨졌다. 흉터 밑의 것이 움직이기 시작한 것이다.<br>자던 손이 저절로 움직였다. 깨기 전에 지지고, 깨서 설명했다. 그 사람은 꿈인 줄 알았다고 했다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'어둠 — 상처를 핥는 것',
  x:`밤 자리에서 이상한 소리에 깼다. 핥는 소리다.<br><br>
    다친 사람 발치에 낮고 긴 것이 엎드려 있다. 상처 감은 천을 핥고 있다. 정성스럽게.<br>
    잡아먹는 게 아니다. 아직은. 간을 보는 것이다.<br><br>
    소리치면 그 자리에서 문다. 치유사의 밤은 가끔 이렇게 시작된다.`,
  o:[
    { l:'① 마력을 천에 흘려 쓴맛을 입힌다.', k:'fix', dc:25, cost:{ mana:29 },
      ok:`누운 채로 손끝만 뻗어 천에 마력을 흘렸다. 떫고 쓰게 비튼 마력이다. 약 달일 때 나는 그 맛으로.<br><br>핥던 것이 혀를 뗐다. 캑, 하고 낮게 뱉는 소리.<br>그것이 침을 두어 번 뱉고 어둠으로 돌아갔다. 간을 봤는데 맛이 없었던 것이다. 그 입맛에 오래 남기를.`,
      ng:`마력을 비트는 데 서툴렀다. 쓴맛이 아니라 단맛이 됐다.<br><br>핥던 소리가 빨라졌다. 천이 당겨진다. 다친 사람이 끌리기 시작했다.<br>모두 소리 지르며 일어났다. 그것이 천만 물고 달아났다. 상처가 맨살로 드러났다. 새로 감는 손이 떨렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 제 팔뚝을 그어 냄새를 이쪽으로 끈다.', k:'bond', dc:24,
      ok:`칼로 제 팔뚝을 얕게 그었다. 새 피 냄새. 핥던 고개가 이쪽으로 돌았다.<br><br>피 묻힌 천을 멀리 던졌다. 그것이 천을 쫓아 사라졌다.<br>제 팔은 제가 감았다. 한 손으로 감는 법은 오래전에 익혔다. 이런 밤을 위해 익혀 둔 줄은 몰랐지만.`,
      ng:`긋는 순간 그것이 천이 아니라 팔뚝으로 왔다. 새 피가 더 가까웠으니까.<br><br>구르며 피했다. 어깨를 스쳤다. 스친 자리가 불에 덴 듯하다.<br>일행이 깨어 소리치자 그것이 물러갔다. 미끼가 될 뻔했다. 미끼를 던지는 쪽이 아니라.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'S', t:'갈림길 — 핏자국',
  x:`길바닥에 핏자국이 길게 끌려 있다. 두 갈래 길 중 왼쪽으로.<br><br>
    피를 아는 눈으로 보면 이건 사람 피가 아니다. 색이 너무 검고, 마르는 결이 다르다.<br>
    무언가가 다쳐서 왼쪽으로 끌려갔거나, 기어갔다.<br><br>
    다친 짐승은 제일 위험한 짐승이다. 그건 어느 땅에서나 같다.`,
  o:[
    { l:'① 핏자국의 마름새로 때와 깊이를 읽는다.', k:'gaze', dc:24, wake:1,
      ok:`쪼그려 앉아 자국을 읽었다. 가장자리만 말랐다. 한나절 전. 방울 간격이 뒤로 갈수록 좁다. 점점 느려졌다는 뜻이다.<br><br>이만큼 흘리고 이만큼 느려졌으면, 왼쪽 끝 어디서 멈췄다. 아마 영영.<br>오른쪽 길로 갔다. 피는 거짓말을 안 한다. 읽을 줄만 알면.<br><br>사람 피만 읽던 눈이 남의 피도 읽기 시작했다. 상처는 어느 몸에 났든 같은 글씨다.`,
      ng:`읽던 중에 방울 간격이 이상해졌다. 뒤로 갈수록 넓다. 느려진 게 아니라 빨라졌다.<br><br>다 나아 가는 것이다. 이 피의 주인은.<br>그리고 나아 가는 것은 돌아온다. 제 피 냄새 맡는 것을 잡으러. 읽기를 멈추고 오른쪽으로 서둘렀다. 왼쪽에서 자갈 구르는 소리가 났다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 핏자국을 따라가 끝을 확인한다.', k:'luck', dc:25,
      doom:{ title:'다친 짐승', what:'다친 것에게 물려 굴로 끌려갑니다', dc:19, sec:45,
        text:`확인해야 안심이 된다. 핏자국을 따라 왼쪽으로 갔다.<br><br>자국 끝에 그것이 있었다. 옆구리가 찢긴 채 엎드려서. 숨이 가늘다. 다 죽어 간다. 그렇게 보였다.<br>다 죽어 가는 것이 마지막 힘을 어디에 쓰는지 안다. 알면서 두 걸음을 더 갔다.<br><br>그것이 튀었다. 찢긴 옆구리째. 어깨를 물고 제 굴 쪽으로 끈다. 다친 것은 먹이를 굴에서 먹는다. 천천히 먹어야 하니까.`,
        dieText:`핏자국 끝에 새 핏자국이 겹쳤다.<br><br>검은 피 위에 붉은 피.<br>두 자국 다 같은 굴로 들어갔다. 나온 자국은 없다.` },
      ok:`따라가다 멈췄다. 자국 옆에 다른 자국이 생겼다. 디딘 발자국. 피 주인 것이 아니다. 더 큰 것이 같은 자국을 따라가고 있다.<br><br>다친 것을 쫓는 건 이쪽만이 아니었다.<br>조용히 물러나 오른쪽 길로 갔다. 왼쪽 깊은 데서 비명 같은 소리가 났다. 짐승 것이. 둘 다 저쪽 일이다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'표본실 — 산에 덴 손',
  x:`앞서가던 사람이 비명을 물었다. 깨진 표본병을 짚은 것이다.<br><br>
    병에 든 액이 손바닥에 묻었다. 살이 연기를 낸다. 지글지글.<br>
    데인 게 아니다. 녹는 것이다. 마력으로 닫으려 해도 닫을 가장자리부터 녹는다.<br><br>
    이 건물의 상처는 배운 것과 다르게 군다. 빨리 다시 배워야 한다.`,
  o:[
    { l:'① 물을 들이붓고 녹은 테두리를 잘라 낸다.', k:'heal', dc:25, wake:1,
      ok:`맑은 물을 아낌없이 부었다. 연기가 멎을 때까지. 그다음 녹은 테두리를 칼로 돌려 깎았다. 산 살이 나올 때까지.<br><br>그 사람이 이를 부러져라 물었다. 산 살이 나오자 그제야 마력을 댔다. 닫혔다. 이번엔.<br>녹이는 상처는 먼저 씻고, 그다음 버릴 살을 버리고, 마지막에 닫는다.<br><br>순서를 새로 적었다. 이 땅의 상처에는 이 땅의 순서가 있다. 첫 장을 오늘 썼다.`,
      ng:`물이 모자랐다. 반만 씻겼다.<br><br>닫은 자리 밑에서 남은 액이 계속 녹였다. 겉은 닫히고 속은 뚫리는 상처.<br>다시 열고 다시 씻었다. 두 번 연 손바닥은 그릇을 못 쥔다. 한동안은.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ hp:-30, spirit:-18 } },
    { l:'② 마력 막을 손과 액 사이에 밀어 넣는다.', k:'fix', dc:26, cost:{ mana:38 },
      ok:`마력을 종잇장처럼 펴서 살과 액 사이로 밀어 넣었다. 녹는 것은 마력 막이 대신 녹는다.<br><br>막이 녹는 속도로 마력을 계속 부었다. 밑 빠진 독이다. 그래도 그동안 살은 성하다.<br>일행이 물을 가져올 때까지 버텼다. 씻고 나니 손바닥이 벌겋지만 온전하다. 마력은 바닥났다. 손바닥 값이다.`,
      ng:`막을 펴는 손이 떨렸다. 막에 바늘구멍이 났다.<br><br>그 구멍으로 액이 들었다. 점으로 깊게.<br>점 하나가 뼈 근처까지 갔다. 그 사람 손가락 하나가 오래 굽은 채로 있을 것이다. 바늘구멍 하나 값이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S1', t:'격리 병동 — 두 번 뛰는 가슴',
  x:`병동 침대에 일행을 눕히고 살폈다. 가슴에 손을 얹었는데 손이 멎었다.<br><br>
    박동이 둘이다. 하나는 익은 박자. 하나는 반 박자 늦게 따라오는 작은 것.<br>
    가슴속에 심장이 둘일 수는 없다. 하나는 심장이 아니다.<br><br>
    침대 머리맡 차트에 같은 그림이 그려져 있다. 가슴 속 작은 덩이. 그 옆에 날짜가 셋. 셋째 날짜에 동그라미.`,
  o:[
    { l:'① 마력으로 작은 박동을 재워 둔다.', k:'heal', dc:26, cost:{ mana:40 }, wake:1,
      ok:`작은 박동 둘레에 마력을 이불처럼 덮었다. 죽이려 들면 몸부림친다. 차트의 동그라미가 그 말일 것이다. 재우는 건 다르다.<br><br>느리게, 둔하게, 겨울잠처럼. 작은 박자가 늘어지다 멎은 듯 가라앉았다.<br>시간을 번 것뿐이다. 그래도 번 시간이 걷는 시간이 된다. 업혀 갈 사람이 제 발로 걷는다.<br><br>못 꺼내는 것은 재운다. 치유가 늘 이기는 싸움은 아니라서, 비기는 법도 배워야 한다. 오늘 배웠다.`,
      ng:`덮는 마력이 작은 박동을 건드렸다. 재워지는 대신 깼다.<br><br>박자가 빨라진다. 반 박자 늦던 것이 반 박자 앞선다.<br>그 사람이 가슴을 쥐고 구부러졌다. 마력을 다 부어 겨우 도로 늦췄다. 차트의 셋째 날짜가 자꾸 눈에 밟힌다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 차트를 끝까지 읽는다.', k:'gaze', dc:24,
      ok:`차트를 넘겼다. 그림 밑에 갈겨쓴 글. 끄집어내면 터진다. 식히면 느려진다. 그리고 마지막 장에 크게. 찬 방.<br><br>복도 끝 냉장 격실이 떠올랐다. 그 사람을 담요째 옮겨 찬 방에 한나절 뉘었다.<br>작은 박동이 반의반으로 줄었다. 여기 의사들이 먼저 치른 싸움이다. 남긴 답안지는 읽는 사람 몫이고.`,
      ng:`차트 뒷장이 뜯겨 있다. 뜯긴 자리에 손톱자국.<br><br>누가 답을 가져갔다. 아니면 답이 마음에 안 들었거나.<br>남은 장을 아무리 읽어도 방법이 없다. 아는 것만 늘었다. 사흘. 동그라미. 그 사람 얼굴을 보며 그 말을 삼켰다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-20, spirit:-20 } },
    { l:'③ 지금 갈라서 꺼낸다.', k:'break', dc:26,
      doom:{ title:'셋째 날짜', what:'가슴속 것이 깨어나 숙주째 끌고 갑니다', dc:20, sec:38,
        text:`기다릴수록 자란다. 칼을 달궜다. 작은 박동 바로 위를 갈랐다.<br><br>살을 열자 그것이 보였다. 주먹만 한, 반투명한, 숨 쉬는 것. 칼끝이 닿기 전에 그것이 먼저 움직였다.<br>숙주의 몸이 침대에서 벌떡 일어났다. 눈은 감긴 채다. 열린 가슴을 한 손으로 누르고, 다른 손으로 이쪽 멱살을 끌며 문으로 걷는다.<br><br>복도 끝 어둠으로. 제 둥지로. 수술은 둥지에서 마저 하겠다는 듯이.`,
        dieText:`병동 침대가 비었다.<br><br>복도에 꿰맨 실 한 타래가 풀린 채 이어져 있다. 어둠 속까지.<br>차트 셋째 날짜에 동그라미가 하나 더 생겼다. 잉크가 아직 젖어 있다.` },
      ok:`칼을 대기 전에 작은 박동을 다시 짚었다. 박자가 손끝을 따라온다. 칼 쥔 손 쪽으로 몰린다.<br><br>이것은 칼을 안다. 여기 의사들의 칼을 겪어 봤다는 뜻이다.<br>칼을 거뒀다. 모르는 적과는 트인 데서 싸우지 않는다. 재우는 쪽으로 돌아섰다. 숙주를 살리는 길이 꼭 베는 길은 아니다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'기밀문 — 문틈의 사람',
  x:`기밀문이 닫히다 멈췄다. 사람이 끼어서다. 허리까지.<br><br>
    문 너머에서 비상등이 돌아간다. 문은 계속 닫히려고 웅웅댄다.<br>
    빼내면 으스러진 데가 쏟아진다. 둔 채로는 문이 마저 닫힌다.<br><br>
    문에 끼인 몸은 문이 지혈대다. 그걸 아는 게 치유사다. 빼는 순간부터 시간이 간다.`,
  o:[
    { l:'① 빼기 전에 묶을 것부터 다 준비한다.', k:'heal', dc:25, wake:1,
      ok:`빼자고 달려드는 손들을 멈춰 세웠다. 먼저 천을 찢고, 지혈대를 두 개 만들고, 마력을 손끝에 미리 모았다.<br><br>하나, 둘, 셋에 뺐다. 쏟아지는 것을 준비한 순서대로 막았다. 묶고, 누르고, 마력으로 닫고.<br>문이 등 뒤에서 쿵 닫혔다. 그 사람은 이쪽에 있다. 피도 거의 이쪽에 있다.<br><br>빼는 게 구조가 아니다. 뺀 다음이 구조다. 그 반 박자를 미리 사는 법. 문틈에서 배웠다.`,
      ng:`준비하는 사이 문이 한 칸 더 닫혔다. 끼인 사람이 비명을 질렀다.<br><br>순서고 뭐고 다 같이 잡아 뺐다.<br>쏟아지는 것을 맨손으로 막으며 묶었다. 묶긴 묶었다. 준비 반, 난장판 반. 그 사람은 살았는데 이쪽 손이 한동안 떨렸다.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ hp:-30, spirit:-18 } },
    { l:'② 마력으로 문틀을 받치고 천천히 뺀다.', k:'steady', dc:26, cost:{ mana:39 },
      ok:`문짝과 문틀 사이에 마력을 기둥처럼 괴었다. 문이 마력을 밀고, 마력이 버틴다. 이가 갈리는 무게다.<br><br>버티는 동안 일행이 그 사람을 조금씩 뺐다. 서두르지 않고.<br>다 빠지자 마력을 거뒀다. 문이 쾅 닫혔다. 기둥 하나 값의 마력이 나갔다. 사람 하나가 통째로 남았다.`,
      ng:`괸 마력이 문 힘에 금이 갔다. 버티던 것이 한순간에 주저앉았다.<br><br>문이 반 뼘 내려왔다. 끼인 사람이 짐승 소리를 냈다.<br>마력을 다시 괴고, 이번엔 빠르게 뺐다. 천천히는 사치였다. 뺀 자리가 많이 상했다. 밤새 닫고 또 닫았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S1', t:'표본 선반 — 아직 움직이는 병',
  x:`선반에 병들이 줄지어 있다. 액에 잠긴 것들.<br><br>
    대부분 멈춰 있다. 한 병만 다르다. 병 속의 작은 것이 유리에 손을 대고 있다. 손이라고 부를 수 있다면.<br>
    산 것이다. 몇 년을 저 안에서.<br><br>
    고치는 일을 하는 사람은 산 것 앞을 그냥 못 지나간다. 그게 병이 될 때도 있다. 여기 같은 데서는.`,
  o:[
    { l:'① 병째 들어 숨 쉴 구멍만 내 준다.', k:'bond', dc:25,
      ok:`병을 선반에서 내렸다. 마개를 반만 돌려 숨구멍을 냈다. 꺼내지는 않았다. 몇 년을 액에서 산 것은 액이 집이다.<br><br>안의 것이 구멍 쪽으로 떠올라 한참 머물렀다.<br>병을 어두운 구석, 넘어지지 않을 자리에 뉘어 놓고 나왔다. 살리는 것과 꺼내는 것이 늘 같은 말은 아니다. 그거면 됐다.`,
      ng:`마개를 돌리자 안의 것이 유리를 긁기 시작했다. 미친 듯이.<br><br>구멍이 아니라 밖을 원하는 것이다. 몇 년 치의 밖을.<br>병이 손안에서 요동친다. 바닥에 내려놓고 물러났다. 병이 선반 밑으로 데굴데굴 굴러 들어갔다. 긁는 소리는 밤새 났다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 병 속 것의 상한 데를 유리 너머로 살핀다.', k:'gaze', dc:24,
      ok:`등불을 비춰 병 속을 살폈다. 작은 몸에 꿰맨 자국이 줄줄이다. 열고 닫은 자국. 여러 번.<br><br>이건 표본이 아니라 환자였다. 여기 사람들이 고치려던 것이다. 끝까지.<br>차트 쪽지가 병 바닥에 눌어 있다. 마지막 줄만 읽혔다. 아프게 하지 말 것. 병을 제자리에 반듯이 놓고 나왔다. 그 한 줄이면 동업자다.`,
      ng:`불빛에 병 속 것이 눈을 떴다. 눈이 있었다.<br><br>그리고 그 눈이 이쪽 눈을 똑바로 봤다. 유리 너머로. 몇 년 만의 눈 맞춤일 것이다.<br>불을 내렸는데도 한참을 못 움직였다. 그 눈이 따라왔다. 복도 끝까지. 눈 감으면 지금도 있다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'S1', t:'환기구 아래 — 긁힌 등',
  x:`환기구 밑을 지나던 사람 등에 세 줄 상처가 났다. 위에서 아래로.<br><br>
    본 사람은 없다. 소리도 없었다. 긁힌 당사자도 바람인 줄 알았다고 한다.<br>
    상처가 얕다. 너무 얕다. 할퀴는 것이 힘 조절을 한 것이다.<br><br>
    얕게 긁는 발톱은 표시하는 발톱이다. 제 것이라고 적어 두는.`,
  o:[
    { l:'① 상처 골을 긁어 내고 박박 씻는다.', k:'heal', dc:25, wake:1,
      ok:`세 줄 골을 칼등으로 긁었다. 골 바닥에 기름 같은 것이 발려 있다. 번들거리는, 냄새 없는 기름.<br><br>이게 표시다. 저들끼리는 냄새가 날 것이다. 소금물로 세 번, 독한 술로 한 번 씻었다.<br>그날 밤 환기구에서 무언가 내려와 등 냄새를 맡고 갔다. 빈 종이가 된 등을. 못 읽고 돌아갔다.<br><br>상처에 적힌 것까지 지우는 게 씻는 일이다. 보이는 피만 씻던 손이 보이지 않는 글씨를 배웠다.`,
      ng:`씻는다고 씻었는데 골 하나를 얕게 봤다.<br><br>그 한 줄이 남았다. 한 줄로도 읽히는 모양이다.<br>이틀 뒤 그 사람 등에 네 줄이 늘어 있었다. 더 깊게. 다시 쓴 글씨는 눌러 쓰는 법이다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 같은 기름을 모두의 등에 바른다.', k:'hide', dc:26, cost:{ mana:31 },
      ok:`긁어 낸 기름을 버리지 않았다. 마력으로 늘려 다섯 등에 얇게 폈다.<br><br>다 표시된 것으로 보이게. 찜한 것은 서로 안 건드린다. 무리 규칙이 그렇다면 그 규칙을 쓰면 된다.<br>환기구 밑을 지날 때마다 위에서 코 킁킁대는 소리만 났다. 발톱은 내려오지 않았다. 남의 것은 안 긁는다.`,
      ng:`기름을 늘리다 마력이 섞여 냄새가 변했다.<br><br>표시가 아니라 도전장이 된 모양이다. 환기구 위가 소란해졌다.<br>기름을 다 닦아 내고 뛰었다. 등 다섯이 한동안 서로를 벽 삼아 걸었다. 벽이 제일 안전한 등이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S1', t:'복도 — 하얀 피',
  x:`복도 바닥에 하얀 얼룩이 점점이 떨어져 있다. 피다. 저것들의 피.<br><br>
    떨어진 자리마다 바닥이 움푹 삭았다. 끓지도 않는데 녹인다.<br>
    그리고 앞서가던 사람이 그걸 밟았다. 신발 바닥에서 연기가 오른다.<br><br>
    여기서는 남의 피가 무기다. 피를 다루는 손이 제일 먼저 알아야 하는 것.`,
  o:[
    { l:'① 신발을 그 자리에서 벗겨 던진다.', k:'evade', dc:24,
      ok:`끈을 풀 새도 없다. 칼로 끈을 끊고 신발째 벗겨 던졌다.<br><br>던져진 신발이 복도 저쪽에서 연기를 내며 주저앉았다. 발은 성하다. 양말 바닥만 뜨끈하다.<br>남은 신발 한 짝과 천으로 발을 싸맸다. 절반의 신발. 전부의 발. 남는 셈이다.`,
      ng:`벗기는 사이 한 방울이 양말까지 닿았다.<br><br>발등에 동전만 한 자국. 그 사람이 주저앉았다.<br>물로 씻고 천으로 쌌다. 걷기는 걷는다. 발을 디딜 때마다 숨을 삼키면서. 흰 얼룩 사이를 그 발로 건너는 길이 멀었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 얼룩의 간격으로 다친 것의 길을 읽는다.', k:'gaze', dc:25,
      ok:`하얀 방울의 간격을 읽었다. 넓고, 또 넓고, 갑자기 좁다. 좁아진 데서 벽을 봤다. 벽에 하얀 손자국.<br><br>여기서 쉬었다. 다쳐서 느려진 것이 벽을 짚고.<br>그 방향만 피해서 돌았다. 다친 저것과 마주치는 복도만은 안 된다. 다친 것은 급하고, 급한 것은 문다.`,
      ng:`읽는 데 정신이 팔려 늦게 알았다. 방울이 마르지 않았다는 걸.<br><br>갓 흘린 피다. 주인이 가깝다.<br>복도 끝에서 쇠 긁는 소리가 났다. 벽을 짚으며 오는 소리. 읽은 것을 다 버리고 반대로 뛰었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-18 } },
    { l:'③ 하얀 피를 병에 담아 간다.', k:'luck', dc:26,
      doom:{ title:'피의 주인', what:'돌아온 주인에게 물려 환기구로 끌려갑니다', dc:20, sec:36,
        text:`녹이는 피는 무기가 된다. 잠긴 문도 녹일 것이다. 유리병에 조심조심 담았다.<br><br>반 병쯤 찼을 때 복도의 공기가 바뀌었다. 하얀 방울들이 가늘게 떨고 있다. 제 주인의 발소리에.<br>다친 것이 돌아왔다. 제 피를 줍는 것을 봤다.<br><br>다친 어깨로도 한입에 물렸다. 천장으로 끌어 올려진다. 병이 손에서 떨어져 깨졌다. 하얀 피가 제 주인 밑에서 바닥을 녹였다.`,
        dieText:`복도 바닥에 깨진 병과 녹은 구멍이 남았다.<br><br>환기구 테두리에 하얀 피와 붉은 피가 같이 말라붙었다.<br>저것들은 제 피를 흘린 자리를 기억한다. 주운 손도.` },
      ok:`병 주둥이를 대려다 멈췄다. 하얀 방울이 가늘게 떨고 있다. 바닥이 아니라 방울이.<br><br>발소리다. 멀리서 오는, 이 피 주인의 발소리를 방울이 먼저 듣는 것이다.<br>병을 거두고 샛길로 빠졌다. 피는 주인 곁에 있을 때 제일 위험하다. 사람 피나 저 피나.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'수술실 — 남의 수술대',
  x:`수술실을 찾았다. 기구가 그대로다. 바늘, 실, 집게, 날 선 것들.<br><br>
    다친 사람 둘을 눕힐 자리도 있다. 제대로 볼 수 있는 등불도.<br>
    다만 수술대 위 천장에 환기구가 있다. 덮개 나사가 안쪽에서 풀려 있다.<br><br>
    좋은 방에는 이유가 있다. 비어 있는 좋은 방에는 더 큰 이유가 있다.`,
  o:[
    { l:'① 환기구를 수술대로 막고 일을 본다.', k:'fix', dc:24,
      ok:`빈 수술대 하나를 세워 환기구 밑을 막았다. 쇠 다리가 천장을 단단히 받친다.<br><br>그 밑에서 둘을 꿰맸다. 바늘다운 바늘, 실다운 실. 손이 날개를 달았다.<br>꿰매는 동안 덮개가 두 번 들썩였다. 수술대에 막혀 두 번 다 내려앉았다. 쇠 식는 소리라고 다친 둘한테는 말해 뒀다.`,
      ng:`수술대를 끌다 바퀴가 요란하게 울었다.<br><br>천장 위가 조용해졌다. 그 조용함이 제일 시끄럽다.<br>결국 수술실을 포기하고 복도 구석에서 꿰맸다. 좋은 바늘로 나쁜 자리에서. 바늘 반, 어깨너머 반.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 쓸 만한 기구만 쓸어 담아 나온다.', k:'sense', dc:23,
      ok:`방은 버리고 기구만 챙겼다. 바늘, 실, 집게, 굽은 가위, 그리고 마개 달린 약병 몇 개.<br><br>천으로 겹겹이 싸서 소리를 죽였다.<br>수술은 어디서든 한다. 연장만 있으면. 좋은 방은 저 위의 것한테 양보했다. 방세가 너무 비싸다.`,
      ng:`약병을 담다가 두 병이 부딪쳤다. 쨍.<br><br>유리 소리는 여기서 제일 맑은 소리다. 맑은 소리는 멀리 간다.<br>천장 덮개가 덜컹했다. 챙긴 것 반을 흘리며 나왔다. 바늘은 챙겼다. 바늘이 반이다.`,
      win:{ exp:20, dream:2, item:'약초 뭉치' }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S2', t:'양치 숲 — 박힌 가시',
  x:`덤불을 지나는데 하나가 주저앉았다. 허벅지에 가시가 박혔다. 손가락만 한 것이.<br><br>
    가시 끝에 미늘이 졌다. 뽑으면 들어갈 때보다 크게 찢는다.<br>
    이 숲의 풀은 제 몸을 지킨다. 바늘로. 어떤 바늘에는 바른 것도 있다.<br><br>
    박힌 자리 둘레가 벌써 뜨뜻하다. 빨리 정해야 한다.`,
  o:[
    { l:'① 밀어서 반대쪽으로 빼낸다.', k:'heal', dc:25, wake:1,
      ok:`뽑지 않았다. 미늘 방향 그대로, 더 밀어서 반대쪽 살가죽을 뚫고 내보냈다. 그 사람이 벼락같이 소리를 물었다.<br><br>나온 끝을 집게로 잡아 끌어냈다. 미늘이 길을 따라 나간다. 새로 찢는 것 없이.<br>두 구멍을 씻고 닫았다. 구멍은 둘인데 상처는 하나다.<br><br>거꾸로 가면 찢고, 그대로 가면 뚫는다. 미늘 박힌 것은 미늘의 길로 보낸다. 이 숲이 가르친 바느질이다.`,
      ng:`미는 각이 틀렸다. 가시가 속에서 부러졌다.<br><br>반 토막이 살 속에 남았다. 미늘째.<br>째고 헤집어 겨우 꺼냈다. 작은 구멍이면 될 일이 손바닥만 한 자리가 됐다. 그 사람은 사흘을 절었다.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 가시 둘레 살의 열부터 읽는다.', k:'gaze', dc:24, cost:{ mana:26 },
      ok:`마력을 얇게 깔아 박힌 자리 둘레의 열을 읽었다. 뜨거운 테가 가시를 따라 좁게만 섰다. 독이 아니라 그냥 염증이다.<br><br>바른 가시였으면 열이 핏줄을 따라 뻗었을 것이다.<br>그럼 급할 것 없다. 숨 고르고, 자리 잡고, 제대로 꺼냈다. 안 급한 걸 아는 것도 실력이다.`,
      ng:`열을 읽는데 테가 둘이다. 가시 둘레 하나, 그리고 무릎 아래 하나.<br><br>아까 긁힌 자리가 따로 덧나고 있던 것이다. 가시에 가려 못 본.<br>하나 꺼내고 하나 다스리고. 한 사람 다리에 반나절이 들었다. 숲은 그동안 어두워졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S2', t:'울타리 — 다리부터 무는 것들',
  x:`울타리 틈을 건너다 뒤처진 하나가 물렸다. 종아리를.<br><br>
    물고 바로 놓았다. 죽이는 물기가 아니다. 느리게 만드는 물기.<br>
    저것들은 먼저 절게 만든다. 무리에서 떨어질 때까지 기다린다. 그게 사냥법이다.<br><br>
    그러니까 이 상처는 상처가 아니라 초대장이다. 받아 줄 수는 없다.`,
  o:[
    { l:'① 그 자리에서 다리를 묶고 어깨에 걸친다.', k:'heal', dc:25,
      ok:`앉혀 놓고 고칠 시간이 아니다. 천으로 세게 감아 피만 잡고, 그 사람 팔을 어깨에 걸쳤다.<br><br>둘이 한 몸으로 걸었다. 세 박자 걸음. 절뚝임이 사라진 건 아닌데 혼자 처지는 그림이 사라졌다.<br>수풀의 눈들이 따라오다 흩어졌다. 떨어지기를 기다리는 사냥은 떨어지지 않으면 끝이다.`,
      ng:`걸치고 걷는데 속도가 반으로 줄었다. 둘 다 느려진 것이다.<br><br>수풀이 조급해졌다. 기다리던 것들이 앞질러 가 길목에 선다.<br>남은 일행이 돌을 던지고 소리를 질러 길을 텄다. 느린 둘이 그 가운데로 지나갔다. 긴 하루였다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 마력으로 다리 힘줄을 당겨 세운다.', k:'fix', dc:26, cost:{ mana:37 }, wake:1,
      ok:`물린 종아리에 손을 대고 마력을 힘줄처럼 꼬아 넣었다. 상한 힘줄 옆에 나란히. 가짜 힘줄이다.<br><br>그 사람이 일어섰다. 디뎠다. 디뎌진다.<br>제 발로 뛰는 사냥감은 초대장을 찢은 사냥감이다. 수풀이 한참 따라오다 포기했다.<br><br>닫는 마력만 쓰던 손이 받치는 마력을 꼬았다. 고치는 것과 버티게 하는 것 사이. 그 사이가 오늘 벌어 준 거리다.`,
      ng:`꼰 마력이 걸음 반 굽이 만에 풀렸다. 디딘 다리가 꺾였다.<br><br>하필 트인 데서. 넘어진 그림은 저것들이 제일 기다리던 그림이다.<br>들쳐 업고 뛰었다. 등 뒤가 소란했다. 울타리 안쪽까지 업은 숨이 한계였다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-18 } },
    { l:'③ 뒤처진 채 혼자 치료부터 한다.', k:'luck', dc:26,
      doom:{ title:'떨어진 둘', what:'무리에서 떼어져 수풀로 끌려갑니다', dc:20, sec:37,
        text:`먼저 가라고 손짓했다. 상처는 바로 봐야 한다. 그게 배운 법이다.<br><br>앉아서 천을 감는데 수풀이 양쪽에서 좁혀 왔다. 소리도 없이. 무리와 떨어진 둘. 저것들이 만든 그림 그대로다.<br>물렸다. 이번에는 놓지 않는 물기다.<br><br>치료하던 손이 풀을 움켜쥔다. 환자였던 사람이 이쪽 팔을 잡고 버틴다. 잡은 손까지 같이 끌려간다. 초대장은 두 장이었다.`,
        dieText:`울타리 틈 앞에 감다 만 천이 떨어져 있다.<br><br>천은 반만 감겼다. 바른 법이었다. 바른 자리가 아니었을 뿐.<br>수풀 안쪽에서 저것들의 낮은 소리가 오래 났다. 나눠 먹는 소리다.` },
      ok:`앉으려다 수풀을 봤다. 바람과 다르게 흔들리는 끝이 둘, 셋.<br><br>여기가 아니다. 상처보다 자리가 먼저다.<br>부축해서 울타리 안쪽까지 간 다음에 앉았다. 천을 감으며 수풀 쪽을 봤다. 흔들리던 끝들이 실망한 듯 가라앉았다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'물가 — 물을 먹은 사람',
  x:`큰 물결이 둑을 넘었다. 한 사람이 쓸려 갔다 걸려 나왔다.<br><br>
    숨이 없다. 입에서 물이 흐른다.<br>
    물가 멀리서 또 물결이 온다. 큰 것이 걷는 물결이다. 이 둑도 다시 넘을 것이다.<br><br>
    숨을 돌릴 시간과 물결이 오는 시간. 둘 중 뭐가 짧은지부터 재야 한다.`,
  o:[
    { l:'① 둑 밑에서 바로 숨을 돌린다.', k:'heal', dc:26, cost:{ mana:36 }, wake:1,
      ok:`옮길 시간이 없다. 모로 눕혀 물부터 뺐다. 그다음 가슴을 눌렀다. 마력을 숨길처럼 틔우면서.<br><br>물결 소리가 커진다. 세지 않았다. 셈은 가슴 누르는 데만 썼다.<br>그 사람이 물을 토하며 숨을 터뜨렸다. 둘이 부축해 둑을 넘자마자 물이 아까 자리를 덮었다.<br><br>급한 일 둘 중 하나만 세는 법. 손이 하는 일에 귀를 닫는 법. 물가에서 배웠다.`,
      ng:`물을 빼는데 숨이 안 돌아온다. 한 번, 두 번, 열 번.<br><br>물결이 둑을 때렸다. 물보라가 등을 덮쳤다.<br>그 사람을 끌고 비탈로 굴렀다. 구르는 중에 그 사람이 켁, 하고 물을 토했다. 살긴 살았다. 어느 쪽 덕인지는 모르겠다.`,
      win:{ exp:24, dream:4, hp:6 }, lose:{ hp:-30, spirit:-20 } },
    { l:'② 업고 비탈 위까지 가서 돌린다.', k:'steady', dc:25,
      ok:`숨 없는 몸을 업고 비탈을 올랐다. 서두르되 넘어지지 않게. 넘어지면 둘 다 끝이다.<br><br>마른 땅에 눕히고 물을 빼고 가슴을 눌렀다. 아홉째에 숨이 터졌다.<br>아래를 보니 아까 그 자리가 물에 잠겨 있다. 비탈 하나 차이다. 그 차이를 등으로 번 것이다.`,
      ng:`비탈 중간에서 발이 미끄러졌다. 업은 채 무릎을 찧었다.<br><br>그만큼 늦었다. 눕히고 누르는 손이 급해졌다.<br>열다섯째에 겨우 숨이 돌아왔다. 돌아온 숨이 가늘다. 밤새 머리맡에서 그 숨을 세며 앉아 있었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S2', t:'들판 — 찬 땀',
  x:`한낮인데 한 사람이 떨고 있다. 땀은 흐르는데 살은 차다.<br><br>
    아침에 물린 자리가 푸르스름하다. 늪 열병이다. 피가 식는 병.<br>
    여기 벌레가 옮기는 모양이다. 책에 없는 병은 몸이 하는 말로 읽는 수밖에.<br><br>
    식는 피는 데워야 한다. 밖에서 말고, 안에서.`,
  o:[
    { l:'① 마력을 피에 실어 속부터 데운다.', k:'heal', dc:25, cost:{ mana:35 },
      ok:`손목과 목, 피가 지나는 길목마다 손을 얹고 마력을 실었다. 덥힌 마력을. 피가 마력을 업고 돈다.<br><br>반나절을 돌리자 떨림이 멎었다. 살빛이 돌아온다.<br>물린 자리의 푸른 것도 테두리부터 걷혔다. 피가 더우면 병이 좁아진다. 이 병은 그렇다. 하나 배웠다.`,
      ng:`데운 마력이 물린 자리에서 자꾸 식는다. 거기 뭔가가 열을 먹는다.<br><br>마력을 쏟아붓는 싸움이 됐다. 해 질 녘까지.<br>겨우 떨림만 잡았다. 푸른 자리는 그대로다. 내일도 이 싸움이다. 마력 주머니가 가볍다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 모두의 몸으로 감싸 한 덩이로 데운다.', k:'bond', dc:24,
      ok:`담요를 펴고 떠는 사람을 가운데 뉘었다. 양옆에 둘씩 붙어 누웠다. 체온 넷이 한 사람을 덥힌다.<br><br>오래된 법이다. 마력보다 느리고 마력보다 안 떨어진다.<br>새벽에 가운데 사람이 땀을 뒤집어쓰고 깼다. 더운 땀이다. 이긴 땀.`,
      ng:`붙어 눕다 보니 망보는 눈이 줄었다.<br><br>새벽에 야영지 가장자리까지 발자국이 들어와 있었다. 세 발 자국. 바로 옆까지 왔다 간 것이다.<br>떨던 사람은 나았다. 나머지가 한동안 떨었다. 다른 이유로.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'S2', t:'둥지 가 — 우는 작은 것',
  x:`덤불 뒤에서 우는 소리가 난다. 가 보니 저것들의 새끼다. 무릎 높이의.<br><br>
    뒷다리가 돌 틈에 끼어 꺾였다. 빠져나오려 울고 있다.<br>
    울음은 멀리 간다. 어미한테도 간다.<br><br>
    고치는 손은 우는 것 앞에서 멈추게 돼 있다. 그 버릇이 여기서는 목숨값이다.`,
  o:[
    { l:'① 다리를 빼 주고 바로 물러난다.', k:'heal', dc:25, wake:1,
      ok:`돌을 괴어 틈을 벌리고 꺾인 다리를 빼 줬다. 새끼가 이빨을 세웠지만 물지는 않았다. 아픈 것은 제 아픔부터 센다.<br><br>부목도 못 대 준다. 사람 냄새가 배면 어미가 버린다. 빼 주고 바로 스무 걸음 물러났다.<br>어미가 왔다. 새끼 냄새를 맡고, 이쪽 수풀을 한 번 길게 보고, 새끼를 물어 올려 갔다.<br><br>고치는 일의 반은 손대지 않는 것이라는 걸, 저 큰 눈 앞에서 배웠다.`,
      ng:`빼 주는데 새끼가 놀라 더 크게 울었다.<br><br>어미 울음이 바로 답했다. 가깝다.<br>덤불을 구르다시피 빠져나왔다. 뒤에서 어미가 새끼를 찾는 소리와 수풀 부서지는 소리가 겹쳤다. 좋은 일이 좋게만 끝나지는 않는 땅이다.`,
      win:{ exp:24, dream:4, spirit:8 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 우는 소리를 등지고 길을 재촉한다.', k:'steady', dc:24,
      ok:`들은 척하지 않았다. 일행을 재촉해 지나쳤다.<br><br>반 굽이쯤 가서 뒤에서 어미 울음이 났다. 새끼를 찾은 울음이다.<br>손대지 않은 덕에 어미는 이쪽을 모른다. 모르는 게 서로 제일 낫다. 걸음이 무거운 건 어쩔 수 없고.`,
      ng:`지나치는데 새끼 울음이 따라붙었다. 끼인 채로 이쪽을 보며 우는 것이다.<br><br>일행 하나가 못 참고 돌아섰다. 말리는 사이 시간이 갔다.<br>결국 빼 주고 다 같이 뛰었다. 어미 울음이 들판 반을 따라왔다. 무른 마음 하나가 무리 전체의 숨값이 됐다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S2', t:'승강기 앞 — 뛸 다리들',
  x:`둔덕 아래 승강기까지 마지막 들판이다. 부르면 내려오는 데 한참, 타면 올라가는 데 또 한참.<br><br>
    다섯 중 셋이 다리에 상처를 달고 있다. 뛰다 한 명이라도 넘어지면 다 선다.<br>
    들판 수풀은 벌써 알고 있다. 끝판에 몰린 것들이 어디로 뛰는지.<br><br>
    출발 전에 손볼 수 있는 건 다 손봐야 한다. 지금뿐이다.`,
  o:[
    { l:'① 셋의 다리를 차례로 손본다.', k:'heal', dc:25, cost:{ mana:34 }, wake:1,
      ok:`셋을 앉혔다. 감은 천을 다 풀고 새로 감았다. 뛰는 다리의 감기는 걷는 다리와 다르다. 더 세게, 관절은 비워서.<br><br>마력은 제일 약한 발목 하나에만 썼다. 아끼는 게 아니라 고르는 것이다.<br>출발 신호에 다섯이 뛰었다. 아무도 처지지 않았다. 들판 가운데서 묶은 천 하나 안 풀렸다.<br><br>손볼 것과 둘 것을 고르는 눈. 모자란 마력이 가르친 눈이다. 넉넉했으면 평생 몰랐을 것이다.`,
      ng:`둘째 다리를 감다가 해가 기울기 시작했다.<br><br>셋째는 반만 손봤다. 시간이 먼저 끝났다.<br>뛰는 중에 셋째가 처졌다. 둘이 돌아가 양팔을 끼고 끌었다. 승강기 문이 닫힐 때 수풀이 둔덕까지 와 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 제일 성한 둘에게 부축 순서를 짠다.', k:'fix', dc:24,
      ok:`뛰다 누가 넘어지면 누가 줍는지부터 정했다. 성한 둘이 좌우 날개. 처지는 사람이 생기면 가까운 쪽이 줍는다. 멈추지 말고.<br><br>들판 한가운데서 정말 하나가 고꾸라졌다. 정한 대로 왼쪽 날개가 낚아챘다. 걸음 반 박자만 늦고 다시 달렸다.<br>계획은 넘어지기 전에 세우는 것이다. 치료도 그렇다.`,
      ng:`순서를 짜는 데 입씨름이 붙었다. 서로 제가 성하다고.<br><br>해는 기울고 결론은 안 난다. 결국 대충 정하고 뛰었다.<br>넘어진 사람을 둘이 동시에 주우러 가다 부딪혔다. 들판 한가운데서 셋이 엉켰다. 그 몇 숨이 제일 길었다.`,
      win:{ exp:20, dream:3, mind:6 }, lose:{ hp:-26, spirit:-16 } },
    { l:'③ 뛰면서 다친 데를 봐주겠다고 한다.', k:'luck', dc:26,
      doom:{ title:'들판 한가운데', what:'멈춘 자리에서 덮쳐져 수풀로 끌려갑니다', dc:20, sec:35,
        text:`미리 볼 시간이 아깝다. 뛰다가 처지는 사람 옆에 붙어 달리며 손보면 된다. 그렇게 정했다.<br><br>들판 가운데서 하나가 절뚝였다. 옆에 붙었다. 천 끝을 잡는 순간 둘의 속도가 같이 꺾였다.<br>느려진 둘. 들판 한가운데. 수풀이 기다리던 그림이다.<br><br>옆구리에 무게가 실렸다. 땅이 뒤집히고, 하늘이 보이고, 그다음은 수풀이 보였다. 끌려가면서. 달리며 하는 치료는 없다. 그 답을 너무 늦게 받았다.`,
        dieText:`들판 가운데 풀이 한 줄로 눕혀져 있다.<br><br>눕혀진 줄은 수풀에서 끝난다.<br>승강기는 넷을 태우고 올라갔다. 빈 한 자리에 천 뭉치만 놓였다.` },
      ok:`뛰기 직전에 생각을 바꿨다. 들판에서 손 볼 수 있는 건 없다. 들판에서 할 수 있는 건 뛰는 것뿐이다.<br><br>출발을 반 박자 늦추고 제일 급한 발목 하나만 당겨 감았다.<br>그 반 박자가 들판 한가운데서 돌아왔다. 아무도 처지지 않는 걸음으로.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'승강기 — 올라가는 동안',
  x:`쇠 바구니가 끼익끼익 올라간다. 다들 바닥에 주저앉았다.<br><br>
    이제야 상처들이 아우성친다. 뛸 때는 조용하던 것들이.<br>
    몸은 그렇다. 살아남을 때까지 참았다가 살아남으면 청구서를 내민다.<br><br>
    올라가는 동안이 진료 시간이다. 흔들리는 진료실이지만.`,
  o:[
    { l:'① 급한 순서대로 셋을 본다.', k:'heal', dc:24, wake:1,
      ok:`아픈 소리 큰 순서가 아니라 핏기 없는 순서로 봤다. 제일 조용한 사람이 제일 위험했다. 역시.<br><br>흔들리는 바닥에서 무릎으로 몸을 고정하고 손을 놀렸다. 묶고, 닫고, 물리고.<br>꼭대기에 닿았을 때 셋 다 제 발로 내렸다.<br><br>비명은 순서가 아니다. 조용한 쪽부터. 그 순서를 몸이 외웠다. 흔들리는 쇠 바닥 위에서.`,
      ng:`흔들림에 손이 자꾸 어긋났다. 매듭이 두 번 풀렸다.<br><br>바늘도 한 번 미끄러졌다. 제 손가락을 찔렀다.<br>꼭대기까지 반밖에 못 봤다. 나머지는 내려서 마저 봤다. 흔들리는 진료는 반값이다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 마지막 마력을 넷으로 갈라 나눈다.', k:'bond', dc:25, cost:{ mana:30 },
      ok:`남은 마력을 긁어모아 네 가닥으로 갈랐다. 한 사람 몫으로는 상처 하나, 네 가닥이면 네 사람의 제일 급한 데 하나씩.<br><br>손바닥을 차례로 얹었다. 따뜻한 것이 한 줄기씩 건너갔다.<br>다 나눠 주고 나니 이쪽 손끝이 차다. 빈 주머니가 이렇게 개운한 날도 있다.`,
      ng:`가르다가 두 가닥이 엉켰다. 한 사람한테 두 몫이 가고 한 사람은 빈손이다.<br><br>빈손인 사람이 괜찮다고 웃었다. 그 웃음이 제일 아팠다.<br>내려서 그 사람 것부터 봤다. 맨손으로. 맨손도 손은 손이다.`,
      win:{ exp:20, dream:3, spirit:8 }, lose:{ mind:-16, spirit:-18 } }
  ] }

]);

// ------------------------------------------
// 약사 (pharma) · 자원 없음
// ------------------------------------------
kJob('pharma', 'S', [

{ at:'S', t:'쉬는 자리 — 재우는 가루',
  x:`다친 사람이 밤새 앓는 소리를 낸다. 참는데도 새어 나온다.<br><br>
    여기서 앓는 소리는 등불이다. 소리 나는 쪽으로 오는 것들한테는.<br>
    봇짐에 재우는 가루가 있다. 문제는 양이다. 적으면 소리가 안 죽고, 많으면 숨이 죽는다.<br><br>
    다친 몸은 약을 평소와 다르게 받는다. 저울 없이 다는 밤이다.`,
  o:[
    { l:'① 맥을 짚어 가며 반 꼬집씩 늘린다.', k:'heal', dc:24, wake:1,
      ok:`손목을 쥔 채 가루를 반 꼬집 먹였다. 맥을 세고, 기다리고, 또 반 꼬집.<br><br>세 번째에 앓는 소리가 숨소리로 내려앉았다. 맥은 느려졌지만 고르다. 거기서 멈췄다.<br>약은 양이 아니라 양의 길이다. 한 번에 닿는 길이 아니라 조금씩 다가가는 길.<br><br>저울 없이 맥으로 다는 법. 손가락 세 개가 저울이 되는 밤이었다.`,
      ng:`둘째 꼬집에서 맥이 출렁했다. 다친 몸이 약을 세게 받은 것이다.<br><br>숨이 얕아졌다. 급히 찬물로 얼굴을 닦고 몸을 주물렀다.<br>숨은 돌아왔는데 약은 깼다. 앓는 소리도 돌아왔다. 밤이 두 배로 길었다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 가루 대신 입에 무는 나무토막을 깎는다.', k:'fix', dc:23,
      ok:`가루를 아꼈다. 대신 나무토막을 깎아 천으로 감고 입에 물렸다.<br><br>무는 것이 있으면 소리가 안으로 삼켜진다. 산길 약방들이 쓰던 법이다.<br>앓는 소리가 숨소리만큼 줄었다. 가루는 주머니에 그대로다. 더 나쁜 밤을 위해.`,
      ng:`새벽에 그 사람이 토막을 뱉고 돌아누웠다. 앓는 소리가 길게 샜다.<br><br>어둠 저쪽에서 무언가 자갈 밟는 소리가 답했다.<br>결국 가루를 썼다. 처음부터 쓸 것을. 아낀 것이 소리 값으로 나갔다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S', t:'어둠 — 싫어하는 냄새',
  x:`그것들이 다니는 길목을 지나야 한다. 벽의 긁힌 자국이 어른 키 위까지 나 있다.<br><br>
    어떤 짐승이든 싫어하는 냄새가 있다. 약방의 믿음이다.<br>
    봇짐에는 쓴 것, 매운 것, 삭은 것이 조금씩 있다. 뭐가 통할지는 여기 것들한테 물어봐야 안다.<br><br>
    묻는 법이 문제다. 가까이서 물으면 대답이 이빨로 온다.`,
  o:[
    { l:'① 세 가지 냄새를 길목에 미리 놓아 본다.', k:'sense', dc:24, wake:1,
      ok:`쓴 뭉치, 매운 가루 주머니, 삭은 즙 천. 길목 어귀에 한 발씩 떼어 놓고 멀리서 지켜봤다.<br><br>그것 하나가 지나갔다. 쓴 것은 밟고, 삭은 것은 킁킁대고, 매운 가루 앞에서는 멈칫하며 크게 돌아갔다.<br>답을 받았다. 매운 가루를 일행 신발과 옷단에 발랐다. 길목을 지나는 내내 아무것도 붙지 않았다.<br><br>약은 사람한테만 묻는 게 아니다. 짐승한테 묻는 법을 오늘 하나 적었다. 멀리서, 셋씩 놓고.`,
      ng:`놓은 셋 다 그냥 밟고 지나갔다. 이 땅 것들은 코의 생김부터 다른 모양이다.<br><br>빈손으로 길목을 지나야 했다. 숨만 죽이고.<br>반쯤 갔을 때 뒤의 것이 콧김을 뿜었다. 가루고 뭐고 다 버리고 뛰었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 매운 가루를 바람 위쪽에서 한꺼번에 날린다.', k:'break', dc:25,
      ok:`길목 바람 위쪽 바위에 올라 가루 주머니를 통째로 털었다. 매운 구름이 길목을 덮었다.<br><br>어둠 속에서 재채기 비슷한 소리가 연달아 났다. 크고 축축한 재채기.<br>그것들이 길목을 비웠다. 코가 돌아오기 전에 다 건넜다. 가루는 다 썼지만 길은 샀다.`,
      ng:`터는 순간 바람이 돌았다. 매운 구름이 이쪽으로 왔다.<br><br>다섯이 눈물 콧물로 길목에 주저앉았다. 기침을 참느라 혀를 깨물며.<br>그것들보다 가루에 먼저 당했다. 눈이 뜨일 때까지 서로의 허리띠를 잡고 기었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-16 } },
    { l:'③ 삭은 즙을 제 몸에 바르고 먼저 건넌다.', k:'hide', dc:25,
      ok:`삭은 즙을 목과 소매에 발랐다. 산 것 냄새를 죽은 것 냄새로 덮는 것이다.<br><br>길목을 혼자 먼저 건넜다. 어둠 속의 것이 코를 대고 지나갔다. 썩은 것은 먹이 축에 못 든다. 여기서도.<br>건너편에서 신호를 보냈다. 나머지도 즙을 바르고 하나씩 건너왔다. 코 막은 채로.`,
      ng:`반쯤 건넜을 때 등 뒤에서 킁킁 소리가 따라붙었다.<br><br>여기 것들은 썩은 것도 먹는 모양이다. 치우는 입이 따로 있는 땅이다.<br>즙을 벗어 던지고 뛰었다. 던진 옷을 그것이 바닥에 놓고 한참 굴렸다. 그사이 다들 건넜다. 옷 한 벌 값.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-15 } }
  ] },

{ at:'S', t:'쉬는 자리 — 두 알의 셈',
  x:`아픈 사람이 셋, 남은 진통제가 두 알이다.<br><br>
    쪼개면 셋 다 조금 덜 아프고, 둘에게 주면 둘은 걷고 하나는 업힌다.<br>
    약방의 셈은 늘 이렇다. 모자라는 약을 어디에 두는가.<br><br>
    내일 길이 험하다는 것까지 셈에 넣어야 한다.`,
  o:[
    { l:'① 내일 짐을 들 둘에게 온전히 준다.', k:'fix', dc:24,
      ok:`약은 아픔 순이 아니라 쓰임 순으로 갔다. 내일 앞장설 둘에게 한 알씩.<br><br>셋째에게는 뜨거운 찜질과 부목을 더 단단히 해 줬다. 그리고 업는 순서를 짰다.<br>다음 날 둘이 길을 열고 셋째는 번갈아 업혔다. 야박한 셈이 무리를 통째로 건넜다.`,
      ng:`셋째가 셈을 들었다. 왜 저는 빼냐고.<br><br>설명은 맞는 말이고 서운함은 맞는 마음이다. 둘 다 밤새 풀리지 않았다.<br>다음 날 셋째가 이를 물고 제 발로 걸었다. 고마운데, 그 걸음이 상처를 키웠다. 약값보다 비싸게.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 두 알을 갈아 셋의 상처에 나눠 바른다.', k:'heal', dc:25, wake:1,
      ok:`먹이지 않고 바르기로 했다. 갈아서 기름에 개어 상처 자리에 직접.<br><br>삼킨 약은 온몸을 돌고 나서야 아픈 데 닿는다. 바른 약은 아픈 데서 시작한다. 양이 적을 때는 그게 셈이 맞다.<br>셋 다 반나절은 걸을 만하다고 했다. 반나절이면 험한 길이 끝난다.<br><br>같은 약도 길을 바꾸면 양이 는다. 입으로 가는 약과 살로 가는 약. 그 갈림길이 손에 들어왔다.`,
      ng:`개는 기름이 상했던 모양이다. 바른 자리가 더 화끈거린다고 셋 다 울상이다.<br><br>씻어 내고 나니 약도 기름도 없다.<br>빈손의 밤. 셋의 앓는 소리를 입막음 천으로 달랬다. 약사 봇짐이 이렇게 가벼우면 안 되는 건데.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S', t:'통로 — 독이 도는 팔',
  x:`스친 상처였다. 그런데 팔이 붓는다. 뻣뻣하게.<br><br>
    긁은 발톱에 무언가 발려 있던 것이다. 부은 자리에서 심장 쪽으로 붉은 줄이 올라간다.<br>
    독이 길을 냈다. 저 줄이 어깨를 넘으면 늦는다.<br><br>
    여기 독은 처음 보는 독이다. 그래도 독이 가는 길은 어디서나 같다.`,
  o:[
    { l:'① 줄 위쪽을 묶고 아래를 째서 빼낸다.', k:'heal', dc:25,
      ok:`붉은 줄보다 한 뼘 위를 천으로 묶었다. 꽉. 그리고 상처 자리를 넓게 째고 피를 짜냈다.<br><br>처음 나온 피는 검다. 검은 것이 붉어질 때까지 짰다.<br>줄이 팔꿈치 아래서 멈췄다. 묶은 천은 백을 세고 반만 풀고, 또 백을 세고 다 풀었다. 독은 길이 끊기면 주저앉는다.`,
      ng:`째긴 쨌는데 독이 생각보다 빨랐다. 줄이 묶은 천 위로 번져 올라갔다.<br><br>천을 한 뼘 더 위로 옮겨 묶었다. 쫓기는 묶기다.<br>어깨 바로 밑에서 겨우 멈췄다. 그 사람 팔이 이틀을 돌덩이였다. 독의 걸음을 얕본 값이다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 약초 뭉치로 빨아내는 찜을 붙인다.', k:'fix', dc:24, wake:1,
      ok:`약초 뭉치에서 빨아들이는 잎을 골라 씹어 이겼다. 상처에 두껍게 붙이고 천으로 감았다.<br><br>반나절마다 갈았다. 뗄 때마다 잎 안쪽이 거뭇하다. 독이 잎으로 옮겨 앉는 것이다.<br>세 번째 잎은 깨끗했다. 다 나온 것이다.<br><br>째는 것만 길이 아니다. 독을 꾀어내는 길도 있다. 칼 없이 치르는 싸움을 하나 배웠다.`,
      ng:`잎을 잘못 골랐다. 빨아들이는 잎이 아니라 데우는 잎이었다.<br><br>더워진 독이 더 빨리 돌았다. 줄이 한 마디 더 올라갔다.<br>그제야 째고 짜냈다. 길을 두 번 바꾼 치료는 몸에 두 배로 남는다. 그 사람 팔에도, 이쪽 마음에도.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S', t:'물가 — 수상한 샘',
  x:`바위 틈에서 물이 솟는다. 맑다. 너무 맑다.<br><br>
    샘 둘레에 풀이 없다. 벌레도 없다. 물가에 아무것도 안 사는 샘.<br>
    약방에서는 그런 물을 먼저 의심한다. 깨끗해서 빈 게 아니라 독해서 빈 것일 수 있다.<br><br>
    목마른 눈 넷이 등 뒤에서 기다린다.`,
  o:[
    { l:'① 은수저 대신 쇠붙이를 담가 본다.', k:'gaze', dc:24,
      ok:`칼끝을 샘에 담갔다. 백을 셌다. 꺼내 보니 칼끝이 거뭇하게 죽었다.<br><br>쇠를 먹는 물이다. 속은 더 잘 먹을 것이다.<br>마시는 건 접고, 대신 병에 반만 받았다. 쇠를 죽이는 물은 쓸 데가 따로 있다. 약이 못 되면 연장이라도 된다.`,
      ng:`칼끝이 멀쩡했다. 그래서 반 모금 마셨다. 쇠에는 안 듣고 사람한테만 듣는 것도 있다는 걸 혀가 저리고서야 떠올렸다.<br><br>급히 게워 냈다.<br>한나절 혀가 둔했다. 맛을 못 보는 약사는 눈 감은 약사다. 혀가 돌아올 때까지 아무 약도 못 지었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 끓이고 숯에 거른 다음 반 모금씩 돌린다.', k:'heal', dc:25, wake:1,
      ok:`받아서 끓이고, 모닥불 숯을 빻아 천에 깔고 걸렀다. 두 번.<br><br>그래도 바로 안 줬다. 반 모금씩, 한 사람씩, 한식경 간격으로. 탈이 나면 바로 멈출 수 있는 간격이다.<br>탈이 없었다. 그제야 병을 채웠다.<br><br>거르고, 나누고, 기다리는 세 겹. 급한 목에 세 겹을 지키는 게 약방의 담력이라는 걸 다시 새겼다.`,
      ng:`두 번 거른 물인데도 첫 사람이 배를 쥐었다.<br><br>숯이 못 거르는 것이 녹아 있던 것이다.<br>토하게 하고 남은 물을 다 쏟았다. 목마름에 배앓이까지 얹었다. 이 샘이 왜 비어 있는지 몸으로 배웠다.`,
      win:{ exp:22, dream:3, item:'맑은 물' }, lose:{ hp:-28, spirit:-16 } },
    { l:'③ 맑으니 그냥 떠서 마신다.', k:'luck', dc:25,
      doom:{ title:'빈 샘', what:'굳은 몸으로 샘가의 것에게 끌려갑니다', dc:19, sec:45,
        text:`맑은 물에 트집 잡는 것도 지쳤다. 손으로 떠서 마셨다. 달다.<br><br>두 모금째에 손끝이 저렸다. 세 모금째에 무릎이 접혔다. 마비다. 샘 둘레가 빈 이유는 독이 아니었다. 덫이었다.<br>바위 틈이 열리고 긴 것이 나왔다. 샘은 저것의 침이 고인 자리였다.<br><br>굳은 몸이 바위 틈으로 끌려 들어간다. 눈만 말짱하다. 끝까지 눈만.`,
        dieText:`샘은 다시 맑아졌다.<br><br>둘레에는 여전히 풀 한 포기 없다. 발자국 몇 개가 샘 쪽으로 나 있고, 나온 자국은 없다.<br>맑은 것이 제일 깊은 덫이다. 약방 첫 장에 적힌 말인데.` },
      ok:`손을 뻗다 멈췄다. 수면에 김이 없다. 솟는 샘인데 물결 하나 없다.<br><br>솟지 않는 샘물. 고여서 기다리는 물.<br>물러나며 돌을 하나 던졌다. 샘이 돌을 받고 출렁이는데, 출렁임이 가장자리에서 안쪽으로 돌았다. 삼키는 물결이다. 목마른 채로 떠났다. 목은 마르면 그만이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'어둠 — 깨어 있게 하는 잎',
  x:`이틀째 아무도 제대로 못 잤다. 눈꺼풀들이 내려온다.<br><br>
    여기서 조는 것은 눕는 것이고, 눕는 것은 사라지는 것이다.<br>
    봇짐에 깨어 있게 하는 잎이 있다. 심장을 채찍질하는 잎이다. 효과도 빚도 확실하다.<br><br>
    빚은 나중에 몸이 갚는다. 그 나중이 언제 오느냐가 문제다.`,
  o:[
    { l:'① 망보는 둘에게만 반 잎씩 물린다.', k:'fix', dc:24, wake:1,
      ok:`다 깨어 있을 필요는 없다. 망 설 둘에게만 반 잎씩. 나머지는 재웠다.<br><br>반 잎은 세 시진을 간다. 교대 때 다음 둘에게 또 반 잎.<br>잎 두 장으로 밤을 넘겼다. 아침에 다들 빚 없이 일어났다. 약은 쓰는 사람 수를 줄이는 게 첫째 절약이다.<br><br>모두에게 쓰는 약과 둘에게 쓰는 약. 같은 잎의 다른 처방. 그 차이를 밤이 가르쳐 줬다.`,
      ng:`반 잎 문 둘 중 하나가 손이 떨리기 시작했다. 빈속이라 세게 받은 것이다.<br><br>떨리는 손으로는 망을 못 선다. 소리만 낸다.<br>결국 그 사람을 재우고 이쪽이 대신 섰다. 맨정신으로. 밤이 사흘 같았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 잎 대신 찬물과 매운 가루로 버티게 한다.', k:'steady', dc:23,
      ok:`잎은 아꼈다. 대신 찬물에 적신 천을 목에 두르게 하고, 졸음이 오면 매운 가루를 혀끝에 콩알만큼.<br><br>싸구려 각성이다. 그래도 빚이 없다.<br>밤새 혀끝 맵다는 투덜거림만 돌았다. 투덜거리는 입은 깨어 있는 입이다.`,
      ng:`새벽녘에 둘이 같이 졸았다. 찬물도 매운 것도 이틀 치 졸음한테는 안 됐다.<br><br>고개 떨어지는 소리에 이쪽이 깼기 망정이지.<br>야영지 가장자리에 긴 것이 지나간 자국이 나 있었다. 자는 다섯을 재 보고 간 자국이.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S', t:'쉬는 자리 — 금이 간 약병',
  x:`봇짐을 여는데 손이 멎었다. 약병 하나에 금이 갔다. 아까 구를 때다.<br><br>
    센 약이다. 상처를 지지는 데 쓰는, 살에 닿으면 안 되는.<br>
    금 사이로 조금씩 배어 나와 옆의 약초 뭉치가 반쯤 젖었다.<br><br>
    봇짐 안에서 약끼리 싸우면 약사 책임이다. 어디서든.`,
  o:[
    { l:'① 젖은 뭉치를 갈라 성한 쪽만 살린다.', k:'heal', dc:24,
      ok:`뭉치를 풀어 한 잎씩 봤다. 젖은 잎은 가장자리가 말려 있다. 만지지 않고도 보인다.<br><br>성한 잎 반을 골라 새 천에 쌌다. 젖은 반은 돌 위에 펴서 태웠다. 연기가 맵다. 바람 아래서.<br>반을 잃고 반을 지켰다. 봇짐 사고의 셈은 그 정도면 남는 셈이다.`,
      ng:`고르다가 젖은 잎 하나가 손가락에 닿았다.<br><br>손끝이 하얗게 일어났다. 지지는 약은 잎에 묻어도 지진다.<br>물로 씻고 천으로 감았다. 약 고르는 손가락이 한동안 둔했다. 약사 손끝은 연장인데, 연장을 상했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 금 간 병을 초로 때우고 겹으로 싼다.', k:'fix', dc:23, wake:1,
      ok:`초를 녹여 금 위에 입혔다. 두 번. 식힌 다음 천으로 감고 뼈 상자에 따로 앉혔다.<br><br>센 약일수록 자리를 따로 준다. 봇짐 속에 작은 약방을 다시 짰다. 센 것은 가운데, 무른 것은 바깥.<br>그 뒤로 어떤 구름에도 봇짐 안은 조용했다.<br><br>약을 담는 것도 조제다. 병과 천과 자리까지가 약이다. 구르고 나서야 그 장을 읽었다.`,
      ng:`초가 모자라 금을 반만 덮었다.<br><br>사흘 뒤 봇짐에서 쓴 냄새가 났다. 못 덮은 금이 자라 병이 쪼개진 것이다.<br>센 약 한 병이 통째로 날아갔다. 다음 지질 일은 달군 칼로 해야 한다. 칼은 약보다 아프다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-15 } }
  ] },

{ at:'S', t:'길 — 무는 벌레 떼',
  x:`풀이 깊어지자 작은 것들이 달려들었다. 물면 콩알만큼 붓는 것들이다.<br><br>
    한 방은 가렵고 끝이다. 문제는 백 방이다. 그리고 부은 자리를 긁으면 덧나고, 덧난 냄새는 큰 것들을 부른다.<br>
    작은 것이 큰 것을 부르는 땅이다.<br><br>
    약방 봇짐에 벌레 쫓는 법이 두엇 있다. 값이 다를 뿐이다.`,
  o:[
    { l:'① 쓴 즙을 끓여 다 같이 바른다.', k:'heal', dc:23,
      ok:`쓴 잎을 끓여 즙을 냈다. 식혀서 목, 손목, 발목, 살 드러난 데마다 발랐다.<br><br>벌레들이 살 위에 앉았다가 맛만 보고 떴다. 무는 놈이 없다.<br>쓴 사람 다섯이 단 저녁을 보냈다. 긁는 손도, 덧나는 자리도 없이.`,
      ng:`즙이 눈가에 들어간 사람이 나왔다. 따가워서 눈물 콧물이다.<br><br>그 사람만 바르다 말았다. 벌레들이 귀신같이 그 사람한테만 몰렸다.<br>밤새 반쪽 얼굴이 두 배가 됐다. 약은 바르다 말면 표적을 만든다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 연기 나는 풀을 허리에 매달고 걷는다.', k:'fix', dc:24,
      ok:`천천히 타는 풀을 골라 심지를 꼬았다. 불씨를 물려 다섯 허리에 하나씩 매달았다.<br><br>걷는 대로 연기가 몸을 감는다. 벌레가 연기 밖에서만 맴돈다.<br>연기 기둥 다섯이 풀밭을 건넜다. 물린 데 하나 없이. 냄새는 좀 났지만 가려움보다 싸다.`,
      ng:`심지 하나가 너무 잘 탔다. 연기가 아니라 불이 됐다.<br><br>허리에서 불씨가 떨어져 마른 풀에 붙었다. 밟아 끄느라 한바탕 소란.<br>연기는 벌레만 부르지 않는다. 풀밭 저쪽에서 큰 그림자가 연기 기둥을 보러 왔다. 다 끄고 엎드려 보냈다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S', t:'쉬는 자리 — 약이 안 듣는 사람',
  x:`물린 사람한테 해독 가루를 먹였다. 들어야 할 시간이 지났는데 열이 그대로다.<br><br>
    양을 늘렸다. 그래도 그대로다. 삼킨 약이 어디론가 사라지는 것 같다.<br>
    약이 안 듣는 몸이 있다. 그리고 약을 가로채는 것이 든 몸이 있다.<br><br>
    여기 와서는 둘째 쪽을 먼저 생각하게 된다.`,
  o:[
    { l:'① 일부러 쓴 약을 먹이고 몸의 답을 본다.', k:'gaze', dc:25, wake:1,
      ok:`해독과 상관없는, 그냥 지독하게 쓴 약을 한 술 먹였다. 쓴 것은 몸이 바로 답한다. 얼굴로.<br><br>답이 없다. 혀가 쓴맛을 저한테 전하지 않는 것이다. 삼킨 것이 중간에서 다 가로채진다.<br>그럼 입은 접는다. 가루를 기름에 개어 살갗에 바르고, 짓이긴 잎을 코 밑에 걸었다. 입을 거치지 않는 길 둘.<br>열이 그 길로 내렸다.<br><br>약이 가는 길이 입만이 아니라는 것. 길이 막히면 길을 바꾸는 것. 가로채는 놈은 입만 지킨다.`,
      ng:`쓴 약을 먹이자 그 사람이 뜻밖에 얼굴을 찡그렸다. 쓴 건 아는 몸이다.<br><br>그럼 약이 왜 안 듣나. 답을 못 찾았다.<br>남은 가루를 다 쓰고도 열이 그대로다. 빈 약통을 쥐고 밤을 샜다. 모르는 병 앞의 약사는 맨손이다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 물린 자리에 직접 가루를 쟁인다.', k:'heal', dc:24,
      ok:`입으로 가는 약을 끊고 물린 자리를 쨌다. 해독 가루를 상처에 직접 쟁이고 천으로 눌렀다.<br><br>삼킨 약은 돌아서 가지만 바른 약은 바로 닿는다.<br>한 식경 만에 물린 자리 둘레의 붉은 기가 옅어졌다. 열은 하루 걸려 내렸다. 느려도 가는 길이 맞는 길이다.`,
      ng:`째고 쟁였는데 상처가 가루를 밀어냈다. 피와 함께 도로 배어 나온다.<br><br>안에서 밀어내는 것이다. 가루가 제게 독이라는 걸 아는 무언가가.<br>세 번을 다시 쟁였다. 세 번째에 겨우 머물렀다. 밀어내는 힘이 빠진 것이길 바라는 수밖에.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-28, spirit:-18 } },
    { l:'③ 밤새 머리맡에서 약그릇을 들고 지킨다.', k:'luck', dc:25,
      doom:{ title:'가로채는 것', what:'앓던 사람의 입에서 나온 것에게 끌려갑니다', dc:19, sec:40,
        text:`먹이고, 지켜보고, 또 먹이고. 머리맡에서 밤을 새기로 했다.<br><br>자정 넘어 그 사람 입이 벌어졌다. 하품인 줄 알았다. 벌어진 입에서 가느다란 것이 나왔다. 약그릇 쪽으로. 냄새를 맡듯 흔들리며.<br>가로채던 놈이 모자랐던 것이다. 그릇째 받으러 나올 만큼.<br><br>그릇을 쥔 손목을 그것이 감았다. 생각보다 굵고 생각보다 세다. 앓는 사람 입속으로, 그 너머 어둠으로, 손목부터 끌려간다.`,
        dieText:`아침에 그 사람은 열이 내린 채 깨어났다. 아주 개운하다고 했다.<br><br>머리맡에 빈 약그릇만 굴러 있다.<br>잘 들은 약이었다. 누구한테 들었는지가 문제일 뿐.` },
      ok:`그릇을 들고 졸음과 싸우다 그릇 속 약물이 떨리는 걸 봤다. 이쪽 손은 떨지 않는데.<br><br>약물이 그 사람 입 쪽으로 쏠린다. 그릇을 기울이지 않았는데.<br>그릇을 내려놓고 물러나 소금 테를 둘렀다. 입에서 나오려던 것이 소금 앞에서 도로 들어갔다. 그날 밤 약은 코 밑에 걸어 두는 것으로 바꿨다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'어둠 — 저린 손끝',
  x:`벽을 짚고 온 손끝이 저리다. 모두가 그렇다.<br><br>
    벽에 뭔가 발려 있는 것이다. 눈에 안 보이는 것이. 저림이 손목으로 천천히 올라온다.<br>
    마비는 약한 독이 아니다. 느린 독이다.<br><br>
    느린 것은 시간이 있다는 뜻이다. 약사한테 시간은 재료 다음으로 큰 밑천이다.`,
  o:[
    { l:'① 비벼 데우고 쓴 즙으로 닦아 낸다.', k:'heal', dc:24,
      ok:`손끝부터 팔꿈치까지 마른 천으로 세게 비볐다. 살갗이 붉어질 때까지. 독이 퍼지기 전에 겉에서 걷는 것이다.<br><br>그다음 쓴 즙으로 닦았다. 두 번.<br>저림이 손목에서 멈췄다 내려갔다. 다섯 손 모두. 벽은 그 뒤로 막대로만 짚었다.`,
      ng:`비비는 게 오히려 독을 문질러 넣은 꼴이 됐다. 이 독은 그런 독이었다.<br><br>저림이 팔꿈치까지 치고 올라왔다.<br>찬물에 팔을 담그고 한 시진을 보냈다. 손끝이 돌아올 때까지 아무도 아무것도 못 쥐었다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 벽의 가루를 조금 긁어 챙긴다.', k:'sense', dc:25, wake:1,
      ok:`닦기 전에 칼등으로 벽을 긁어 가루를 받았다. 종이에 싸서 세 겹.<br><br>사람을 저리게 하는 것은 저것들도 저리게 할지 모른다. 독은 돌려 쓰는 자의 것이다.<br>이틀 뒤 좁은 길목에서 그 가루를 뿌렸다. 따라오던 것이 길목에서 비틀거렸다. 세 걸음. 그 세 걸음이 다섯 목숨이었다.<br><br>독을 닦는 손과 독을 줍는 손. 같은 손이다. 여기서는 둘 다 써야 산다.`,
      ng:`긁다가 가루가 날렸다. 코로 들어왔다.<br><br>콧속부터 입천장까지 저려 온다. 맛도 냄새도 모르는 약사가 됐다. 한나절.<br>가루는 챙겼는데 그동안 물 간 것도 못 가려냈다. 비싼 수업료다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S', t:'갈림길 — 혀끝의 버릇',
  x:`길이 갈린다. 왼쪽 바닥에는 하얀 가루가 얇게 앉았고, 오른쪽은 맨돌이다.<br><br>
    하얀 것이 소금꽃인지 독가루인지에 따라 답이 다르다. 소금꽃이면 왼쪽에 물이 있다.<br>
    약방의 오랜 버릇이 손가락을 당긴다. 찍어서, 혀끝에.<br><br>
    고향 약방에서는 그 버릇으로 백 가지를 가렸다. 여기는 고향이 아니다.`,
  o:[
    { l:'① 혀 대신 겉가죽에 묻혀 한 식경 본다.', k:'steady', dc:24, wake:1,
      ok:`버릇을 눌렀다. 가루를 칼끝으로 떠서 신발 가죽에 묻혔다. 한 식경을 기다렸다.<br><br>가죽이 하얗게 일며 오그라들었다. 혀였으면 혀가 저랬다.<br>오른쪽 길로 갔다. 버릇 하나 누른 값이 혀 하나다.<br><br>혀끝 버릇을 땅에 맞춰 바꾸는 것. 아는 땅의 버릇과 모르는 땅의 법. 약사는 땅을 옮기면 버릇부터 다시 꾸린다.`,
      ng:`기다리는 사이 바람이 가루를 쓸어 갔다. 답도 같이 쓸려 갔다.<br><br>가려낼 것이 없으니 감으로 골라야 한다. 제일 싫은 방식이다.<br>오른쪽을 골랐다. 반 굽이 가서 길이 무너져 있었다. 되돌아와 왼쪽으로. 시간을 갑절로 썼다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 버릇대로 찍어 혀끝에 댄다.', k:'luck', dc:26,
      doom:{ title:'하얀 가루', what:'굳어 가는 몸으로 가루 주인에게 끌려갑니다', dc:19, sec:42,
        text:`버릇이 손보다 빨랐다. 찍고, 혀끝에 댔다.<br><br>짠맛을 기다렸다. 온 것은 단맛이다. 그리고 단맛 끝의 저림. 혀뿌리부터 목으로.<br>가루가 아니다. 말라붙은 침이다. 길목에 발라 두는. 왼쪽 길 안쪽에서 바닥 쓸리는 소리가 났다. 제 상에 앉은 것을 거두러 오는 소리.<br><br>무릎이 꺾인다. 혀끝 하나로 몸 전체가 값을 치른다. 끌려가며 생각했다. 고향 버릇이 여기서는 미끼 무는 버릇이구나.`,
        dieText:`갈림길 왼쪽 바닥의 하얀 것이 한 겹 더 두꺼워졌다.<br><br>새로 바른 것이다.<br>다음에 올 혀를 위해. 이 길목은 그렇게 차려지는 상이다.` },
      ok:`혀에 닿기 직전에 멈췄다. 가루에서 단내가 났다. 소금꽃에서는 안 나는 단내가.<br><br>단 것은 꾀는 것이다. 약이든 덫이든.<br>손가락을 바위에 문질러 닦고 오른쪽 길로 갔다. 왼쪽 안에서 무언가가 아쉬운 듯 바닥을 길게 쓸었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'약품실 — 글자 없는 약장',
  x:`약품실을 찾았다. 벽 한 면이 다 약장이다.<br><br>
    상표가 죄다 벗겨지고 색만 남았다. 안의 것은 가루, 알, 물. 수백 가지.<br>
    글자는 없어도 약장은 약장이다. 약장 꾸리는 법은 어디나 같다. 자주 쓰는 것은 손 닿는 데, 위험한 것은 잠긴 데.<br><br>
    여기 약사의 손버릇을 읽으면 된다.`,
  o:[
    { l:'① 손때와 자리로 약장을 읽는다.', k:'gaze', dc:24, wake:1,
      ok:`선반을 읽었다. 가슴 높이, 손때가 반질한 칸. 거기가 그 집 상비약이다. 열어 보니 가루들이 종류별로 묶여 있다.<br><br>맨 아래 잠긴 칸은 건드리지 않았다. 잠근 데는 잠근 이유가 있다.<br>상비약 묶음만 챙겼다. 쓰임은 색과 냄새로 하나씩 맞춰 가면 된다. 글자가 없어도 약장 주인과는 말이 통했다.<br><br>약장은 약사의 글씨다. 읽는 법을 여기서 한 벌 더 배웠다. 죽은 동업자한테서.`,
      ng:`읽는다고 읽었는데 상비약 칸이 비어 있었다. 먼저 다녀간 손이 있다.<br><br>남은 건 구석의 낯선 것들뿐이다.<br>색과 냄새로 두어 가지 추렸는데 확신이 없다. 확신 없는 약은 반 토막 약이다. 쓸 때마다 손에 땀이 날 것이다.`,
      win:{ exp:22, dream:3, item:'약초 뭉치' }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 병마다 조금씩 덜어 겉가죽에 시험한다.', k:'fix', dc:25,
      ok:`쓸 만해 보이는 병 열 개를 골라, 가죽 조각에 하나씩 묻혀 줄을 세웠다.<br><br>지지는 것 둘, 아무 일 없는 것 일곱, 가죽을 말랑하게 푸는 것 하나.<br>지지는 둘은 무기 칸, 일곱은 모름 칸, 푸는 것은 굳은 상처에 쓸 칸. 글자 대신 시험이 이름표다. 느리지만 틀리지 않는다.`,
      ng:`열째 병 마개가 삭아 있었다. 여는데 바스러지며 가루가 피어올랐다.<br><br>숨을 참고 물러났지만 눈이 맵다. 눈물이 줄줄 난다.<br>눈을 씻고 나니 세워 둔 가죽 줄이 뒤섞여 있었다. 누가 밟은 것이다. 처음부터 다시. 약품실에서 반나절이 갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S1', t:'실험대 — 녹이는 피의 답',
  x:`저것들의 피는 쇠도 녹인다. 벌써 신 한 짝과 칼 한 자루를 잃었다.<br><br>
    실험대 위에 여기 사람들이 쓰던 흔적이 있다. 태운 자국, 녹은 자국, 그리고 하얗게 중화된 자국.<br>
    하얀 자국 옆에 가루 통이 쓰러져 있다.<br><br>
    여기 사람들도 같은 답을 찾고 있었다. 끝냈는지는 모르지만, 어디까지 갔는지는 읽을 수 있다.`,
  o:[
    { l:'① 하얀 자국의 가루를 거두어 간을 맞춘다.', k:'heal', dc:25, wake:1,
      ok:`쓰러진 통의 가루를 긁어모았다. 녹은 자국 가장자리에 아주 조금 뿌려 봤다. 부글거리던 것이 하얗게 멎는다.<br><br>삭히는 가루다. 물에 개어 작은 병 셋에 나눴다. 피가 튀면 바로 끼얹는 약이다.<br>이틀 뒤 한 사람 팔뚝에 피가 튀었을 때, 병 하나가 팔뚝 하나를 그대로 지켰다.<br><br>독에는 독의 반대가 있다. 그 반대를 찾는 일. 여기 죽은 약사들이 반을 해 놨고, 나머지 반은 이쪽 몫이었다.`,
      ng:`가루가 바닥나 있었다. 통 바닥에 긁을 것도 없다.<br><br>자국만 보고 따라 만들 재주는 없다. 재료 이름도 모르는데.<br>빈 통만 챙겼다. 통 안쪽 냄새라도 기억해 두려고. 다음 약품실에서 같은 냄새를 찾는 수밖에.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 실험 일지의 그림만 훑는다.', k:'gaze', dc:24,
      ok:`일지는 못 읽는 글자다. 그림은 읽힌다. 피 한 방울, 화살표, 가루 통, 그리고 동그라미 안에 지워진 사람 그림.<br><br>마지막 장 그림은 달랐다. 가루를 몸에 바른 사람 그림에 가위표. 바르면 안 되고 끼얹기만 하라는 뜻이다.<br>그 가위표 하나가 약병 셋의 사용법이 됐다. 글자 없이도 유언은 남는다.`,
      ng:`그림을 훑는데 장마다 귀퉁이가 뜯겨 있다. 아귀가 안 맞는 그림만 남았다.<br><br>화살표가 어디서 와서 어디로 가는지를 모르겠다.<br>반쪽 지식은 안 쓰느니만 못할 때가 있다. 일지를 덮었다. 녹는 것 앞에서는 그냥 피하는 것으로 했다. 당분간은.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'③ 산 피를 떠다 직접 실험해 본다.', k:'luck', dc:26,
      doom:{ title:'실험대', what:'피 주인에게 발목을 잡혀 끌려갑니다', dc:20, sec:36,
        text:`죽은 자국만으로는 모자라다. 복도에 갓 흘린 하얀 피가 있었다. 유리 숟가락으로 떠서 실험대로 가져왔다.<br><br>가루를 섞자 피가 부글거리며 하얘진다. 된다. 더 떠 와야 한다. 복도로 다시 나갔다.<br>두 번째 숟가락을 뜨는데 피 웅덩이가 끌리듯 움직였다. 핏방울들이 한 방향으로. 주인 쪽으로.<br><br>천장에서 내려온 것이 발목을 잡았다. 제 피를 두 번 뜨러 온 손을, 그것은 기억하고 있었다. 실험은 성공했다. 결과를 전할 수 없을 뿐.`,
        dieText:`실험대 위에 하얗게 멎은 접시 하나가 남았다.<br><br>답은 맞았다. 접시가 증거다.<br>일행이 그 접시를 들여다보고 가루 통을 찾아냈다. 마지막 실험자의 몫까지 쓸 것이다.` },
      ok:`숟가락을 들고 복도까지 갔다가 돌아섰다. 갓 흘린 피는 주인이 가깝다는 뜻이라는 게 그제야 들렸다.<br><br>마른 피 딱지를 긁어 왔다. 산 피만큼은 아니어도 답은 나온다.<br>가루를 섞자 딱지가 하얗게 삭았다. 충분하다. 실험은 멀리 있는 재료로 하는 것이다. 여기서는.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'격리 병동 — 둘을 재우는 양',
  x:`가슴에 무언가 든 사람이 잠을 못 잔다. 속의 것이 밤마다 움직여서다.<br><br>
    재우는 약을 쓰면 되는데, 셈이 이상해진다. 사람 몫만 먹이면 사람만 자고 속의 것은 깬다.<br>
    자는 몸속에서 깨어 있는 것. 그게 제일 나쁜 그림이다.<br><br>
    둘을 같이 재워야 한다. 몸 하나에 든 둘을.`,
  o:[
    { l:'① 사람 몫 반, 속엣것 몫 반으로 나눠 먹인다.', k:'heal', dc:25, wake:1,
      ok:`한 번에 많이가 아니라 반씩 두 번으로 갔다. 먼저 사람 몫 반. 사람이 얕게 잠들자 속의 것이 느슨해진다. 숙주 따라 늘어지는 것이다.<br><br>그때 나머지 반. 늘어진 것한테 약이 같이 스몄다.<br>둘 다 잤다. 가슴이 밤새 잔잔했다. 그 사람이 몇 밤 만에 꿈 없이 잤다고 했다.<br><br>한 몸에 둘인 환자. 처방도 두 줄로 쓴다. 이 땅에서 새로 생긴 서식이다.`,
      ng:`반씩 가른다는 게 첫 반을 너무 작게 잡았다. 사람이 안 자고 몽롱하기만 하다.<br><br>몽롱한 사이 속의 것이 먼저 약 기운을 다 받아 마셨다. 그리고 멀쩡하다. 내성만 하나 얹어 줬다.<br>다음 밤부터 양을 더 써야 한다. 약은 주는데 빚은 이쪽이 지는 장사다.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 약 대신 가슴을 차게 식혀 재운다.', k:'fix', dc:24,
      ok:`찬 것에 느려지는 건 속엣것들의 공통이다. 여기 차트들도 그렇게 말했다.<br><br>찬물 적신 천을 가슴에 얹고 마를 때마다 갈았다. 속의 것이 느려지자 사람도 잠들었다. 약 한 톨 없이.<br>밤새 천을 가는 손만 바빴다. 약을 아끼는 밤은 손이 약값을 한다.`,
      ng:`식히는 게 과했다. 한밤에 그 사람이 덜덜 떨며 깼다.<br><br>몸이 식으니 속의 것이 더 깊이 파고들었다. 따뜻한 데로.<br>도로 데우느라 담요를 다 둘렀다. 식히는 것도 약이다. 약이면 양이 있다. 그걸 넘겼다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'S1', t:'복도 — 소독약 한 통',
  x:`쓰러진 청소 수레에서 소독약 한 통을 찾았다. 코를 찌르는 그 냄새다.<br><br>
    복도의 긁힌 자국들이 소독약 엎질러진 자리만 비켜 가 있다. 저것들이 싫어하는 냄새라는 뜻이다.<br>
    한 통뿐이다. 통째로 쓰면 하루, 아껴 쓰면 열흘.<br><br>
    묽히는 것은 약방 일이다. 어디까지 묽혀도 약인지 아는 것이.`,
  o:[
    { l:'① 묽혀 가며 듣는 끝 농도를 찾는다.', k:'fix', dc:25, wake:1,
      ok:`물에 열 배로 묽혀 복도 긁힌 자국에 발라 봤다. 다음 날 그 자리에 새 자국이 없다. 스무 배로 또 시험. 그래도 없다. 서른 배에서 새 자국이 났다.<br><br>스무 배. 그게 끝 농도다.<br>한 통이 스무 통이 됐다. 잠자리 둘레에 금 긋듯 뿌리면 밤이 조용했다.<br><br>약의 끝을 찾는 시험. 센 것을 더 세게가 아니라, 듣는 가장 묽음을 찾는 것. 약방 셈의 뼈대를 여기서 다시 세웠다.`,
      ng:`시험할 시간이 없어 어림으로 쉰 배를 묽혔다.<br><br>그날 밤 잠자리 금을 무언가 성큼 넘어 들어왔다. 물비린내 나는 맹물 금이었던 것이다.<br>놀라 깬 다섯이 반 시진을 대치했다. 다음부터는 진하게 썼다. 통이 사흘 만에 반이 됐다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 천에 적셔 다섯 목에 건다.', k:'heal', dc:24,
      ok:`천 조각 다섯에 소독약을 적셔 목에 하나씩 걸었다. 걸어 다니는 금이다.<br><br>복도에서 그것과 마주쳤을 때, 그것이 코를 한 번 킁 하더니 길을 비켰다. 싫은 냄새 다섯 덩이가 떼로 오니 비킨 것이다.<br>마를 때마다 다시 적셨다. 통은 줄었지만 길은 계속 열렸다.`,
      ng:`목에 건 천에서 소독약이 상처로 흘러든 사람이 나왔다.<br><br>쓰라려서 펄쩍 뛰었다. 소리까지 질렀다.<br>냄새로 길을 열고 소리로 길을 알렸다. 남는 게 없는 장사가 됐다. 천 거는 자리를 상처 반대쪽으로 다 고쳐 달았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S1', t:'표본실 — 잠 가루 포자',
  x:`표본실 구석 선반이 잿빛 곰팡이로 덮였다. 그 아래 작은 짐승 뼈 몇 구.<br><br>
    뼈에 다친 자국이 없다. 자다가 간 것처럼 웅크린 채다.<br>
    재우는 포자다. 건드리면 피고, 피면 잠들고, 잠들면 못 깬다.<br><br>
    독이자 약이다. 담을 수만 있으면. 약사 눈에는 선반 하나가 통째로 약재다.`,
  o:[
    { l:'① 젖은 천으로 입을 막고 병에 쓸어 담는다.', k:'heal', dc:25,
      ok:`천을 적셔 코와 입을 세 겹으로 막았다. 숨을 반만 쉬며 곰팡이를 깃털로 쓸어 병에 담았다. 날리지 않게, 쓰다듬듯.<br><br>두 병을 채우고 마개를 밀봉했다.<br>닷새 뒤 길목에서 이 병 하나가 뒤쫓던 것 하나를 재웠다. 세 걸음 만에. 선반의 잿빛이 다섯 목숨으로 바뀐 셈이다.`,
      ng:`쓸다가 깃털이 선반 모서리에 걸렸다. 포자가 훅 피었다.<br><br>젖은 천 너머로도 단내가 스몄다. 눈꺼풀이 바로 무거워진다.<br>병 하나만 쥐고 기다시피 나왔다. 문밖에서 한 식경을 꾸벅였다. 일행이 번갈아 뺨을 때려 깨웠다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 뼈의 자세로 포자의 반경을 잰다.', k:'gaze', dc:24, wake:1,
      ok:`뼈들을 봤다. 웅크린 뼈는 선반에서 두 걸음 안, 그보다 먼 뼈는 기던 자세다. 두 걸음이 바로 잠드는 금, 네 걸음이 버티다 쓰러지는 금.<br><br>금을 알면 쓸 수 있다. 긴 막대에 병을 묶어 세 걸음 밖에서 담았다.<br>반경을 재고 들어가는 채집. 뼈들이 남긴 측량이다.<br><br>죽은 것들의 자세가 눈금이 된다. 약재 앞에서 먼저 죽은 것들을 읽는 법. 이 선반에서 배웠다.`,
      ng:`금을 쟀는데 바람을 셈에 안 넣었다. 환기구 바람이 금을 한 걸음 밀었다.<br><br>세 걸음 밖이 두 걸음 안이 됐다.<br>하품이 연달아 나왔다. 병 반만 채우고 물러나 벽에 기대 반 시진을 졸았다. 깨워 준 손이 없었으면 선반 밑 뼈가 하나 늘 뻔했다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-18 } }
  ] },

{ at:'S1', t:'배양실 안쪽 — 어미의 냄새',
  x:`깨진 수조 안쪽 벽에 진액이 발려 있다. 그것들이 서로 몸을 비비고 간 자리다.<br><br>
    저것들은 서로를 안 문다. 냄새 때문이다. 한 어미 냄새.<br>
    그 냄새를 두르면 지나칠 수 있을지 모른다. 약사의 셈으로는 저 진액이 통행증이다.<br><br>
    통행증이 발린 벽은 깊다. 둥지 쪽으로 세 방은 더 들어가야 한다.`,
  o:[
    { l:'① 바깥 벽의 마른 진액만 긁어 쓴다.', k:'heal', dc:25, wake:1,
      ok:`깊이 안 갔다. 바깥 벽 마른 딱지만 긁어 기름에 개었다. 묽은 통행증이다.<br><br>다섯 발등과 어깨에 발랐다. 사람 냄새 위에 저들 냄새 한 겹.<br>복도에서 그것과 스쳤다. 그것이 코를 대고, 갸웃하고, 지나갔다. 묽어도 통했다. 완벽한 위조보다 어설픈 진짜가 낫다.<br><br>필요한 농도만큼만 위험을 사는 것. 깊은 데 짙은 것이 있어도 바깥 묽은 것으로 되면 거기서 끝. 약방의 담력은 들어가는 담력이 아니라 멈추는 담력이다.`,
      ng:`마른 딱지는 냄새가 반쯤 날아가 있었다.<br><br>복도에서 그것이 코를 대고, 갸웃하고, 다시 코를 댔다. 두 번째 킁킁이 길었다.<br>숨을 참는 시간이 한 해 같았다. 그것이 지나가고 나서 보니 발랐던 어깨가 땀으로 다 지워져 있었다. 반쪽 통행증이었다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 진액을 미끼 천에 발라 길을 꼰다.', k:'fix', dc:25,
      ok:`천 두 장에 진액을 발라 하나는 왼쪽 복도 깊이, 하나는 창고에 던져 뒀다.<br><br>제 어미 냄새가 엉뚱한 데서 나면 저것들은 확인하러 간다. 가족 일이니까.<br>그것들이 천 쪽으로 몰린 사이 가운데 복도를 다 건넜다. 냄새 두 장으로 길 하나를 통째로 샀다.`,
      ng:`던진 천 하나가 너무 가까이 떨어졌다. 확인하러 온 것이 이쪽 길목에 서 버렸다.<br><br>천 냄새를 맡고, 둘레 냄새를 맡고, 둘레에 이쪽이 있었다.<br>창고에 숨어 반 시진. 그것이 천을 물고 둥지로 돌아갈 때까지 숨으로만 살았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-18 } },
    { l:'③ 짙은 것을 찾아 안쪽 벽까지 들어간다.', k:'luck', dc:26,
      doom:{ title:'둥지 어귀', what:'둥지의 것들에게 붙들려 안쪽으로 끌려갑니다', dc:20, sec:35,
        text:`묽은 걸로는 못 미덥다. 안쪽으로 세 방을 더 들어갔다. 벽의 진액이 점점 짙어진다. 공기가 미지근해진다.<br><br>넷째 방 벽은 진액이 흐를 만큼 싱싱했다. 병 가득 담았다. 넉넉한 통행증이다.<br>돌아서는데 방 안쪽 어둠이 통째로 일어섰다. 벽이 아니라 등이었다. 비비고 간 자리가 아니라 비비는 중인 자리였다.<br><br>여럿의 손이 한꺼번에 왔다. 통행증은 손에 쥔 채다. 둥지 안쪽으로, 따뜻하고 축축한 쪽으로 끌려간다. 초대로 바뀐 통행증과 함께.`,
        dieText:`배양실 바깥 벽에 긁힌 자국 다섯 줄이 새로 났다.<br><br>안쪽에서 바깥쪽으로 긁은 자국이다.<br>자국은 넷째 방 문턱에서 끊겼다. 진액이 그 위로 한 겹 새로 발렸다.` },
      ok:`둘째 방에서 걸음을 세웠다. 벽의 진액에 김이 서려 있다. 갓 바른 것이다.<br><br>갓 바른 벽은 바른 몸이 가깝다는 뜻이다.<br>둘째 방 것만 반 병 긁어 물러났다. 욕심의 금을 둘째 방에 그었다. 금 밖에서 어미 냄새가 한 번 크게 울렸다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'약품실 안쪽 — 삭은 약들',
  x:`안쪽 방의 약들은 상태가 다 다르다. 몇 해를 버려진 것들이다.<br><br>
    삭은 약은 셋으로 갈린다. 힘 빠진 것, 딴것이 된 것, 그대로인 것.<br>
    힘 빠진 건 아깝고, 딴것이 된 건 무섭다.<br><br>
    셋을 가리는 눈이 있으면 이 방은 창고다. 없으면 함정이다.`,
  o:[
    { l:'① 색·냄새·결 세 가지로 추려 낸다.', k:'gaze', dc:25, wake:1,
      ok:`하나씩 들었다. 색이 변한 것은 내려놓고, 냄새가 시큼해진 것도 내려놓고, 가루가 떡진 것도 내려놓았다.<br><br>셋 다 통과한 것만 챙겼다. 열에 둘 꼴이다.<br>그 둘이 보름을 버텨 줬다. 지혈 가루와 열 내리는 알. 둘 다 끝까지 들었다.<br><br>세 겹 체로 거르는 손. 아까움이 체를 넓히자고 할 때마다 체를 지키는 것. 그게 삭은 약방에서 사는 법이다.`,
      ng:`아까움이 이겼다. 색만 괜찮은 것을 몇 개 더 담았다.<br><br>그중 하나가 딴것이 된 약이었다. 열 내리라고 먹인 알이 열을 올렸다.<br>한나절 생으로 앓게 만들었다. 약사가 준 약이 병이 되면, 그다음부터는 성한 약도 의심받는다. 그게 제일 큰 손해다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 그대로인 것만 찾아 밀봉 칸을 연다.', k:'fix', dc:24,
      ok:`낱개는 다 삭았어도 밀봉은 산다. 은박과 밀랍, 뜯지 않은 상자만 찾았다.<br><br>안쪽 벽장에서 밀봉 상자 둘. 뜯어 보니 가루가 어제 빻은 것 같다.<br>세월은 공기가 옮긴다. 공기를 못 만난 약은 세월도 못 만난 것이다. 봇짐이 든든해졌다.`,
      ng:`밀봉 칸을 여는데 경첩이 삭아 문짝째 떨어졌다. 요란하게.<br><br>약품실 밖 복도에서 무언가가 멈춰 서는 기척.<br>상자 하나만 안고 선반 뒤에 숨었다. 그것이 문간에서 한참 냄새 맡다 갔다. 남은 상자는 다음에. 다음이 있다면.`,
      win:{ exp:20, dream:3, item:'약초 뭉치' }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S2', t:'양치 숲 — 처음 보는 풀',
  x:`옛 세상의 풀밭이다. 아는 풀이 한 포기도 없다.<br><br>
    약사의 봇짐은 길에서 채워진다. 여기 풀이 여기 병을 고친다. 어느 땅이든 그랬다.<br>
    문제는 순서다. 모르는 풀은 겉가죽, 손목 안쪽, 입술, 혀끝 순으로 묻는다.<br><br>
    한 단계마다 한 식경. 지루한 만큼 안전한 사다리다.`,
  o:[
    { l:'① 사다리 순서대로 하루를 들여 세 가지를 가린다.', k:'heal', dc:24, wake:1,
      ok:`쓸 만해 보이는 세 가지를 꺾어 순서를 밟았다. 가죽, 손목, 입술, 혀끝. 한 식경씩.<br><br>하나는 손목에서 탈락, 하나는 입술이 얼얼해 탈락. 남은 하나가 끝까지 올라왔다. 씹으니 씀바귀 맛. 열 내리는 쪽이다.<br>옛 세상 약초 한 가지가 봇짐에 올랐다. 이름은 이쪽이 지었다.<br><br>모르는 땅의 약전은 이렇게 한 줄씩 쓰인다. 서두르면 약전이 아니라 비명이 쓰인다.`,
      ng:`둘째 풀이 손목 단계를 멀쩡히 넘고 입술에서 뒤늦게 크게 왔다.<br><br>입술이 두 배로 부었다. 느리게 오는 독이었다.<br>사다리가 틀린 게 아니라 식경이 짧았던 것이다. 이 땅 풀은 한 단계에 두 식경. 약전 첫 줄에 그것부터 적었다. 부은 입술로.`,
      win:{ exp:24, dream:3, item:'약초 뭉치' }, lose:{ hp:-26, mind:-15 } },
    { l:'② 병든 잎을 찾아 그 둘레만 딴다.', k:'sense', dc:25,
      ok:`풀밭을 훑다가 벌레 먹고도 성한 풀을 찾았다. 갉힌 자리가 아문 풀. 저 스스로 고치는 풀이다.<br><br>제 몸 고치는 풀은 남의 몸에도 듣는 수가 많다.<br>그 풀만 한 줌 땄다. 찧어서 상처 하나에 시험했더니 딱지가 하루 빨리 앉았다. 풀밭이 알려 준 처방이다.`,
      ng:`아문 자국이라 생각한 게 벌레집이었다.<br><br>찧는데 속에서 애벌레가 쏟아졌다. 약초가 아니라 알집을 딴 것이다.<br>쏟아진 것들이 꿈틀대며 흩어졌다. 소름이 가시기 전에 자리를 떴다. 빈손으로. 이 땅은 풀도 겉과 속이 다르다.`,
      win:{ exp:22, dream:3, item:'산나물' }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S2', t:'수풀 — 독침 벌레',
  x:`엄지만 한 벌레가 수풀에 떠다닌다. 꽁무니에 바늘을 달고.<br><br>
    쏘인 작은 짐승이 세 걸음 만에 굳는 걸 봤다. 죽지는 않았다. 한참 뒤에 깨서 비틀비틀 갔다.<br>
    굳히는 독. 죽이지 않고 굳히는 독은 약방에서 금값이다.<br><br>
    저 바늘 열 개면 쫓아오는 것들 다리를 한 번은 묶는다.`,
  o:[
    { l:'① 단내 나는 끈끈이로 덫을 놓는다.', k:'fix', dc:25, wake:1,
      ok:`꿀 반 술을 나무진에 개어 넓은 잎에 발랐다. 수풀 가장자리에 세 장.<br><br>반나절 뒤 잎마다 벌레가 서넛씩 붙어 있었다. 바늘째.<br>집게로 꽁무니만 떼어 작은 병에 모았다. 열둘. 던지는 마비약 열두 방이다.<br><br>독 가진 것한테 손을 내밀지 않고 독을 받는 법. 덫은 약사의 손이 길어지는 것이다.`,
      ng:`끈끈이가 묽었다. 붙었던 벌레들이 반나절 만에 다 떨어져 날아갔다.<br><br>남은 건 단내 나는 잎 석 장. 그리고 단내를 맡고 온 다른 것들.<br>잎 둘레에 뿔 달린 큰 벌레들이 끓었다. 덫을 거두지도 못하고 돌아섰다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 쏘인 짐승의 피를 받아 해독부터 만든다.', k:'heal', dc:25,
      ok:`굳었다 깬 짐승이 또 있었다. 깨어나는 놈 상처에서 피 몇 방울을 받았다.<br><br>이겨 낸 피에는 이긴 힘이 남는다. 그 피를 말려 가루에 섞었다.<br>훗날 일행 하나가 쏘였을 때 그 가루가 굳는 시간을 반으로 줄였다. 독과 해독을 한 수풀에서 같이 얻었다. 약방 장부로는 두 배 남는 날이다.`,
      ng:`피를 받는데 깨어나던 놈이 확 정신을 차렸다. 뒷발에 손등을 긁혔다.<br><br>놓친 짐승은 수풀로 달아나고 손등만 남았다.<br>긁힌 자국이 밤새 욱신댔다. 독 오른 발톱은 아니라서 다행이지, 해독 만들려다 해독 쓸 뻔했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-15 } },
    { l:'③ 떠다니는 놈을 맨손 그물로 쫓는다.', k:'luck', dc:26,
      doom:{ title:'벌레의 주인', what:'수풀 아래 것에게 물려 끌려갑니다', dc:19, sec:38,
        text:`천을 그물 삼아 쫓았다. 벌레가 수풀 안쪽으로 달아난다. 쫓아 들어갔다.<br><br>세 걸음, 다섯 걸음. 벌레가 갑자기 높이 떠올랐다. 덫 위에서는 날지 않는 법인데, 하는 생각과 발밑이 꺼지는 게 같이 왔다.<br>수풀 아래 엎드려 있던 것이 입을 벌리고 기다리고 있었다. 벌레들은 저것 둘레에 꼬이는 것들이었다. 남은 밥 찌꺼기에.<br><br>다리부터 물려 수풀 아래로 끌려간다. 벌레 한 마리 값으로는 너무 크다.`,
        dieText:`수풀 위로 벌레들이 다시 모여들었다.<br><br>아래에서 식사가 시작된 자리에는 늘 그것들이 꼬인다.<br>떨어뜨린 천 그물만 가지 끝에 걸려 나부꼈다.` },
      ok:`쫓다가 멈췄다. 벌레들이 수풀 한가운데 위로만 돈다. 둥글게.<br><br>꼬이는 데는 이유가 있다. 썩는 것 아니면 먹는 것.<br>가운데를 피해 가장자리에서 한 마리만 천으로 덮어 잡았다. 바늘 하나. 오늘은 그걸로 족하다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'물가 — 달라붙는 것들',
  x:`얕은 물을 건너고 보니 다리마다 검은 것들이 붙어 있다. 손가락만 한 것들이 피를 빨고 있다.<br><br>
    떼면 머리가 살에 남는 것들이다. 남은 머리는 곪는다.<br>
    여기서 곪는 냄새가 무엇을 부르는지는 다들 안다.<br><br>
    급한 손들이 벌써 잡아 뜯으려 한다. 그 손부터 잡아야 한다.`,
  o:[
    { l:'① 소금을 아껴 등에만 한 톨씩 얹는다.', k:'heal', dc:24,
      ok:`뜯으려는 손들을 쳐 냈다. 소금을 꺼내 한 마리 등에 한 톨씩만 얹었다.<br><br>검은 것들이 몸을 비틀며 제 입으로 떨어져 나온다. 머리째. 깨끗하게.<br>떨어진 자리를 눌러 피만 멎게 했다. 곪을 자리가 하나도 없다. 소금 한 줌이 다섯 다리를 지켰다.`,
      ng:`소금이 눅어 있었다. 얹어도 뭉친 채 굴러떨어진다.<br><br>결국 불붙인 잔가지 끝으로 지져 뗐다. 서두르다 둘은 손으로 뜯었다.<br>뜯은 자리 둘이 이틀 만에 발갛게 곪았다. 째고 씻는 일이 하나 더 늘었다. 눅은 소금 값이다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ hp:-26, spirit:-15 } },
    { l:'② 몇 마리는 병에 담아 간다.', k:'fix', dc:25,
      ok:`다 버리지 않았다. 통통한 놈 셋을 물 채운 병에 담았다.<br><br>피를 빠는 것들은 고인 피도 빤다. 멍들고 부은 자리에 얹으면 약이 된다. 옛 의원들 법이다.<br>사흘 뒤 발목 삔 사람 복사뼈에 한 마리를 얹었다. 검붉던 것이 하루 만에 가라앉았다. 징그러운 약이 제일 잘 듣는 날도 있다.`,
      ng:`병 마개를 덜 조였다. 봇짐 안에서 다 빠져나왔다.<br><br>봇짐 바닥에서 셋이 약초 뭉치에 엉겨 있었다. 즙을 빨아 홀쭉해진 뭉치와 퉁퉁해진 셋.<br>약도 잃고 약벌레도 못 쓰게 됐다. 약사 봇짐에서 약끼리 잡아먹는 꼴을 봤다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S2', t:'들판 — 자는 큰 것',
  x:`들판 한가운데 언덕이 숨을 쉰다. 언덕이 아니다. 자는 큰 것이다.<br><br>
    돌아가면 한나절, 곁을 지나면 한 식경. 깨어 있으면 못 지나가고, 자고 있으면 지나갈 수 있다.<br>
    문제는 잠의 깊이다. 겉잠인지 속잠인지.<br><br>
    잠을 재는 법이라면 약방에도 몇 가지 있다.`,
  o:[
    { l:'① 숨 간격과 콧김으로 잠의 깊이를 잰다.', k:'gaze', dc:25, wake:1,
      ok:`멀리서 숨을 쟀다. 들숨 길고 날숨 길고, 사이가 고르다. 콧김에 풀이 눕는 각도 일정하다. 속잠이다.<br><br>게다가 꼬리 끝이 가끔 떨린다. 꿈까지 꾸는 잠이다.<br>바람 아래쪽으로 한 사람씩 곁을 지났다. 큰 것의 갈비뼈가 산처럼 오르내리는 걸 옆에서 봤다. 다 건넌 뒤에도 숨 간격은 그대로였다.<br><br>사람 잠만 재던 눈금에 짐승 잠 눈금이 늘었다. 숨은 어느 몸에서나 정직하다. 그걸 믿는 게 약방이다.`,
      ng:`재는 중에 숨 간격이 한 번 흐트러졌다. 날숨 끝이 짧아졌다.<br><br>겉잠으로 떠오르는 중이다.<br>건너기를 접고 돌아가는 길을 택했다. 한나절 길. 멀리서 돌아보니 그것이 머리를 들고 아까 그 자리를 보고 있었다. 접길 잘했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 재우는 포자 반 병을 바람에 실어 보낸다.', k:'heal', dc:26,
      ok:`잠을 더 눌러 두기로 했다. 재우는 가루 반 병을 바람 위에서 천천히 흘렸다.<br><br>가루가 콧김에 빨려 들어간다. 숨이 한 뼘 더 깊어졌다. 꼬리 떨림도 멎었다.<br>다섯이 보통 걸음으로 곁을 지났다. 서두르지도 않고. 약 반 병으로 산 한나절이다.`,
      ng:`바람이 변덕을 부렸다. 가루 반이 엉뚱하게 흩어졌다.<br><br>남은 반만 들어갔다. 어설픈 양은 잠을 깊게 하는 게 아니라 간지럽힌다.<br>큰 것이 코를 벌름대더니 재채기를 했다. 들판이 울렸다. 다들 풀숲에 엎드려 반 시진을 굳어 있었다.`,
      win:{ exp:22, dream:4 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'S2', t:'둥지 터 — 삭은 껍데기',
  x:`버려진 둥지 터에 깨진 알껍데기가 쌓여 있다. 오래 삭아 희고 바삭하다.<br><br>
    삭은 껍데기는 갈면 속 쓰림과 신물에 듣는 가루가 된다. 뼈 붙는 데도 보탬이 되고.<br>
    약방 눈에는 여기가 노다지다.<br><br>
    다만 버려진 둥지와 비워 둔 둥지는 다르다. 그것부터 가려야 한다.`,
  o:[
    { l:'① 껍데기 삭은 정도로 둥지의 나이를 읽는다.', k:'gaze', dc:24,
      ok:`껍데기를 집어 눌러 봤다. 바삭 부서진다. 속막도 다 삭았다. 몇 해 묵은 터다.<br><br>둑 흙도 비에 뭉개진 채 그대로다. 돌보는 발이 끊긴 지 오래라는 뜻이다.<br>마음 놓고 자루 가득 담았다. 갈아서 체에 치니 고운 약가루가 두 줌. 옛 세상 알이 이쪽 속병을 다스리게 됐다.`,
      ng:`터 가장자리 것만 보고 묵은 터라 읽었다. 가운데 껍데기는 속막이 아직 눅진했다.<br><br>올해도 쓰는 터였다. 철이 아닐 뿐.<br>담다 말고 그 눅진함을 보고서야 등줄기가 식었다. 반 자루만 챙겨 서둘러 떴다. 철 지난 둥지의 주인은 멀리 안 간다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 껍데기 가루에 쓴 즙을 개어 바르는 약을 만든다.', k:'heal', dc:25, wake:1,
      ok:`그 자리에서 조제까지 했다. 껍데기를 돌로 갈고, 쓴 즙에 개어 되직한 고약을 만들었다.<br><br>마침 한 사람 정강이에 뼈까지 울린 멍이 있었다. 발라 보니 하루 만에 부기가 손가락 한 마디 내렸다.<br>길에서 줍고 길에서 짓는다. 봇짐 약방이 제대로 돌기 시작했다.<br><br>재료를 보면 약이 떠오르고, 환자를 보면 재료가 떠오른다. 양쪽이 이어진 날. 약사 평생 몇 안 되는 날이다.`,
      ng:`개는 즙의 양을 못 맞췄다. 묽어서 줄줄 흐른다.<br><br>바르면 흘러내리는 고약은 고약이 아니다.<br>다시 가루부터 갈았다. 해가 기울었다. 좋은 재료를 손이 못 따라가는 날도 있다. 그런 날은 빨리 접는 게 약이다.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S2', t:'승강기 앞 — 마지막 조제',
  x:`승강기까지 마지막 들판. 다들 다리가 풀려 있다.<br><br>
    봇짐에 심장을 때리는 가루가 있다. 한 꼬집이면 한 식경을 전력으로 뛴다. 두 꼬집이면 심장이 먼저 나간다.<br>
    다섯 몸이 다 다르다. 큰 몸, 마른 몸, 다친 몸.<br><br>
    같은 가루, 다섯 처방. 약사의 마지막 조제다.`,
  o:[
    { l:'① 몸마다 양을 달리해 다섯 봉지를 싼다.', k:'heal', dc:25, wake:1,
      ok:`한 사람씩 손목을 짚고 눈을 보고 양을 정했다. 큰 몸은 한 꼬집, 마른 몸은 반, 다친 몸은 반의반에 꿀을 섞어서.<br><br>출발 직전에 각자 제 봉지를 털어 넣었다.<br>들판을 다섯이 한 호흡으로 건넜다. 아무도 처지지 않고 아무 심장도 넘치지 않았다.<br><br>같은 약을 다섯 몸에 다섯 양으로. 약전의 마지막 장은 늘 사람 쪽에 있다. 들판 하나를 건너며 그 장을 다 읽었다.`,
      ng:`마른 몸 하나가 제 봉지가 적다고 남의 반을 얻어 먹었다.<br><br>들판 중간에서 그 사람 심장이 미친 북이 됐다. 얼굴이 하얘져서 비틀댄다.<br>양팔을 꿰어 끌다시피 뛰었다. 승강기에서 반 시진을 눕혀 놓고 맥을 세었다. 약은 나눠 먹으라고 있는 게 아니다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 가루 대신 단것과 호흡으로 다리를 깨운다.', k:'fix', dc:24,
      ok:`센 약은 접었다. 꿀 한 숟갈씩 돌리고, 출발 전에 무릎과 장딴지를 주물러 풀었다. 숨 고르는 박자도 맞췄다. 넷 들이쉬고 넷 내쉬고.<br><br>약 없이 깨운 다리들이 들판을 건넜다. 느리지만 고르게.<br>승강기에 타서도 아무도 손이 떨리지 않았다. 빚 없는 다리가 제일 멀리 간다.`,
      ng:`약 없이 가자는 말에 둘이 불안해했다. 가루 있는 걸 아는데 왜 안 쓰냐고.<br><br>설득에 시간을 쓰다 출발이 늦었다. 그늘이 들판 반을 덮은 뒤에야 뛰었다.<br>건너긴 건넜다. 마지막 스무 걸음은 수풀의 소리와 나란히 뛰었다. 아낀 약값을 간으로 치렀다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ mind:-18, spirit:-16 } },
    { l:'③ 시간이 없으니 다 같이 한 꼬집씩 삼킨다.', k:'luck', dc:26,
      doom:{ title:'넘친 심장', what:'굳어 쓰러진 채 수풀로 끌려갑니다', dc:20, sec:36,
        text:`잴 시간이 없다. 똑같이 한 꼬집씩. 공평하고 빠르다.<br><br>들판 삼분의 일에서 제일 마른 사람 심장이 넘쳤다. 다리가 풀리고 입술이 퍼레진다. 부축하려고 멈춘 이쪽 심장도 가루 탓에 미친 듯 뛴다.<br>멈춘 둘. 뛰는 셋은 벌써 저만치다. 수풀은 멈춘 것부터 챙긴다.<br><br>풀린 다리로는 버틸 수가 없다. 마른 사람을 감싼 채로 같이 끌려간다. 공평한 처방이 제일 불공평한 결과를 낳았다.`,
        dieText:`들판에 빈 약봉지 다섯 장이 날렸다.<br><br>똑같이 접힌 다섯 장.<br>몸은 다 다르다. 그 한 줄을 빼먹은 처방전이었다.` },
      ok:`봉지를 돌리다 멈췄다. 제일 마른 손목이 눈에 걸렸다. 이 손목에 한 꼬집은 두 꼬집이다.<br><br>그 봉지만 길에 반을 털었다. 셈은 셈이다. 아무리 급해도.<br>들판을 건너는 동안 그 마른 몸이 꼴찌로, 그러나 제 심장으로 뛰었다. 그거면 된 것이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'승강기 — 떨리는 손들',
  x:`쇠 바구니가 올라간다. 살았다. 그런데 다들 손이 떨린다.<br><br>
    뛸 때 눌러 둔 것들이 한꺼번에 올라오는 것이다. 겁도, 떨림도, 신물도.<br>
    몸이 셈을 끝내는 중이다. 약방은 이 셈도 거든다.<br><br>
    올라가는 동안이 마지막 진료다.`,
  o:[
    { l:'① 단것과 더운물로 속부터 가라앉힌다.', k:'heal', dc:24, wake:1,
      ok:`마지막 꿀을 더운물에 풀어 돌렸다. 한 모금씩. 천천히.<br><br>단것은 몸한테 끝났다고 말해 주는 신호다. 떨리던 손들이 그릇의 온기에 하나씩 가라앉았다.<br>꼭대기에 닿았을 때 다섯 손이 다 조용했다.<br><br>마지막 처방은 대개 약이 아니다. 더운물, 단맛, 그리고 끝났다는 말. 그 세 가지를 같이 내는 법을 배웠다.`,
      ng:`더운물을 돌리는데 바구니가 크게 출렁했다.<br><br>그릇이 엎어져 아까운 꿀물이 창살 사이로 샜다.<br>남은 건 맹물뿐이다. 맹물이라도 돌렸다. 떨림은 꼭대기까지 갔다. 거기서부터는 시간이 약이다. 제일 흔하고 제일 느린 약.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 남은 약재를 셈해 다음 봇짐을 꾸린다.', k:'fix', dc:23,
      ok:`올라가는 동안 봇짐을 다 폈다. 남은 것, 떨어진 것, 이 땅에서 새로 얻은 것.<br><br>셈을 마치니 들어올 때보다 봇짐이 낫다. 잃은 약보다 배운 약이 많다.<br>셈하는 손은 떨 새가 없다. 그래서 셈을 한 것이기도 하다. 바닥이 보일 때는 장부가 약이다.`,
      ng:`봇짐을 펴다 빈 칸이 너무 많은 걸 봤다. 지지는 약도, 재우는 가루도 바닥이다.<br><br>셈이 무서워졌다. 다음에 이런 데를 또 오면, 하는 생각에 손이 더 떨렸다.<br>장부를 덮었다. 어떤 날은 셈이 독이다. 그날은 그냥 올라가는 쇠 소리만 들었다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-16, spirit:-18 } }
  ] }

]);

// ------------------------------------------
// 의원 (physician) · 내공
// ------------------------------------------
kJob('physician', 'S', [

{ at:'S', t:'쉬는 자리 — 두 줄 맥',
  x:`쉬는 틈마다 돌아가며 맥을 짚는다. 오랜 버릇이다.<br><br>
    셋째 손목에서 손가락이 멎었다. 맥이 두 줄이다.<br>
    사람 맥 하나, 그리고 그 밑에서 반 박자 어긋나게 뛰는 가는 맥 하나.<br><br>
    한 몸에 두 맥은 없다. 의서 어디에도. 그러니 하나는 손님이다.`,
  o:[
    { l:'① 내공을 실처럼 흘려 손님의 자리를 찾는다.', k:'gaze', dc:24, cost:{ qi:28 },
      ok:`손목에서 내공을 가늘게 흘려 넣었다. 맥을 거슬러 올라가며 두 줄이 갈라지는 자리를 더듬었다.<br><br>팔꿈치 안쪽. 거기서 가는 맥이 샛길로 빠진다. 콩알만 한 것이 핏길 옆에 붙어 제 맥을 틀고 있다.<br>자리를 알면 반은 이긴 것이다. 그 자리를 짚어 핏길을 돌려 세웠다. 샛길이 마르자 가는 맥이 흐려졌다.<br>사흘 뒤 두 줄이 한 줄이 됐다. 손님이 굶어 나간 것이다.`,
      ng:`내공이 갈림길에 닿자 가는 맥이 숨었다. 뛰기를 멈추고 죽은 척을 한다.<br><br>맥으로 찾는 걸 아는 놈이다.<br>자리를 못 찾았다. 손을 뗀 지 한 식경 만에 가는 맥이 다시 뛰었다. 이쪽 셈을 다 보고 있다는 듯이.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 매일 같은 시각에 맥을 적어 놈의 때를 잰다.', k:'heal', dc:23, wake:1,
      ok:`아침저녁으로 짚어 수첩에 적었다. 사람 맥, 손님 맥, 나란히.<br><br>사흘 치가 모이자 결이 보였다. 손님 맥은 그 사람이 먹은 직후에 세진다. 얻어먹고 사는 놈이다.<br>끼니를 반으로 줄이고 쓴 것을 곁들였다. 손님 맥이 날로 가늘어졌다. 이레째 아침에 끊겼다.<br><br>병을 적는 붓이 칼이 되는 수가 있다. 맥의 장부로 손님을 굶겨 내보냈다. 의원의 싸움은 이렇게도 한다.`,
      ng:`적는 걸 들켰다. 그 사람이 수첩을 보고 제 몸에 뭐가 있냐고 떨기 시작했다.<br><br>겁먹은 맥은 장부를 망친다. 사람 맥이 널뛰니 손님 맥이 묻힌다.<br>적기를 멈추고 달래는 데 이틀이 갔다. 병자 모르게 적는 법부터 다시 배워야 했다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S', t:'어둠 — 다섯 숨',
  x:`좁은 틈에 다섯이 숨었다. 저쪽에서 그것이 어둠을 더듬으며 온다.<br><br>
    다섯 숨소리가 다 다르다. 겁에 질린 숨은 빠르고 얕고, 얕은 숨은 소리가 난다.<br>
    숨을 참게 하면 더 나쁘다. 참은 숨은 터질 때 크게 터진다.<br><br>
    숨을 고치는 것도 의원 일이다. 지금, 여기서는 제일 급한 일이다.`,
  o:[
    { l:'① 등에 손을 대고 숨 박자를 내공으로 이끈다.', k:'heal', dc:25, cost:{ qi:30 }, wake:1,
      ok:`옆 사람 등에 손바닥을 댔다. 내공을 느리게 밀고 당겼다. 들숨에 밀고 날숨에 당기고.<br><br>그 사람 숨이 손바닥을 따라왔다. 길고 깊게. 그 사람이 다음 사람 등에 손을 얹었다. 박자가 손에서 손으로 건너갔다.<br>다섯 숨이 한 숨이 됐다. 긴 숨 하나는 바위 틈 바람 소리와 같다.<br>그것이 틈 앞을 두 번 오가고 떠났다.<br><br>숨은 가르치는 게 아니라 옮기는 것이다. 손바닥으로 숨을 옮기는 법. 어둠이 가르쳐 준 의술이다.`,
      ng:`둘째 사람까지는 옮았다. 셋째 등에서 박자가 깨졌다. 그 사람 겁이 내공보다 셌다.<br><br>얕은 숨이 틈 밖으로 샜다.<br>그것이 틈 어귀에 코를 박았다. 콧김이 발등에 닿았다. 다섯이 눈만 뜬 채 한 식경을 죽어 있었다. 그것이 포기할 때까지.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 제일 거친 숨의 혈을 짚어 재운다.', k:'fix', dc:24,
      ok:`제일 숨이 거친 사람의 목덜미 혈을 짚었다. 지그시. 셋을 세고 뗐다.<br><br>그 사람이 스르르 늘어졌다. 잠든 숨은 느리고 고르다. 제일 큰 소리 하나가 꺼졌다.<br>남은 넷은 제 숨을 제가 다스렸다. 그것이 지나갈 때까지. 잠든 사람은 아침에 제일 개운해했다. 혼자만.`,
      ng:`혈을 짚는 순간 그 사람이 놀라 몸을 틀었다. 어둠 속에서 갑자기 목을 잡혔으니.<br><br>팔꿈치가 바위를 쳤다. 퍽.<br>그것이 홱 돌아섰다. 다행히 소리는 한 번뿐이었고, 바위 틈은 그것 머리보다 좁았다. 콧김만 반 식경을 들이쳤다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'③ 숨을 아예 죽이라고 손짓한다.', k:'steady', dc:24,
      ok:`손가락을 입에 대고, 가슴을 누르는 시늉을 했다. 다들 알아들었다. 숨을 바닥까지 낮췄다.<br><br>반만 쉬는 숨 다섯. 가슴이 타들어 가지만 소리는 없다.<br>그것이 지나갔다. 다 지나가고 쉰 첫 숨이 다섯 개 같이 터졌다. 그 소리가 제일 컸다. 다행히 그때는 멀었다.`,
      ng:`셋까지는 숨을 죽였다. 넷째가 참다 참다 턱 끝에서 터뜨렸다.<br><br>컥, 하는 소리. 참은 숨은 꼭 이렇게 갚는다.<br>그것이 틈으로 앞발을 넣었다. 발톱이 벽을 긁는 동안 다섯이 틈 안쪽으로 살을 맞대고 뭉쳤다. 앞발이 닿지 않는 반 뼘이 목숨이었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-18 } }
  ] },

{ at:'S', t:'쉬는 자리 — 빠진 어깨',
  x:`구르다 어깨가 빠진 사람이 있다. 팔이 이상한 각도로 늘어졌다.<br><br>
    맞추는 법은 안다. 문제는 맞출 때 나는 소리다. 뼈 소리가 아니라 사람 소리.<br>
    빠진 어깨를 맞추면 장정도 소리를 지른다.<br><br>
    여기서 비명 한 번이면 오늘 밤 자리는 끝이다.`,
  o:[
    { l:'① 혈을 눌러 팔을 재우고 나서 맞춘다.', k:'heal', dc:24, cost:{ qi:27 }, wake:1,
      ok:`어깨 밑 혈 두 곳을 내공으로 지그시 눌렀다. 팔이 그 사람 것이 아닌 듯 둔해졌다.<br><br>그때 당기고, 돌리고, 넣었다. 둑, 하는 느낌이 손에 왔다.<br>그 사람이 어리둥절해했다. 아픈 건 알겠는데 멀다고. 맞추고 나서 혈을 풀었다. 아픔이 돌아왔을 때 어깨는 이미 제자리였다.<br><br>아픔을 멈추는 게 아니라 멀리 보내 두는 법. 침상 없는 데서 뼈를 다루는 수를 하나 얻었다.`,
      ng:`혈이 반만 들었다. 당기는 순간 그 사람이 입을 열었다.<br><br>옆 사람이 손바닥으로 그 입을 덮어 비명을 반으로 줄였다.<br>어깨는 들어갔다. 소리도 반은 나갔다. 어둠 저쪽에서 돌 하나가 구르는 소리. 그날 밤 두 번 자리를 옮겼다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, spirit:-16 } },
    { l:'② 입에 천을 물리고 셋에 맞춘다.', k:'steady', dc:23,
      ok:`천을 접어 물렸다. 하나, 둘, 하고 셋 전에 당겼다. 셋을 기다리는 몸은 굳는다. 둘에서 가는 게 요령이다.<br><br>으읍, 하는 소리가 천에 다 먹혔다.<br>어깨가 들어가고, 그 사람이 천을 뱉고 욕을 했다. 작게. 욕이 나오면 다 된 것이다.`,
      ng:`둘에 당겼는데 각이 틀렸다. 안 들어갔다.<br><br>두 번째는 몸이 알고 굳는다. 천을 문 채 식은땀을 쏟는 사람을 한참 달래고 나서야 다시 당길 수 있었다.<br>세 번째에 들어갔다. 어깨는 제자리, 믿음은 반 자리. 둘 다 시간이 메워야 한다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S', t:'통로 — 걸으며 막는 피',
  x:`허벅지가 찢긴 사람을 부축해 걷는 중이다. 멈춰서 제대로 묶을 자리가 없다.<br><br>
    뒤에서 오는 것이 있다. 피는 걸음마다 샌다. 피가 새면 흘린 길이 생기고, 흘린 길은 안내판이다.<br>
    서면 잡히고, 걸으면 흘린다.<br><br>
    걸으면서 피를 막는 법. 의서에는 없다. 지금 쓰면서 걷는다.`,
  o:[
    { l:'① 짚은 혈을 걸음 박자로 바꿔 가며 누른다.', k:'heal', dc:25, cost:{ qi:32 },
      ok:`찢긴 자리 위쪽 혈에 엄지를 박고 같이 걸었다. 혈은 오래 누르면 다리가 죽는다. 백 걸음마다 옆 혈로 옮겼다.<br><br>누르고, 옮기고, 누르고. 엄지와 허벅지가 한 몸으로 걸었다.<br>반 굽이를 그렇게 갔다. 바닥에 떨어진 피는 처음 열 걸음 치뿐이다. 뒤의 것이 그 열 걸음 끝에서 한참 코를 박고 있었다. 길이 끊긴 자리에서.`,
      ng:`옮기는 박자를 한 번 놓쳤다. 눌렀던 다리가 저려 그 사람이 꺾였다.<br><br>둘이 엉켜 넘어졌다. 그 바람에 상처가 더 벌어졌다.<br>결국 멈춰서 묶었다. 제일 안 좋은 자리에서 제일 급한 손으로. 뒤의 기척이 반으로 줄어든 거리에서 들렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 업고 뛰며 다리를 심장보다 높인다.', k:'fix', dc:24,
      ok:`부축을 접고 업었다. 다리가 위로, 머리가 아래로 가게 거꾸로 둘러업었다.<br><br>피는 아래로 흐른다. 찢긴 다리가 심장보다 높으면 새는 양이 준다.<br>우스운 꼴로 반 굽이를 갔다. 내려 보니 피가 거의 안 샜다. 우스운 것과 사는 것 중에는 늘 사는 것이다.`,
      ng:`거꾸로 업힌 사람이 어지럼에 토했다.<br><br>토사물 냄새는 피 냄새만큼 간다.<br>자세를 도로 바꾸고 그냥 뛰었다. 피도 흘리고 냄새도 흘리고. 오늘 밤 이 통로는 이쪽 기록으로 도배가 됐다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S', t:'바닥 — 끊어진 맥',
  x:`앞서 걷던 사람이 소리 없이 무너졌다. 맥을 짚었다. 없다.<br><br>
    숨도 없다. 겉상처는 발목의 긁힌 자국 하나.<br>
    맥이 끊기고 얼마 안 됐다. 몸이 아직 따뜻하다. 불씨가 남은 아궁이다.<br><br>
    트인 자리라는 게 걸린다. 무너진 사람 둘레에 모인 그림은 여기서 제일 위험한 그림이다.`,
  o:[
    { l:'① 심장 혈에 내공을 바로 때려 넣는다.', k:'heal', dc:25, cost:{ qi:36 }, wake:1,
      ok:`가슴 한가운데 혈에 손바닥을 포개고 내공을 쳤다. 한 번, 숨 불어넣고, 또 한 번.<br><br>셋째에 가슴이 손바닥을 밀어 올렸다. 제 박자로.<br>맥이 돌아왔다. 거칠지만 돌아왔다. 둘러선 일행이 그제야 숨을 쉬었다.<br><br>내공으로 맥을 되살리는 수는 책으로만 알았다. 손은 오늘 처음 했다. 책의 수와 손의 수 사이에 죽은 사람 하나가 눕는다. 오늘은 아니었다.`,
      ng:`첫 번째, 두 번째, 내공이 심장에서 미끄러진다. 받는 그릇이 금 간 것처럼.<br><br>다섯 번을 치고서야 맥이 붙었다. 내공은 바닥까지 긁어 썼다.<br>그 사람은 살았다. 이쪽은 반나절을 빈 몸으로 걸었다. 빈 의원은 짐이다. 그 반나절 동안 아무 일도 없기를 비는 수밖에 없었다.`,
      win:{ exp:24, dream:4, hp:6 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 발목 긁힌 자국부터 짼다.', k:'gaze', dc:25,
      ok:`맥 짚은 손이 말했다. 끊긴 게 아니라 눌린 맥이라고. 누르는 것부터 치웠다.<br><br>긁힌 자국을 째자 가시 끝이 나왔다. 바늘만 한 것이 심줄 옆에 박혀 있었다. 뽑고 짜냈다.<br>뽑기가 무섭게 맥이 돌아왔다. 굳히는 독은 샘이 마르면 풀린다. 심장을 두드리기 전에 샘부터 찾은 게 맞았다.`,
      ng:`째고 뒤졌는데 아무것도 없다. 독이 아닌가, 하는 사이 시간이 갔다.<br><br>뒤늦게 가슴을 쳤다. 내공 반 통을 쓰고야 맥이 붙었다.<br>살긴 살았다. 그런데 발목 째는 데 쓴 그 몇 숨이 두고두고 걸린다. 갈림길에서 틀리면 사람이 늦는다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-18 } },
    { l:'③ 업고 가려진 데까지 옮겨 놓고 살핀다.', k:'luck', dc:25,
      doom:{ title:'멈춘 심장', what:'업힌 사람째 덮쳐져 끌려갑니다', dc:19, sec:44,
        text:`트인 자리가 불안했다. 맥 없는 몸을 업고 바위 쪽으로 뛰었다.<br><br>맥 없는 몸을 업고 뛰는 것. 그건 느린 것 하나에 죽은 것 하나를 얹은 그림이다. 이 들판에서 그보다 짙은 초대장은 없다.<br>바위 열 걸음 앞에서 옆구리에 무게가 왔다.<br><br>등에 업힌 사람과 함께 수풀로 끌려간다. 아궁이의 불씨를 살리겠다고 아궁이째 들고 뛴 값이다.`,
        dieText:`바위 앞 열 걸음에 끌린 자국 두 줄이 겹쳐 남았다.<br><br>한 줄은 끌려간 자국, 한 줄은 업혀 간 자국.<br>맥 없는 몸은 그 자리에서 다루는 것이다. 다음 의원은 그렇게 배울 것이다.` },
      ok:`업으려다 멈췄다. 맥이 끊긴 몸에게 지금 필요한 건 자리가 아니라 시간이다.<br><br>일행 셋을 등지고 세워 벽을 만들었다. 사람 벽 안에서 가슴을 쳤다.<br>셋째에 맥이 붙었다. 벽이 되어 준 등 셋은 아무것도 안 왔다고 했다. 와도 몰랐을 것이다. 다들 뒤돌아 있었으니까. 그게 벽의 일이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'어둠 — 침 한 대',
  x:`한 사람이 기침을 참고 있다. 목에 먼지가 걸린 것이다.<br><br>
    참는 기침은 눈물이 나게 참아도 결국 터진다. 그리고 이 어둠에서 기침 한 번은 종을 치는 것이다.<br>
    침통에 가는 침이 있다. 목의 간지럼을 끊는 혈이 있다.<br><br>
    어둠 속에서, 보이지 않는 목에, 가는 침 한 대. 손끝만 믿는 수밖에.`,
  o:[
    { l:'① 손끝으로 혈을 더듬어 어둠 속에서 놓는다.', k:'heal', dc:25, wake:1,
      ok:`왼손으로 목울대를 더듬어 혈 자리를 쟀다. 손가락 폭으로 하나, 둘. 오른손 침이 왼손 손톱 옆을 따라 들어갔다.<br><br>끝이 혈에 앉는 느낌. 지그시 돌리고 뺐다.<br>간지럼이 끊겼다고 그 사람이 손짓했다. 기침은 끝내 터지지 않았다.<br><br>보고 놓는 침과 더듬어 놓는 침. 후자가 진짜 손이라고 스승이 말했었다. 어둠이 그 말을 받아 적게 했다.`,
      ng:`어둠 속에서 혈을 반 푼 비껴 짚었다.<br><br>따끔함에 그 사람이 움찔하며 숨을 들이켰다. 그 들숨이 기침을 당겼다.<br>콜록. 한 번. 손바닥 두 개로 덮은 한 번. 어둠 저쪽이 조용해졌다. 듣는 조용함이었다. 다들 한참을 벽에 붙어 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 물로 삼키게 하고 목을 쓸어 준다.', k:'bond', dc:23,
      ok:`물병을 입에 대 주고 턱을 받쳤다. 세 모금. 그리고 목을 위에서 아래로 천천히 쓸었다.<br><br>걸린 것이 내려갔다. 간지럼이 가라앉았다.<br>침 없이 끝났다. 제일 흔한 수가 제일 조용한 수일 때가 있다. 물 세 모금 값이다.`,
      ng:`물이 급하게 넘어갔다. 사레가 들렸다.<br><br>기침 대신 켁켁대는 소리. 오십보백보다.<br>등을 두드릴 수도 없다. 그 사람이 제 주먹을 물고 버텼다. 눈물이 어둠 속에서 번들거렸다. 길고 조용한 사투였다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S', t:'쉬는 자리 — 식어 가는 몸',
  x:`비에 젖은 채 한나절을 걸은 사람이 떨기를 멈췄다.<br><br>
    떨기를 멈춘 게 더 나쁘다. 몸이 데우기를 포기한 것이다.<br>
    말이 느려지고 눈이 게을러졌다. 속이 식는 순서다.<br><br>
    불은 못 피운다. 그럼 남은 화로는 사람 몸뿐이다.`,
  o:[
    { l:'① 내공을 단전에서 데워 혈길로 흘려 넣는다.', k:'heal', dc:25, cost:{ qi:34 },
      ok:`등을 맞대고 앉아 손목과 등 가운데 혈에 손을 댔다. 단전에서 데운 내공을 가늘고 길게 흘렸다.<br><br>급히 데우면 겉만 덥고 속이 놀란다. 뜸 들이듯 반 시진.<br>그 사람 말이 돌아오고, 눈이 돌아오고, 마지막에 떨림이 돌아왔다. 떨림이 돌아오면 산 것이다. 몸이 다시 제 일을 시작했다는 뜻이니까.`,
      ng:`내공을 흘리는데 그 사람 몸이 받기만 하고 제 불을 안 지핀다.<br><br>이쪽 내공만 축난다. 붓는 족족 식는 독에 붓는 격이다.<br>결국 둘러앉아 담요째 껴안는 수로 바꿨다. 사람 넷이 화로가 됐다. 내공 반 통은 수업료다. 꺼진 아궁이에는 장작부터, 불씨는 그다음.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 마른 옷으로 갈아입히고 겨드랑이에 덥힌 돌을 끼운다.', k:'fix', dc:23,
      ok:`젖은 옷부터 벗겼다. 식는 몸에 젖은 옷은 얼음 갑옷이다.<br><br>마른 것으로 갈아입히고, 품에 덥힌 돌을 겨드랑이와 사타구니에 끼웠다. 굵은 핏길이 지나는 자리다.<br>속부터 데워졌다. 내공 한 톨 안 쓰고. 의원의 반은 이런 잔손이다.`,
      ng:`갈아입힐 마른 옷이 모자랐다. 서로 제 것을 벗어 주다 둘이 더 젖은 꼴이 됐다.<br><br>식는 사람이 둘로 늘 뻔했다.<br>결국 다섯이 한 담요에 겹쳐 눕는 밤이 됐다. 좁고 냄새나고, 그래도 아침에 다섯 다 더웠다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S', t:'길 — 땅의 맥',
  x:`땅이 가늘게 운다. 발바닥에 닿을 듯 말 듯.<br><br>
    맥 짚는 손은 떨림에 밝다. 손목이든 땅이든.<br>
    엎드려 손바닥을 대면 더 잘 읽힌다. 무엇이, 몇이서, 어느 쪽으로 가는지.<br><br>
    땅도 몸이다. 걷는 것들이 땅의 맥을 만든다.`,
  o:[
    { l:'① 엎드려 땅의 맥을 짚는다.', k:'sense', dc:24, wake:1,
      ok:`손바닥과 귀를 땅에 댔다. 울림이 넷. 박자가 가볍고 잘다. 작은 것들 넷이 왼쪽 앞에서 오른쪽으로 비껴간다.<br><br>그 뒤로 느리고 무거운 것 하나. 작은 것들을 따라가는 놈이다.<br>사냥 행렬이다. 길을 비켜 바위 뒤에서 한 식경 보냈다. 행렬이 다 지나간 다음의 길이 제일 빈 길이다.<br><br>사람 맥 너머의 맥. 손바닥 하나로 들판 전체를 진맥하는 법을 얻었다.`,
      ng:`울림을 세는데 울림이 갑자기 멎었다.<br><br>멎은 건 선 것이다. 선 것은 들은 것이다. 이쪽 발소리를.<br>엎드린 채 숨을 죽였다. 한참 뒤 울림이 다시 일었다. 멀어지는 쪽으로. 땅에 가슴을 댄 채 심장 소리가 땅으로 샐까 그게 걱정됐다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 일행 발걸음을 울림 박자에 숨긴다.', k:'hide', dc:25, cost:{ qi:26 },
      ok:`울림을 세며 손짓했다. 쿵, 할 때만 한 걸음. 멀리서 걷는 큰 것의 발 박자에 다섯 걸음을 포갰다.<br><br>큰 소리 밑에 작은 소리를 묻는 것이다.<br>박자 맞춰 들판을 건넜다. 땅 위의 모든 귀한테 이쪽 발소리는 큰 것의 메아리였다.`,
      ng:`박자가 바뀌는 걸 늦게 알았다. 큰 것이 걸음을 멈춘 것이다.<br><br>포개 둔 다섯 걸음이 맨땅에 그대로 울렸다.<br>멀리서 그것이 고개를 돌리는 기척. 전력으로 뛰어 바위틈에 몸을 구겼다. 빌린 박자는 주인이 멈추면 빚이 된다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S', t:'쉬는 자리 — 변한 맥',
  x:`어제까지 멀쩡하던 사람의 맥이 변했다. 뛰는 결이 다르다.<br><br>
    사람 맥은 울퉁불퉁하다. 걱정하고 설레고 지치고. 이 맥은 고르다. 너무 고르다. 자로 잰 것처럼.<br>
    몸은 그 사람인데 박자가 남이다.<br><br>
    의원은 얼굴보다 맥을 믿는다. 맥이 남이라고 말하고 있다.`,
  o:[
    { l:'① 아픈 혈을 일부러 짚어 몸의 답을 듣는다.', k:'gaze', dc:25, wake:1,
      ok:`누구나 아픈 혈이 있다. 눌리면 윽 소리가 나는 자리. 지나는 척하며 그 자리를 짚었다.<br><br>윽. 그 사람이 평소 그대로 아파했다. 맥은 고른데 아픔은 사람이다.<br>하루 더 지켜보니 답이 나왔다. 속에 든 것이 맥만 먼저 길들인 것이다. 사람은 아직 사람이다. 그럼 싸울 시간이 있다. 쓴 약과 뜸이 그날부터 시작됐다.<br><br>맥이 거짓말할 때 몸의 딴 데에 물어보는 법. 진맥 너머의 진맥이다.`,
      ng:`짚었는데 답이 없다. 아픈 혈이 안 아프다.<br><br>맥도 남, 아픔도 남. 어디까지 넘어간 건지 가늠이 안 된다.<br>그날 밤부터 그 사람 잠자리를 가운데로 옮겼다. 지키는 건지 갇힌 건지는 아직 말 안 했다. 양쪽 다라서.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 고른 박자를 흔들어 본다.', k:'fix', dc:25, cost:{ qi:31 },
      ok:`손목을 쥐고 내공을 한 번 툭 쳐 넣었다. 고른 맥에 돌 하나 던지듯.<br><br>맥이 출렁하더니 사람의 울퉁불퉁함이 돌아왔다. 놀라고, 두근대고, 가라앉는 결.<br>속에 든 것이 박자를 놓친 것이다. 그 틈에 쓴 것을 먹였다. 박자를 두 번 다시 못 잡게. 사흘을 흔들자 고른 맥이 다시는 안 왔다.`,
      ng:`친 내공을 그 고른 박자가 삼켰다. 출렁임도 없이.<br><br>그리고 이쪽 손끝으로 고른 박자가 거슬러 올라왔다. 손목까지. 제 박자를 나눠 주겠다는 듯이.<br>손을 뗐다. 한동안 이쪽 맥이 설었다. 진맥하는 손이 진맥당한 것은 처음이다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'③ 밤에 그 사람 맥이 이끄는 곳을 따라가 본다.', k:'luck', dc:26,
      doom:{ title:'고른 박자', what:'한밤의 걸음에 홀려 끌려갑니다', dc:19, sec:40,
        text:`밤에 그 사람이 일어나 걸었다. 자면서 걷는 걸음치고 너무 곧다. 맥이 고른 걸음이다. 소리 없이 따랐다.<br><br>그 사람이 어둠 한가운데 섰다. 그리고 돌아봤다. 자는 얼굴 그대로. 손목을 내민다. 진맥하라는 듯이.<br>버릇이 손을 뻗었다. 손목을 쥐는 순간 고른 박자가 손바닥으로 쏟아져 들어왔다.<br><br>다리가 저 혼자 걷는다. 그 사람과 나란히, 어둠 안쪽으로. 박자에 실려서. 뒤에서 일행이 부르는 소리가 박자 바깥에서 희미하다.`,
        dieText:`아침에 그 사람은 제자리에서 깼다. 맥도 사람으로 돌아와 있었다.<br><br>간밤 일을 아무것도 모른다.<br>의원의 자리만 비었다. 들고 다니던 침통이 어둠 쪽으로 가는 길에 떨어져 있었다.` },
      ok:`따라가다 걸음을 세웠다. 그 사람 발이 돌을 밟고도 안 아파한다. 맨발인데.<br><br>아픔이 꺼진 몸. 지금 저건 사람 쪽이 잠든 몸이다. 따라가서 깨울 수 있는 게 아니다.<br>돌아와 일행을 깨워 넷이서 끌어 왔다. 눕히고 발바닥을 바늘로 살짝 찔렀다. 움찔했다. 아픔이 돌아오는 자리부터 사람이 돌아온다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'어둠 — 풀린 눈',
  x:`한 사람 눈이 풀렸다. 겁이 어느 금을 넘은 것이다.<br><br>
    묻는 말에 답이 반 박자 늦다. 걸음이 떠 있다. 이대로면 어둠 속에서 혼자 엉뚱한 데로 걷는다.<br>
    혼이 몸에서 반 뼘 뜬 상태. 의서는 이걸 이탈 직전이라 적는다.<br><br>
    몸에 도로 앉혀야 한다. 지금.`,
  o:[
    { l:'① 인중과 손끝 혈을 세게 짚는다.', k:'heal', dc:24, wake:1,
      ok:`인중을 엄지로 세게 눌렀다. 동시에 가운뎃손가락 끝을 손톱으로 꾹.<br><br>아픔은 제일 빠른 길이다. 뜬 혼을 몸으로 당기는.<br>그 사람이 억 소리를 내며 눈의 초점을 되찾았다. 아프냐고 물으니 아프다고 성을 낸다. 성내는 사람은 돌아온 사람이다.<br><br>혼을 붙드는 혈 두 개. 손가락 두 개로 사람을 돌려 앉히는 수를 이 어둠에서 처음 제대로 썼다.`,
      ng:`혈을 짚었는데 반응이 약하다. 너무 멀리 뜬 것이다.<br><br>이름을 부르며 볼을 두드렸다. 조용히 할 수 있는 건 다 했다.<br>돌아오긴 했는데 한 식경이 걸렸다. 그동안 한 손은 그 사람 허리띠를 꽉 쥐고 있었다. 혼보다 몸이 먼저 걸어 나갈까 봐.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 손을 잡히고 익은 일을 시킨다.', k:'bond', dc:24,
      ok:`그 사람 손에 붕대 뭉치를 쥐여 줬다. 감아라. 내 팔에.<br><br>손이 기억하는 일은 혼보다 가까이 있다. 그 사람 손가락이 더듬더듬 감기 시작했다.<br>세 바퀴째부터 손놀림이 야물어졌다. 감기를 마친 눈에 초점이 돌아와 있었다. 일이 사람을 당겨 앉힌 것이다.`,
      ng:`붕대를 쥐여 줬는데 그 사람이 그걸 물끄러미 보기만 한다.<br><br>그러다 붕대를 풀기 시작했다. 감는 게 아니라 풀어서, 바닥에, 길게.<br>어둠 쪽으로 붕대 길을 내는 손을 급히 잡았다. 뭘 부르는 길인지 알고 싶지 않았다. 붕대는 태웠다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'S', t:'갈림길 — 두 길의 숨',
  x:`굴이 둘로 갈린다. 둘 다 어둡고 둘 다 깊다.<br><br>
    손바닥을 들자 바람이 읽힌다. 왼쪽 굴은 바람이 한결같다. 오른쪽 굴은 바람이 느리게 들고 난다.<br>
    들고 나는 바람. 맥 짚는 손은 그걸 안다. 숨이다.<br><br>
    굴이 숨을 쉬는 게 아니다. 굴 안의 무언가가 쉬는 것이다.`,
  o:[
    { l:'① 숨 쉬는 굴을 피해 왼쪽으로 간다.', k:'sense', dc:24, wake:1,
      ok:`오른쪽 굴 어귀에 손바닥을 대고 한 식경 쟀다. 들숨 길고 날숨 길고. 크고 깊은 것의 잠든 숨이다.<br><br>왼쪽으로 갔다. 한결같은 바람은 뚫린 바람이다. 뚫린 길은 끝이 있다.<br>반나절 만에 바깥 공기가 섞여 들었다.<br><br>길에도 맥이 있고 숨이 있다. 들고 나는 것은 다 진맥이 된다. 굴 앞에서 의서가 한 장 늘었다.`,
      ng:`왼쪽으로 들어서고 한참 뒤에 바람이 변했다. 한결같던 것이 끊겼다 이어졌다 한다.<br><br>앞에서 무언가가 길을 막았다 비켰다 하는 것이다.<br>벽에 붙어 반 식경을 기다렸다. 막던 것이 제 갈 데로 가고서야 지나갔다. 바람은 정직한데 바람의 이유까지는 안 가르쳐 준다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 숨의 임자를 확인하러 오른쪽으로 든다.', k:'luck', dc:26,
      doom:{ title:'굴의 숨', what:'굴 안쪽 숨에게 빨려 들어갑니다', dc:19, sec:42,
        text:`숨의 임자가 뭔지 알아야 피하든 돌든 할 것 아닌가. 오른쪽으로 들었다.<br><br>바람이 점점 축축해진다. 그리고 따뜻해진다. 벽이 매끈해진다. 돌이 아니라.<br>디딘 바닥이 물컹, 내려앉았다. 굴이 아니었다. 굴 모양으로 입을 벌리고 숨 쉬는 것이었다.<br><br>들숨이 시작됐다. 바람이 아니라 끌림이다. 발이 끌리고, 무릎이 끌리고, 안쪽의 젖은 어둠으로 미끄러져 들어간다.`,
        dieText:`오른쪽 굴의 숨이 한동안 멎었다.<br><br>삼킨 것을 내리는 동안은 숨을 참는 모양이다.<br>반 시진 뒤 굴은 다시 느리게 숨을 쉬었다. 갈림길에 침통 하나가 떨어져 있었다.` },
      ok:`열 걸음 들어가다 멈췄다. 발바닥에 전해지는 바닥의 느낌이 변했다. 단단한데, 아주 미세하게 오르내린다.<br><br>맥이다. 바닥에 맥이 뛴다.<br>살아 있는 바닥은 밟는 게 아니다. 발소리를 죽여 되돌아 나왔다. 어귀를 벗어나자 등 뒤에서 굴이 길게 숨을 내쉬었다. 아쉬움처럼.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'표본실 — 낯선 몸의 지도',
  x:`해부대 위에 저것들 사체 하나가 펼쳐져 있다. 여기 사람들이 열다 만 것이다.<br><br>
    의원의 눈은 몸을 보면 지도부터 그린다. 핏길, 숨길, 급소.<br>
    사람 지도는 눈 감고도 그린다. 이 몸의 지도는 백지다.<br><br>
    백지를 채울 기회다. 산 것한테는 못 물어볼 것을 죽은 것한테 묻는다.`,
  o:[
    { l:'① 핏길을 따라가 심장 자리를 찾는다.', k:'gaze', dc:25, wake:1,
      ok:`굵은 핏대를 짚어 거슬러 올라갔다. 가슴이 아니라 목 뒤. 딱딱한 판 밑에 주먹만 한 심장이 숨어 있다.<br><br>겉가죽이 제일 얇은 자리도 찾았다. 턱 밑, 그리고 겨드랑이 안쪽.<br>지도가 그려졌다. 사흘 뒤 복도에서 마주쳤을 때 창 끝이 망설임 없이 턱 밑으로 갔다. 백지였으면 다섯이 거기서 끝났다.<br><br>적의 몸도 몸이다. 몸을 아는 것이 의원의 무기가 되는 순간이 있다. 해부대 앞에서 그 문장을 얻었다.`,
      ng:`핏길을 따라가는데 길이 중간중간 녹아 있다. 제 피에 제 속이 삭은 것이다.<br><br>지도가 군데군데 끊긴 채로 그려졌다.<br>심장 자리는 끝내 못 찾았다. 목 뒤 아니면 배 속 어딘가. 반쪽 지도라도 없는 것보다는 낫다고 믿기로 했다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 독주머니부터 찾아 떼어 둔다.', k:'heal', dc:25,
      ok:`칼을 대기 전에 짚이는 데부터 눌러 봤다. 턱 양옆이 물컹하다. 주머니 둘.<br><br>겉가죽째 넓게 돌려 떼어 그릇에 받았다. 한 방울도 안 흘리고.<br>떼어 낸 주머니는 좋은 약재다. 저것들 피에 삭는 쇠도 이 주머니 안쪽 막은 멀쩡하다. 그 막으로 약병 마개를 쌌다. 녹는 피를 담을 수 있는 병이 생겼다.`,
      ng:`주머니 하나가 칼끝에 터졌다.<br><br>해부대가 부글거리며 꺼졌다. 쇠 대가 엿가락처럼 휘었다.<br>뒤로 뛰어 물러나 한 방울도 안 맞았다. 사체와 지도 반쪽이 해부대와 함께 내려앉았다. 죽어서도 무는 몸이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S1', t:'격리 병동 — 가는 맥을 묶는 침',
  x:`가슴에 든 것이 자라는 사람. 맥이 두 줄인 그 병이다.<br><br>
    여기 병동 차트에 침 그림이 있다. 사람 그림의 가슴 둘레에 점 아홉 개.<br>
    아홉 혈에 침을 세우면 가는 맥이 갇힌다는 뜻 같다. 울타리처럼.<br><br>
    여기 의원들이 찾아낸 수다. 끝까지 썼는지는 모르지만, 그림은 남겼다.`,
  o:[
    { l:'① 그림대로 아홉 혈에 침을 세운다.', k:'heal', dc:26, cost:{ qi:38 }, wake:1,
      ok:`숨을 고르고 아홉 자리를 쟀다. 사람 혈 자리와 여덟은 겹치고 하나만 낯설다. 낯선 하나까지 그림대로.<br><br>아홉째 침이 서자 손끝에 느낌이 왔다. 가는 맥이 울타리 안에서 맴돈다. 넓어지지도 뻗지도 못하고.<br>그 사람 숨이 깊어졌다. 몇 밤 만에 처음으로.<br><br>남이 그린 침 그림을 제 손으로 완성했다. 죽은 의원들과 산 의원이 한 환자를 같이 본 것이다. 의술은 이렇게 이어지는 것이다.`,
      ng:`여덟째까지는 섰다. 아홉째, 낯선 자리에서 손이 흔들렸다.<br><br>반 푼 비껴 꽂혔다. 울타리에 틈이 났다.<br>가는 맥이 그 틈으로 가늘게 샌다. 다 가두지 못했다. 그래도 여덟 개 값은 한다. 자라는 속도가 눈에 띄게 줄었다. 아홉째 자리는 내일 다시.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 먼저 제 팔에 비슷한 혈을 시침해 본다.', k:'steady', dc:24,
      ok:`남의 가슴에 꽂기 전에 제 팔뚝의 비슷한 혈 세 개에 놓아 봤다. 깊이와 손맛을 몸으로 재는 것이다.<br><br>둘째 혈에서 깊이를 반 푼 고쳐 잡았다. 그림에는 깊이가 없었다.<br>그다음 환자에게 갔다. 아홉 침이 한 번에 섰다. 제 살로 먼저 치른 연습 값이다.`,
      ng:`제 팔에 놓은 셋째 침이 저릿하게 잘못 들어갔다.<br><br>오른손이 반나절 무뎌졌다. 시침하는 손이.<br>환자 침은 다음 날로 밀렸다. 그사이 가는 맥이 한 뼘 자랐다. 연습이 본 일을 미루면 연습이 아니다. 순서를 배웠다. 아픈 쪽으로.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'③ 침 대신 달군 돌로 가슴을 지진다.', k:'luck', dc:26,
      doom:{ title:'놀란 손님', what:'깨어난 것이 숙주째 몰고 어둠으로 사라집니다', dc:20, sec:36,
        text:`침은 아홉 번의 위험이다. 뜸이면 한 번에 끝난다. 달군 돌을 천에 싸서 가슴 한가운데 얹었다.<br><br>열이 스미자 가는 맥이 미쳐 날뛰었다. 재우는 것도 가두는 것도 아닌, 쫓는 열. 쫓기는 것은 달아난다. 집을 몰고.<br>환자가 벌떡 일어났다. 눈이 뒤집힌 채. 돌을 쳐 내고 문 쪽으로 내닫는다.<br><br>팔을 붙들었다. 질질 끌려간다. 복도로, 어둠으로. 그림에 뜸이 없던 이유를 온몸으로 배우면서.`,
        dieText:`병동 바닥에 식은 돌과 뒤집힌 침상이 남았다.<br><br>차트 마지막 장 귀퉁이에 불 그림이 있고 가위표가 쳐져 있었다.<br>늦게 본 가위표다. 여기 의원들도 같은 값을 먼저 치렀던 모양이다.` },
      ok:`돌을 달구다 차트를 한 번 더 넘겼다. 마지막 장 귀퉁이, 불 그림에 가위표.<br><br>먼저 간 이들이 쳐 놓은 가위표다. 열은 안 된다는 뜻이다.<br>돌을 내려놓고 침통을 열었다. 남의 실패는 공짜 수업이다. 받아 적는 사람한테만.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'기밀문 — 으스러진 팔',
  x:`닫히는 문에서 사람은 빼냈다. 팔이 값을 치렀다. 팔뚝 뼈 두 대가 다 갔다.<br><br>
    퉁퉁 붓는 중이다. 맞출 거면 더 붓기 전에 맞춰야 한다.<br>
    복도 끝에서 쇠 긁는 소리가 간간이 온다. 저쪽도 이 문 소리를 들었을 것이다.<br><br>
    빠른 손과 바른 손. 오늘은 둘 다여야 한다.`,
  o:[
    { l:'① 내공으로 부기를 가르며 뼈를 맞춘다.', k:'heal', dc:26, cost:{ qi:35 },
      ok:`부은 살에 내공을 흘려 핏물을 양옆으로 갈랐다. 손끝에 뼈 끝이 만져진다. 두 대를 차례로 당겨 맞췄다.<br><br>딱, 딱. 자리 무는 느낌 두 번.<br>부목을 대고 감았다. 쇠 긁는 소리가 오기 전에 끝났다. 부기 너머를 더듬는 손은 내공이 등불이다.`,
      ng:`한 대는 맞았는데 둘째 대가 어긋난 채 물렸다.<br><br>다시 당기자니 환자가 혼절 직전이다. 쇠 소리는 가까워지고.<br>어긋난 채로 부목을 댔다. 나중에 한 번 더 부러뜨려 맞춰야 한다. 그 말은 아직 안 했다. 오늘 치 아픔은 오늘 치로 족하다.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 침으로 팔의 감각부터 끊고 맞춘다.', k:'fix', dc:25,
      ok:`어깨 안쪽 혈에 침 둘을 세웠다. 팔이 환자 것이 아니게 됐다.<br><br>느긋하게 맞췄다. 당기고, 돌리고, 물리고. 환자는 남의 팔 구경하듯 봤다.<br>침을 뽑자 아픔이 돌아왔지만 뼈는 이미 집에 간 뒤다. 아픔은 셋집만 털고 갔다.`,
      ng:`침이 환자의 떨림에 밀려 얕게 섰다. 감각이 반만 끊겼다.<br><br>당기는 순간 환자가 반 토막 비명을 질렀다.<br>복도의 쇠 소리가 뚝 멎었다. 듣는 멈춤이다. 맞추다 만 팔을 안고 넷이서 옆방으로 숨었다. 반 시진 뒤에 마저 맞췄다. 떨리는 손으로.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S1', t:'수술실 — 쇠 바늘들',
  x:`수술실 서랍에 바늘이 가득하다. 곧은 것, 굽은 것, 실 꿴 것.<br><br>
    이쪽 침통의 침은 닷새째 삶지 못했다. 여기 것은 봉지째 밀봉이다.<br>
    의원 손에 연장 서랍이 통째로 들어온 셈이다.<br><br>
    다만 서랍이 반쯤 열린 채였다. 누가 먼저 뒤진 서랍이다. 급하게.`,
  o:[
    { l:'① 쓸 것만 골라 침통을 새로 꾸린다.', k:'fix', dc:24, wake:1,
      ok:`욕심 안 내고 골랐다. 곧은 바늘 아홉, 굽은 것 셋, 실 꿴 것 여섯. 침통 한 벌 분량만.<br><br>천에 줄줄이 말아 품에 넣었다. 소리 안 나게 한 벌.<br>이 땅에 와서 처음으로 연장이 몸보다 든든하다.<br><br>연장을 고르는 눈도 의술이다. 다 가지려는 손은 느리고, 느린 손은 여기서 제일 비싸다. 한 벌의 무게를 배웠다.`,
      ng:`고르는데 서랍 안쪽 깊이 손을 넣었다가 찔렸다. 누가 거꾸로 꽂아 둔 바늘에.<br><br>남이 뒤진 서랍은 남의 급함까지 들어 있다.<br>찔린 손가락을 짜고 소독했다. 바늘은 얻었는데 시침하는 손가락이 이틀 부었다. 연장 값치고 묘한 값이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 수술대 밑 핏자국부터 읽는다.', k:'gaze', dc:25,
      ok:`서랍보다 바닥이 먼저 눈에 들어왔다. 수술대 밑 핏자국. 사람 피 색과 하얀 얼룩이 겹쳐 있다.<br><br>여기서 사람을 열다가 하얀 피가 나온 것이다. 속에 든 것을 째다가.<br>그 순서로 보면 서랍을 뒤진 급함도 읽힌다. 산 채로 열면 안 되는 것이다. 공책에 적었다. 산 채로 열지 말 것. 바늘보다 비싼 수확이다.`,
      ng:`핏자국을 읽느라 바닥에 너무 오래 쪼그려 있었다.<br><br>수술대 밑 어둠과 눈이 맞았다. 어둠 속에 웅크린 것이 있었다. 작고, 젖은 것이.<br>그것이 환풍구로 튀어 달아났다. 서랍이고 뭐고 바늘 한 줌만 쥐고 나왔다. 그 방에서는 그 이상 못 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S1', t:'복도 — 아픔을 끄는 혈',
  x:`산성 피가 튄 상처는 씻어도 아픔이 남는다. 데인 아픔이 뼈까지 울린다.<br><br>
    한 사람이 그 아픔으로 걷지를 못한다. 소리를 삼키는 데 힘을 다 써서.<br>
    기밀문 두 개를 더 지나야 쉴 자리가 나온다.<br><br>
    아픔을 지울 수는 없다. 끌 수는 있다. 잠깐씩.`,
  o:[
    { l:'① 아픔의 길목 혈을 짚어 반나절을 끈다.', k:'heal', dc:25, cost:{ qi:33 }, wake:1,
      ok:`덴 자리에서 심장으로 가는 길목, 세 혈을 차례로 눌러 내공을 채웠다. 아픔이 다니는 길에 수문을 세운 것이다.<br><br>그 사람 어깨가 풀렸다. 아픔이 안 올라온다고 했다. 걸음이 돌아왔다.<br>반나절 뒤 수문이 풀리기 전에 쉴 자리에 닿았다. 거기서는 소리 내고 아파도 된다. 아픔에도 낼 자리가 있는 법이다.<br><br>아픔을 길로 보는 눈. 막을 수 있는 것은 길목이 있는 것뿐이다. 그 길목 셋을 오늘 외웠다.`,
      ng:`수문 하나가 일찍 풀렸다. 기밀문 사이 복도 한가운데서.<br><br>밀렸던 아픔이 한꺼번에 왔다. 그 사람이 주저앉으며 신음을 쏟았다.<br>복도 양끝 문을 다 닫고 그 사이에서 반 식경을 버텼다. 문 하나 너머로 무언가 지나가는 소리를 들으며.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 아픈 쪽 반대 손에 더 큰 자극을 준다.', k:'fix', dc:24,
      ok:`성한 손바닥에 침 하나를 얕게 세워 쥐게 했다. 걸을 때마다 따끔하게.<br><br>몸은 큰 소리 하나만 듣는다. 새 따끔함이 묵은 아픔을 가렸다.<br>기밀문 둘을 그 침 한 대로 건넜다. 속임수다. 몸에게 쓰는 착한 속임수.`,
      ng:`쥔 침이 너무 깊이 섰다. 가리려던 자극이 새 상처가 됐다.<br><br>이제 아픈 데가 둘이다.<br>침을 빼고 그냥 업었다. 업는 게 처음부터 답이었는지도 모른다. 꾀가 손보다 앞서면 이런 날이 온다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S1', t:'환기구 — 쇠관의 맥',
  x:`갈림길 천장마다 환기구가 지난다. 어느 관에 그것들이 다니는지 알면 길이 보인다.<br><br>
    맥 짚는 손이 쇠관이라고 못 짚을 것 없다.<br>
    관에 손을 대면 울림이 온다. 빈 관의 울림과 안에 무언가 기는 관의 울림.<br><br>
    문제는 손을 대려면 관 바로 밑에 서야 한다는 것이다.`,
  o:[
    { l:'① 막대 끝을 관에 대고 떨림을 읽는다.', k:'sense', dc:25, wake:1,
      ok:`맨손 대신 쇠막대를 관에 대고 막대 끝을 손가락으로 짚었다. 떨림이 막대를 타고 내려온다.<br><br>왼쪽 관은 고르게 웅웅댄다. 바람뿐이다. 오른쪽 관은 웅웅거림 사이에 긁힘이 섞인다. 기는 것이 있다.<br>왼쪽 복도로 갔다. 머리 위가 조용한 길로만.<br><br>진맥에 길이가 생겼다. 손끝에서 막대 한 대만큼. 닿을 수 없는 몸을 짚는 법이다.`,
      ng:`막대를 대는 순간 관이 쩅 울렸다. 급하게 댄 탓이다.<br><br>울림이 관을 타고 사방으로 퍼졌다. 이 건물 관은 다 이어져 있다.<br>먼 데서 긁는 소리가 일제히 방향을 틀었다. 이쪽으로. 읽기는커녕 쓰여 버렸다. 여기 있다고.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 관 이음새의 먼지로 다니는 길을 읽는다.', k:'gaze', dc:24,
      ok:`관 밑에 서지 않고 먼지를 읽었다. 이음새마다 쌓인 먼지가 다르다. 손대지 않은 관은 먼지가 고르고, 다니는 관은 이음새 먼지가 떨려 내려 바닥에 줄을 긋는다.<br><br>바닥의 먼지 줄만 따라 보면 저것들의 길이 천장에 그려진다.<br>그 길을 피해 방 셋을 건넜다. 머리 위로 지나가는 소리를 두 번 들었다. 둘 다 먼지 줄 위였다.`,
      ng:`먼지 줄을 읽으며 걷다가 고개를 너무 오래 들고 있었다.<br><br>발밑의 깨진 유리를 못 봤다. 와작.<br>천장 관 안의 긁는 소리가 머리 바로 위에서 멎었다. 이음새 틈으로 젖은 코가 내려와 벌름거렸다. 다들 조각상이 됐다. 코가 돌아갈 때까지.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-18 } },
    { l:'③ 관 뚜껑을 열고 직접 귀를 넣는다.', k:'luck', dc:26,
      doom:{ title:'쇠관 속', what:'관 속의 것에게 물려 끌려 들어갑니다', dc:20, sec:35,
        text:`막대도 먼지도 성에 안 찼다. 이음새 뚜껑을 살살 열고 귀를 관 안에 넣었다.<br><br>고요하다. 바람 소리뿐. 더 깊이 머리를 넣었다.<br>고요한 이유가 있었다. 숨을 참는 것은 소리가 없다. 관 안쪽 어둠에서 숨 참던 것이 입을 벌렸다.<br><br>머리부터 물려 관 속으로 끌려 올라간다. 몸이 이음새에 걸리고, 걸린 몸이 꺾여 넘어간다. 진맥하러 넣은 머리였다.`,
        dieText:`열린 이음새 뚜껑이 복도에 떨어져 있다.<br><br>관 속에서 먼 데로 끌려가는 소리가 한참 났다. 긁힘, 긁힘, 긁힘.<br>소리는 이 건물 관이 다 이어져 있다는 것만 한 번 더 가르쳐 줬다.` },
      ok:`뚜껑에 손을 대는데 손끝에 떨림이 왔다. 고요한 관인데 관 살이 미지근하다.<br><br>쇠는 차야 한다. 미지근한 쇠는 안에서 데우는 것이 있다는 뜻이다.<br>뚜껑에서 손을 떼고 그 복도를 통째로 버렸다. 돌아가는 길이 한 식경 멀었다. 머리가 붙어 있는 한 식경이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'냉동고 앞 — 언 손가락',
  x:`냉동고를 뒤지고 나온 사람 손가락이 하얗다. 장갑 없이 쇠를 쥔 탓이다.<br><br>
    감각이 없다고 한다. 하얀 밀랍 같은 손가락 네 개.<br>
    급하게 데우면 살이 운다. 터지고 물집 잡히고.<br><br>
    언 것은 어는 데 걸린 시간만큼 들여 녹인다. 그게 법이다. 여기는 그 시간이 아까운 땅이지만.`,
  o:[
    { l:'① 내공을 미지근하게 낮춰 속부터 녹인다.', k:'heal', dc:25, cost:{ qi:29 },
      ok:`손가락을 이쪽 겨드랑이에 끼우고, 내공을 미지근하게 낮춰 뼈 쪽부터 흘렸다. 겉은 천천히, 속은 먼저.<br><br>반 시진에 걸쳐 색이 돌아왔다. 밀랍이 분홍이 되고, 분홍이 아픔이 됐다.<br>아프다고 울상인 손가락 넷. 아픈 손가락은 산 손가락이다. 넷 다 제 몫을 할 것이다.`,
      ng:`내공 온도를 반 식경 유지하다 집중이 흐트러졌다. 한순간 뜨거워졌다.<br><br>손가락 둘에 물집이 잡혔다.<br>녹이기는 녹였는데 물집 두 개 값을 치렀다. 며칠은 그 손으로 아무것도 못 쥔다. 급한 불과 미지근한 불 사이에서 손이 흔들린 값이다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 제 배에 그 손을 품고 걷게 한다.', k:'bond', dc:23,
      ok:`그 사람 손을 제 옷 속, 배에 바로 대게 했다. 사람 배가 제일 믿을 만한 화로다. 온도가 안 변하니까.<br><br>걸으면서 녹였다. 서 있는 시간을 안 쓰고.<br>한 굽이를 가니 손가락이 아리다고 했다. 좋은 신호다. 화로 노릇한 배가 차가워서 혼났지만.`,
      ng:`걷다가 그 사람이 휘청하며 손을 뺐다. 빼서 벽을 짚었다. 언 손으로, 찬 쇠벽을.<br><br>도로 얼었다. 처음보다 깊게.<br>결국 멈춰 앉아 제대로 녹였다. 걸으며 하려던 치료가 두 배로 들었다. 지름길이 에움길 되는 건 한순간이다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-26, spirit:-15 } }
  ] },

{ at:'S2', t:'양치 숲 — 뿌리에 삔 발목',
  x:`양치 뿌리가 그물처럼 얽힌 땅이다. 하나가 발목을 접질렸다.<br><br>
    붓는 속도가 빠르다. 접질린 게 아니라 인대가 상했을 수도 있다.<br>
    이 숲에서 못 걷는 발 하나는 다섯의 속도다.<br><br>
    가려내고, 처치하고, 걷게 한다. 셋 다 지금 여기서.`,
  o:[
    { l:'① 눌러 보고 돌려 보고 금 간 데를 가려낸다.', k:'heal', dc:24, wake:1,
      ok:`복사뼈 아래위를 차례로 눌렀다. 아픈 자리가 인대 쪽이지 뼈 쪽이 아니다. 돌려 보니 걸리는 데 없이 아프기만 하다. 삔 것이다. 금은 없다.<br><br>그럼 감고 걷는다. 천을 여덟 자로 감아 발목을 세웠다.<br>지팡이 하나 깎아 주니 제 발로 걸었다. 가려낸 덕에 업을 사람 하나가 걷는 사람 하나가 됐다.<br><br>뼈냐 인대냐. 그 갈림을 손끝으로 묻는 순서가 몸에 뱄다. 묻지 않고 감는 손은 반쪽 손이다.`,
      ng:`눌러 가리는데 아픈 사람이 자꾸 몸을 빼서 답이 흐렸다.<br><br>삔 것으로 치고 감았다. 반나절 뒤 부기가 천을 넘었다. 실금이 있던 것이다.<br>다시 풀고 부목을 댔다. 처음 답이 틀리면 두 번째 처치는 첫 처치를 뜯는 데서 시작한다. 그만큼 늦는다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 침으로 부기 길을 열어 내린다.', k:'fix', dc:25,
      ok:`복사뼈 둘레 세 혈에 침을 얕게 세웠다. 고인 것이 내려갈 물꼬다.<br><br>반 식경 만에 팽팽하던 살이 수그러들었다.<br>부기는 가두면 아픔이고 흘리면 지나감이다. 침 세 대가 물꼬 세 개. 그 발이 저녁에는 반쯤 디뎌졌다.`,
      ng:`침 자리 하나가 뿌리에 긁힌 생채기와 겹쳤다.<br><br>물꼬가 아니라 덧날 길을 연 셈이 됐다. 붉은 기가 침 자리를 따라 돌았다.<br>침을 거두고 쓴 즙으로 씻었다. 혈 자리는 맞는데 살 상태를 안 봤다. 자리와 살, 둘 다 보는 게 침이다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S2', t:'울타리 — 느리게 하는 이빨',
  x:`울타리를 넘다 한 사람이 장딴지를 물렸다. 무리 사냥꾼들의 그 물기다.<br><br>
    피는 얼마 안 나는데 다리가 말을 안 듣는다고 한다. 물린 자리 둘레가 차갑다.<br>
    죽이는 독이 아니라 느리게 하는 독. 느려진 것은 무리가 거둔다.<br><br>
    맥을 짚으니 다리 쪽 맥만 늘어져 있다. 독이 맥을 타고 있다.`,
  o:[
    { l:'① 다리 혈 셋을 짚어 독의 길을 끊는다.', k:'heal', dc:26, cost:{ qi:37 }, wake:1,
      ok:`물린 자리 위쪽, 독이 오르는 길목 혈 셋을 차례로 내공으로 틀어막았다. 둑 셋을 쌓은 것이다.<br><br>독이 둑 안에 갇혔다. 갇힌 독은 장딴지 한 뼘만 재웠다. 무릎 위는 산 다리다.<br>절뚝이되 제 발로 걸었다. 무리의 셈은 틀어졌다. 느려진 것이 무리를 안 떠나고, 떠나지 않는 것은 못 거둔다.<br><br>독을 못 빼면 가둔다. 둑 쌓는 혈 세 자리. 이 울타리 밑에서 평생 쓸 수를 받았다.`,
      ng:`둑 하나가 샜다. 독이 무릎을 넘었다.<br><br>허벅지까지 느려졌다. 한 다리가 통째로 남의 다리다.<br>업고 뛰는 수밖에 없었다. 울타리 안쪽까지. 등 뒤에서 그것들이 따라오다 멈추는 기척이 났다. 다 넘어와서야.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-30, spirit:-18 } },
    { l:'② 물린 자리를 입으로 빨아낸다.', k:'steady', dc:25,
      ok:`입에 상처가 없는 걸 확인하고 물린 자리를 빨았다. 뱉고, 빨고, 뱉고. 입이 얼얼해질 때까지.<br><br>차갑던 둘레에 온기가 돌았다. 반은 뺀 것이다.<br>남은 반은 몸이 이긴다. 이 독은 양의 싸움이다. 입술이 반나절 저렸다. 싼 값이다.`,
      ng:`빨다가 혀끝이 저려 왔다. 입 안 어딘가 짓무른 데가 있던 모양이다.<br><br>뱉어도 저림이 남는다. 둘이 나란히 느려졌다.<br>남들 부축을 받으며 걸었다. 의원이 환자가 되는 건 순식간이다. 제 입부터 진맥할 것을.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'③ 뒤에 남아 혼자 찬찬히 처치한다.', k:'luck', dc:26,
      doom:{ title:'거두는 무리', what:'둘째 이빨에 물려 수풀로 끌려갑니다', dc:20, sec:36,
        text:`제대로 보려면 앉아야 한다. 먼저들 가라 하고 남았다.<br><br>혈을 짚는데 수풀이 양옆에서 숨을 죽였다. 물린 것 하나, 돌보는 것 하나. 느린 둘.<br>저것들의 첫 이빨은 느리게 하는 이빨이고 둘째 이빨은 거두는 이빨이다. 둘째가 왔다.<br><br>어깨에 이빨이 박힌다. 수풀로 끌리며 생각했다. 치료에는 자리가 먼저라고 그렇게 배우고도.`,
        dieText:`울타리 밑에 침통이 떨어져 있었다.<br><br>침이 세 대 꽂힌 채로 뒹군다. 셋째 둑까지는 쌓은 것이다.<br>수풀 속의 소리로는, 넷째 둑이 필요했다.` },
      ok:`앉으려다 수풀의 결이 눈에 걸렸다. 바람과 어긋나게 눕는 풀.<br><br>혼자 남는 그림이 저것들의 주문서라는 걸 그 결이 말해 줬다.<br>부축해 울타리 안쪽까지 가서 앉았다. 둑 셋을 거기서 쌓았다. 늦게 쌓아도 안에서 쌓는 둑이 밖의 급한 둑보다 낫다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'물가 — 물 먹은 가슴',
  x:`얕은 물에서 건진 사람이 숨은 쉬는데 숨소리가 젖어 있다. 그르렁그르렁.<br><br>
    물이 숨길에 들어앉은 것이다. 지금은 쉬어도 밤에 숨이 막히는 수가 있다. 의서가 마른 익사라고 적는 그것이다.<br>
    겉은 멀쩡해서 본인은 괜찮다고 웃는다.<br><br>
    그 웃음이 제일 위험하다.`,
  o:[
    { l:'① 엎드리게 하고 등의 혈을 두드려 물을 몬다.', k:'heal', dc:25, cost:{ qi:30 }, wake:1,
      ok:`무릎에 엎드리게 하고 등의 혈 자리를 손바닥 뿌리로 두드렸다. 아래에서 위로, 물길을 몰 듯.<br><br>내공을 손바닥에 실어 떨림을 깊이 넣었다. 기침이 터지고, 기침 끝에 물이 올라왔다. 한 모금, 또 한 모금.<br>그르렁이 걷히고 숨소리가 말랐다. 밤에 그 사람은 코를 골며 잤다. 고운 소리였다.<br><br>겉이 멀쩡한 병을 겉보다 믿는 법. 숨소리 한 결이 웃는 낯보다 정직하다.`,
      ng:`두드려도 물이 반만 나왔다. 깊이 앉은 반이 안 나온다.<br><br>밤새 그 사람 숨소리를 지켰다. 그르렁이 심해질 때마다 일으켜 두드리고.<br>새벽에야 마지막 기침이 물을 뱉었다. 긴 밤이었다. 반 남은 물 한 모금이 밤 하나를 통째로 먹었다.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 괜찮다는 사람을 한나절 눕혀 지킨다.', k:'steady', dc:24,
      ok:`괜찮다는 말은 접수만 하고 처방은 따로 냈다. 한나절 안정. 그 사람 짐을 나눠 지고 걸음도 늦췄다.<br><br>세 시진째에 그 사람이 갑자기 기침을 쏟았다. 물과 함께.<br>눕혀 둔 덕에 앉은 채로 받았다. 걷는 중이었으면 들판 한가운데서 쓰러졌을 것이다. 괜찮다는 말은 병이 아니라 성격이다. 처방은 병에 낸다.`,
      ng:`괜찮다는 사람을 말로 못 이겼다. 반나절만 쉬고 걷기로 물러섰다.<br><br>걷는 중에 기침이 터졌다. 들판 한가운데서. 주저앉아 물을 뱉는 사람과 둘러선 넷.<br>제일 나쁜 자리에서 제일 급한 간호를 했다. 물러선 반나절이 이 꼴로 돌아왔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S2', t:'들판 — 발소리 박자',
  x:`큰 것이 들판 저쪽을 오간다. 쿵. 쿵. 땅이 맥처럼 뛴다.<br><br>
    맥에는 결이 있다. 이 발소리에도 결이 있다. 아홉 걸음 가고, 셋 쉬고, 돌아선다.<br>
    오가는 짐승은 제 길을 돈다. 순찰이다.<br><br>
    맥을 읽듯 박자를 읽으면 빈 때가 보인다.`,
  o:[
    { l:'① 박자를 재서 빈 때에 맞춰 건넌다.', k:'sense', dc:25, wake:1,
      ok:`엎드려 발소리를 쟀다. 아홉 걸음, 셋 쉼, 돌아섬. 돌아서는 셋 숨이 등을 보이는 때다.<br><br>그 셋 숨마다 한 사람씩 보냈다. 다섯 번의 셋 숨.<br>다 건넜을 때 큰 것은 여전히 제 길을 돌고 있었다. 제 박자에 실려 간 다섯을 모르고.<br><br>맥 짚던 셈이 들판에서도 통했다. 몸이든 땅이든 박자 있는 것은 다 읽힌다. 읽히면 건너진다.`,
      ng:`넷째 사람 차례에 박자가 바뀌었다. 아홉이 일곱이 됐다.<br><br>짐승 박자는 사람 맥과 달라서 제멋대로 변한다.<br>넷째가 들판 한가운데서 엎드렸다. 큰 것이 지나가기를 풀 속에서 기다렸다. 콧김이 풀을 가르고 지나갔다. 두 번.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 다섯을 묶어 한 숨에 건넌다.', k:'fix', dc:25, cost:{ qi:28 },
      ok:`나눠 보내면 다섯 번의 위험이다. 허리끈을 서로 묶어 한 덩이로 만들고, 내공으로 다섯 걸음의 박자를 맞췄다.<br><br>돌아서는 셋 숨에 다섯이 한 몸으로 내달렸다.<br>발소리 다섯이 박자가 같으면 하나로 들린다. 큰 것 귀에는 중간치 한 마리가 지나간 것이다. 중간치는 순찰감이 아니다.`,
      ng:`묶고 뛰는데 가운데 사람이 반 박자 늦었다. 끈이 당겨지고 다섯 박자가 다 흐트러졌다.<br><br>흐트러진 발소리는 여럿으로 들린다.<br>큰 것이 돌아섰다. 다행히 다 건넌 뒤였다. 들판 끝에서 그것이 한참 땅에 코를 대고 있는 걸 봤다. 다섯 냄새를 세고 있었을 것이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S2', t:'둥지 가 — 바닥난 사람',
  x:`한 사람이 주저앉아 못 일어난다. 상처는 없다. 바닥난 것이다.<br><br>
    잠도 밥도 아닌 것이 비었다. 의서는 이걸 기가 말랐다고 적는다.<br>
    여기는 버려진 둥지 가. 오래 머물 데가 아니다.<br><br>
    마른 기는 꾸어 줄 수 있다. 의원 몸에 든 것으로.`,
  o:[
    { l:'① 단전을 맞대고 내공을 꾸어 준다.', k:'heal', dc:25, cost:{ qi:40 }, wake:1,
      ok:`등을 맞대고 앉아 단전 높이를 맞췄다. 이쪽 내공을 가늘게, 그 사람 빈 데로 흘렸다.<br><br>붓는 게 아니라 마중물이다. 한 바가지 부어 그 사람 샘이 도로 돌게.<br>반 시진 뒤 그 사람이 제 숨으로 깊게 쉬었다. 샘이 돈 것이다. 일어나서 걷고, 저녁에는 제 몫의 짐도 졌다.<br><br>기를 꾸어 주는 데도 셈이 있다. 샘을 돌릴 만큼만. 그 금을 넘으면 둘 다 마른다. 오늘 그 금을 손으로 쟀다.`,
      ng:`마중물이 마중을 못 했다. 그 사람 샘이 생각보다 깊이 말라 있었다.<br><br>부은 만큼 고이기만 하고 돌지를 않는다.<br>내공 반을 꾸어 주고도 그 사람은 반나절을 업혀 갔다. 꾸어 준 쪽도 빈 몸으로 걸었다. 빈 둘이 낀 행렬은 느렸다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 혀 밑에 꿀을 녹이고 발바닥 혈을 데운다.', k:'fix', dc:24,
      ok:`꿀 한 숟갈을 혀 밑에 물렸다. 삼키지 말고 녹이라고. 그사이 발바닥 가운데 혈을 덥힌 돌로 문질렀다.<br><br>단것이 위에서, 온기가 아래에서. 빈 몸의 양 끝에 불을 댕기는 법이다.<br>한 식경 만에 그 사람 눈에 힘이 돌아왔다. 내공 한 톨 없이 올린 불이다.`,
      ng:`돌이 식은 걸 모르고 문질렀다. 찬 돌은 거꾸로 기를 누른다.<br><br>그 사람이 더 처졌다.<br>돌을 다시 데워 오는 동안 꿀만 두 숟갈이 들었다. 연장 온도 하나 안 본 손. 의원 손이 아니라 그냥 바쁜 손이었다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S2', t:'승강기 앞 — 굳은 다리들',
  x:`마지막 들판 앞. 다들 다리가 돌이 됐다. 겁과 피로가 같이 굳힌 다리다.<br><br>
    굳은 다리로 뛰면 반드시 누가 넘어진다.<br>
    침통에 침이 아홉 대 남았다. 다리 푸는 혈은 한 다리에 세 자리.<br><br>
    아홉 대, 다섯 사람, 열 다리. 셈이 안 맞는다. 맞춰야 한다.`,
  o:[
    { l:'① 사람마다 제일 굳은 다리 한쪽만 푼다.', k:'heal', dc:25, wake:1,
      ok:`열 다리를 다 만져 보고 사람마다 더 굳은 쪽을 골랐다. 그 다리에만 침 둘씩. 남은 침은 아홉에서 하나 남는다. 제일 심한 사람에게 셋째 침.<br><br>한쪽이 풀리면 반대쪽은 따라 걷는다. 다리는 짝으로 움직이니까.<br>다섯이 다 제 속도로 뛰었다. 아홉 대의 셈이 맞아떨어졌다.<br><br>모자란 연장은 몸의 이치로 채운다. 짝 지어 움직이는 것은 반만 고쳐도 다 고쳐진다. 그 이치 하나가 침 아홉을 열여덟로 만들었다.`,
      ng:`고른다고 골랐는데 한 사람 것을 반대로 짚었다. 덜 굳은 쪽에 침이 갔다.<br><br>뛰는 중에 그 사람의 안 푼 다리가 접혔다.<br>옆 사람이 낚아채 부축했다. 승강기까지 세 발 뛰기로 왔다. 셈은 맞았는데 눈이 틀렸다. 침은 눈이 반이다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 침 대신 다섯 무릎에 내공을 한 바퀴 돌린다.', k:'fix', dc:26, cost:{ qi:39 },
      ok:`침을 아꼈다. 한 사람씩 무릎 뒤에 손을 대고 내공을 한 바퀴씩 돌렸다. 굳은 것을 데워 푸는 바퀴.<br><br>다섯 번째에 이쪽 단전이 바닥을 긁었다.<br>그래도 열 다리가 다 풀렸다. 들판을 건너는 다섯 걸음이 고르게 울렸다. 빈 단전은 승강기 안에서 채우면 된다. 다리는 지금 필요했다.`,
      ng:`셋째 사람에서 내공이 끊겼다. 남은 둘은 맨다리다.<br><br>맨다리 둘을 가운데 세우고 뛰었다.<br>한 명이 들판 끝에서 쥐가 났다. 둘이 끌고 마지막 스무 걸음을 갔다. 반만 푼 처방은 반만 뛴다. 몸은 셈을 안 봐준다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, spirit:-16 } },
    { l:'③ 풀 것 없이 바로 출발 신호를 낸다.', k:'luck', dc:26,
      doom:{ title:'굳은 다리', what:'넘어진 사람을 붙들다 함께 끌려갑니다', dc:20, sec:35,
        text:`해가 기운다. 주무르고 있을 때가 아니다. 바로 뛰자고 손을 내저었다.<br><br>들판 삼분의 일에서 예감이 맞았다. 제일 굳었던 다리가 접혔다. 그 사람이 구르고, 달려가 일으키는 사이 수풀이 좁혀 왔다.<br>일으킨 사람은 앞으로 밀어 보냈다. 이쪽 다리도 굳은 다리였다는 게 다음 문제였다.<br><br>반 걸음이 늦었다. 발목에 이빨이 걸렸다. 굳은 다리는 의원 것도 예외가 아니었다. 그걸 환자들 다리만 보다 잊었다.`,
        dieText:`들판에 침통이 떨어져 있었다. 아홉 대가 고스란히 든 채.<br><br>쓸 시간은 있었다. 쓰자는 판단이 없었을 뿐.<br>승강기에 탄 넷의 다리는 그 뒤로 의원 없이 저희끼리 굳고 풀렸다.` },
      ok:`신호를 내리려다 손이 멎었다. 눈앞의 다리 열 개가 다 떨고 있다. 뛰기도 전에.<br><br>떠는 다리는 뛰는 다리가 아니다. 반 식경을 벌어 제일 심한 셋만 급히 풀었다.<br>해가 반 뼘 더 기울었지만 다섯이 다 섰다. 늦은 출발이 못 가는 출발보다 빠르다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'승강기 — 다섯 맥',
  x:`쇠 바구니가 올라간다. 다들 바닥에 늘어졌다.<br><br>
    버릇대로 손목부터 잡았다. 한 사람씩, 다섯 맥.<br>
    뛰고 난 맥은 거칠다. 거친 것과 상한 것을 가리는 게 지금 할 일이다.<br><br>
    올라가는 동안이 의원의 마지막 회진이다.`,
  o:[
    { l:'① 다섯 맥을 차례로 짚어 회진을 돈다.', k:'heal', dc:24, wake:1,
      ok:`첫째 맥, 거칠지만 고르다. 둘째도. 셋째 맥이 걸렸다. 거칠고 어지럽다. 뛰면서 어디를 삔 게 아니라 속으로 놀란 맥이다.<br><br>그 사람 손을 잡은 채 숨을 같이 쉬었다. 넷 들이쉬고 여섯 내쉬고.<br>꼭대기에 닿기 전에 다섯 맥이 다 고른 거칢으로 내려왔다. 거친 건 자고 나면 낫는다.<br><br>맥을 짚는 건 병을 찾는 일이면서 사람을 세는 일이다. 다섯. 들어간 수와 나온 수가 같다. 의원의 장부는 그 한 줄이면 된다.`,
      ng:`넷째 맥에서 이쪽 손이 떨렸다. 제 맥이 먼저 거칠었던 것이다.<br><br>남의 맥은 제 손이 고요해야 읽힌다.<br>손을 바꿔 왼손으로 짚었다. 왼손은 서툴다. 서툰 대로 다 돌긴 돌았다. 회진 끝에 제 손목도 짚었다. 환자가 여섯이었던 셈이다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 남은 내공을 다섯 등에 한 줌씩 나눈다.', k:'bond', dc:25, cost:{ qi:25 },
      ok:`바닥을 긁어 남은 내공을 다섯 몫으로 갈랐다. 등마다 손바닥을 대고 한 줌씩.<br><br>약도 침도 아닌, 그냥 온기다. 그래도 등이 펴진다.<br>다 나누고 나니 이쪽은 빈 몸이다. 빈 몸으로 올라가는 쇠 소리를 들었다. 가볍다. 내공이 비어서만은 아니었다.`,
      ng:`나누다 바구니가 출렁해 손이 미끄러졌다. 한 줌이 허공에 샜다.<br><br>마지막 사람 몫이 모자랐다.<br>그 사람이 웃으며 괜찮다고 했다. 그 말이 오래 남았다. 의원 장부에는 빚으로 적혔다. 갚을 날이 있을 것이다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ mind:-16, spirit:-18 } }
  ] }

]);

// ------------------------------------------
// 수도사 (monk) · 무력
// ------------------------------------------
kJob('monk', 'S', [

{ at:'S', t:'쉬는 자리 — 소리 없는 기도',
  x:`하루가 끝나면 기도를 올린다. 거른 적이 없다.<br><br>
    여기서는 입을 열 수가 없다. 낮은 중얼거림도 여기 어둠에서는 종소리다.<br>
    입으로 올리던 것을 다른 데로 올려야 한다.<br><br>
    기도는 소리가 아니라고 배웠다. 그 말을 시험할 밤이다.`,
  o:[
    { l:'① 호흡에 기도를 실어 올린다.', k:'heal', dc:23, wake:1,
      ok:`눈을 감고 들숨에 한 구절, 날숨에 한 구절을 실었다. 입술도 안 움직이고.<br><br>숨이 기도가 되자 기도가 숨처럼 길어졌다. 옆에 앉은 일행의 숨도 어느새 그 박자를 따라왔다.<br>소리 없이 다섯이 같은 기도를 쉬었다. 어둠이 끼어들 틈이 없는 숨이었다.<br><br>입을 잃고 숨을 얻었다. 기도의 그릇이 하나 늘어난 것이다. 이 어둠이 준 것 중 처음으로 고마운 것이다.`,
      ng:`숨에 싣는다는 게 뜻대로 안 됐다. 구절이 자꾸 입술로 샜다.<br><br>옆 사람이 팔을 꽉 쥐었다. 입술 소리가 났다는 뜻이다.<br>기도를 접고 귀만 세웠다. 다행히 어둠은 조용했다. 그 밤 기도는 미안함으로 끝났다.`,
      win:{ exp:20, dream:3, spirit:8 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 손가락으로 구슬 대신 흙을 센다.', k:'fix', dc:23,
      ok:`기도 구슬은 소리가 난다. 대신 바닥의 흙을 한 줌 쥐고 손가락 사이로 한 알씩 흘렸다.<br><br>알 하나에 한 구절. 흙이 구슬이 됐다.<br>한 줌이 다 흐르자 기도도 끝났다. 빈 손바닥이 개운했다. 도구는 바뀌어도 센 것은 같다.`,
      ng:`세다가 흙 속 자갈이 돌에 떨어졌다. 톡.<br><br>작은 소리인데 크게 들렸다. 다들 깼다.<br>그 밤은 기도 대신 사과를 셌다. 미안하다는 눈짓 네 번. 기도보다 어려웠다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-16, spirit:-15 } }
  ] },

{ at:'S', t:'어둠 — 무서움의 무게',
  x:`어둠이 깊어지자 일행의 어깨가 하나씩 내려앉는다.<br><br>
    무서움은 무게다. 지고 걷다 보면 다리가 꺾인다.<br>
    짐을 나눠 지는 법은 수도원에서 배웠다. 무서움도 짐이면 나눠 질 수 있다.<br><br>
    문제는 어떻게 받아 드는가다.`,
  o:[
    { l:'① 한 사람씩 손을 잡고 제 몫처럼 들어 준다.', k:'heal', dc:24, wake:1,
      ok:`제일 어깨가 낮은 사람 손을 잡았다. 말은 안 했다. 잡은 손에 힘만 줬다. 무서우면 이 손을 쥐라고.<br><br>그 사람이 손을 쥐었다 놓았다 하며 걸었다. 쥘 때마다 이쪽 손바닥이 아팠다. 아픈 만큼 그쪽이 가벼워졌다.<br>한 굽이 가서 그 사람이 옆 사람 손을 잡아 줬다. 같은 방식으로.<br><br>무서움은 없애는 게 아니라 들어 주는 것이다. 받아 든 무게만큼 손바닥에 굳은살이 앉는다. 그 굳은살이 이 길의 수행이다.`,
      ng:`손을 내밀자 그 사람이 뿌리쳤다. 어린애 취급 말라고.<br><br>무서움은 들켰다고 느끼면 더 무거워진다.<br>반 굽이를 떨어져 걸었다. 그러다 그 사람이 돌부리에 걸렸을 때 말없이 팔만 받쳐 줬다. 그 손은 안 뿌리쳤다. 거기서부터 다시.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 제일 무서운 자리를 말없이 맡는다.', k:'steady', dc:24,
      ok:`맨 뒤. 어둠을 등에 지는 자리. 아무도 서고 싶지 않은 자리에 말없이 섰다.<br><br>맨 뒤가 든든하면 앞의 넷이 돌아보지 않는다. 돌아보지 않는 걸음은 빠르다.<br>등 뒤의 어둠을 밤새 혼자 상대했다. 어둠은 등을 보이는 자를 좋아한다. 보여 주되 내주지 않았다.`,
      ng:`맨 뒤에 섰는데 자꾸 뒤를 돌아보게 됐다. 이쪽도 사람이다.<br><br>돌아보는 기척이 앞까지 전해졌다. 넷이 다 같이 뒤를 신경 쓰기 시작했다.<br>걸음이 반으로 줄었다. 맨 뒤는 등이 아니라 낯빛으로 서는 자리라는 걸 배웠다. 비싸게.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'③ 무서움을 소리 내어 꾸짖는다.', k:'break', dc:25,
      ok:`걸음을 멈추고 어둠을 향해 한 마디를 뱉었다. 낮고 단단하게. 물러가라.<br><br>어둠이 물러갈 리 없다. 물러간 것은 일행 속의 무서움이다. 누가 저 대신 소리 내 줬으니까.<br>어깨 넷이 올라왔다. 한 마디 값으로는 컸다. 어둠 저쪽이 조용한 걸 확인하는 데 반 식경이 들긴 했지만.`,
      ng:`한 마디가 생각보다 멀리 울렸다.<br><br>어둠 저쪽에서 돌 구르는 소리가 답했다.<br>꾸짖음이 초대장이 됐다. 다 같이 반 굽이를 뛰었다. 무서움은 쫓았는데 무서운 것이 왔다. 남는 장사인지는 아직 모르겠다.`,
      win:{ exp:18, dream:3, spirit:6 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S', t:'쉬는 자리 — 보내는 일',
  x:`앞 팀이 남긴 자리를 지난다. 다 챙겨 가지 못한 것이 남아 있다. 사람이.<br><br>
    오래됐다. 누군지 알 길도 없다.<br>
    다들 눈을 돌리고 지나치려 한다. 봐 버리면 밤에 따라오니까.<br><br>
    보내는 일을 배운 사람은 안다. 보내지 않은 것이야말로 따라온다.`,
  o:[
    { l:'① 돌을 쌓고 짧게 보내는 예를 올린다.', k:'heal', dc:24, wake:1,
      ok:`돌 일곱을 소리 없이 쌓았다. 이름 모르는 이를 보내는 예는 짧다. 잘 가라. 여기 일은 여기 두고.<br><br>일행이 하나둘 곁에 와 고개를 숙였다. 눈을 돌리던 이들이.<br>그날 밤 아무도 그 자리 꿈을 꾸지 않았다. 보낸 것은 따라오지 않는다.<br><br>보내는 예는 죽은 이를 위한 것이라고 배웠는데, 반은 산 사람을 위한 것이었다. 눈 돌린 마음은 밤에 앓는다. 숙인 마음은 잔다.`,
      ng:`돌을 쌓는데 하나가 무너지며 굴렀다. 소리가 골을 탔다.<br><br>예는 서둘러 마쳤다.<br>그래도 올릴 것은 올렸다. 그날 밤 어둠 속에서 뭔가 그 돌무더기를 뒤지는 소리가 났다. 보낸 이와는 상관없는 것이. 예는 예대로, 여기는 여기대로다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 남은 짐에서 쓸 것만 거두고 예는 마음으로 한다.', k:'sense', dc:24,
      ok:`그이 봇짐을 열었다. 산 사람이 쓸 것은 산 사람이 쓰는 게 보내는 예에 어긋나지 않는다. 그렇게 배웠다.<br><br>마른 식량 한 꾸러미와 성한 천. 거두며 속으로 한 구절을 올렸다. 잘 쓰겠다고.<br>그이 신표는 돌 밑에 묻었다. 언젠가 누가 찾으러 올지 모르니. 그것까지가 거두는 예다.`,
      ng:`봇짐을 여는데 손이 멈칫했다. 봇짐이 안에서부터 묶여 있었다.<br><br>마지막에 제 손으로 여민 매듭이다. 가져가지 말라는 뜻인지, 가져가 달라는 뜻인지.<br>알 수 없는 매듭은 푸는 게 아니다. 그대로 두고 돌만 쌓았다. 빈손이 무거운 날이 있다.`,
      win:{ exp:20, dream:3, item:'말린 고기' }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S', t:'통로 — 업는 어깨',
  x:`못 걷는 사람이 생겼다. 번갈아 업자는데, 업어 본 사람은 안다.<br><br>
    업는 건 힘이 아니라 요령이고, 요령보다 버릇이다. 수도원에서 아픈 이를 수레 없는 산길로 나르던 버릇.<br>
    여기 길은 그 산길보다 어둡고 좁다.<br><br>
    버릇 있는 등이 맡는 게 맞다.`,
  o:[
    { l:'① 끈으로 묶어 업고 두 손을 비워 둔다.', k:'fix', dc:24, cost:{ might:28 }, wake:1,
      ok:`천을 길게 이어 업은 사람을 등에 묶었다. 산길 버릇이다. 묶으면 두 손이 빈다.<br><br>빈 두 손으로 벽을 짚고 몸을 가누며 좁은 길을 건넜다. 업힌 사람은 두 손으로 이쪽 어깨만 잡으면 된다.<br>세 굽이를 쉬지 않고 갔다. 묶인 둘은 한 몸이다. 한 몸은 안 떨어진다.<br><br>업는 끈의 매듭이 손에 완전히 붙었다. 어둠 속에서도 세 번 감아 두 번 꿰는 그 매듭. 등이 침상이 되는 법이다.`,
      ng:`매듭 하나가 걷는 중에 늘어졌다. 업힌 사람이 한쪽으로 기울었다.<br><br>기운 무게에 이쪽 발이 꼬였다. 벽에 어깨를 갈며 겨우 버텼다.<br>다시 묶는 데 한참 걸렸다. 어둠 속 매듭은 손가락 끝이 눈이다. 그 눈이 아직 어두웠다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 번갈아 업자는 일행에게 요령부터 가르친다.', k:'bond', dc:23,
      ok:`혼자 다 업으면 혼자 먼저 쓰러진다. 대신 업는 법을 가르쳤다. 허리로 받지 말고 다리로 설 것. 팔로 당기지 말고 끈으로 묶을 것.<br><br>넷이 돌아가며 업었다. 아무도 허리가 나가지 않았다.<br>나르는 짐은 나눠야 멀리 간다. 수도원 짐꾼의 첫 계율이다. 여기서도 통했다.`,
      ng:`가르치는데 하나가 제 방식을 고집했다. 팔힘으로 둘러업는 방식.<br><br>반 굽이 만에 그 사람 허리가 삐끗했다.<br>업을 사람이 둘이 됐다. 가르침은 귀가 아니라 허리로 배우는 사람이 꼭 있다. 그 허리까지가 이쪽 짐이 됐다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ hp:-26, spirit:-15 } }
  ] },

{ at:'S', t:'틈새 — 버티는 등',
  x:`무너진 바위 틈이 유일한 길이다. 틈을 받친 바위 하나가 흔들린다.<br><br>
    지나는 동안 저 바위가 내려앉으면 가운데서 깔린다.<br>
    누가 받치고 있어야 한다. 다 지나갈 때까지.<br><br>
    받치는 등은 수도원에서 종루 대들보를 갈 때 서 본 적이 있다. 그때는 밑에 사람이 없었다.`,
  o:[
    { l:'① 등으로 받치고 넷을 먼저 보낸다.', k:'steady', dc:25, cost:{ might:35 }, wake:1,
      ok:`틈에 들어가 바위 밑에 등을 댔다. 무릎을 반만 굽히고 숨을 바닥에 가라앉혔다. 받치는 건 팔이 아니라 자세다.<br><br>하나, 둘, 셋, 넷. 등 위로 바위가 조금씩 내려앉는 걸 뼈로 느끼며 셌다.<br>넷이 다 건너고, 몸을 빼며 굴렀다. 등 뒤에서 틈이 쿵 내려앉았다.<br><br>버티는 시간은 힘이 아니라 셈이라는 걸 배웠다. 넷을 세는 동안만 버티면 된다. 끝이 있는 무게는 들 수 있다.`,
      ng:`셋째가 건널 때 발이 미끄러져 시간을 끌었다.<br><br>그 몇 숨에 바위가 한 뼘 내려왔다. 무릎이 떨리기 시작했다.<br>넷째는 기다시피 빠져나갔고, 이쪽은 구르다 어깨를 바위 모서리에 찍었다. 틈은 무너졌다. 어깨 하나 값으로 넷이 건넌 셈이니, 셈은 맞다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 바위를 막대와 돌로 괴고 다 같이 건넌다.', k:'fix', dc:24,
      ok:`등 대신 괼 것을 찾았다. 굵은 쇠막대 하나, 모난 돌 둘. 바위 밑에 박아 넣고 흔들어 봤다. 선다.<br><br>다섯이 차례로 빠르게 건넜다.<br>마지막 사람이 건너자마자 막대가 휘기 시작했다. 사람 등은 마지막 수단이다. 먼저 쓸 것이 있으면 그걸 쓴다. 그것도 배움이다.`,
      ng:`괸 돌 하나가 무게에 바스러졌다. 셋째가 건너는 중에.<br><br>달려들어 등을 댔다. 준비 없이 받은 무게는 두 배다.<br>셋째와 넷째가 건너는 동안 이가 갈렸다. 빠져나와 보니 입안에 피 맛이 돌았다. 어금니 하나가 금 간 모양이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-32, mind:-15 } },
    { l:'③ 흔들리는 바위 밑을 그냥 빠르게 통과한다.', k:'luck', dc:25,
      doom:{ title:'내려앉는 틈', what:'무너진 틈에 깔려 어둠 밑으로 끌려 들어갑니다', dc:19, sec:45,
        text:`받치고 괴고 할 시간에 뛰면 된다. 하나씩 빠르게. 그렇게 정하고 맨 뒤에 섰다.<br><br>넷은 운이 좋았다. 다섯째, 이쪽 차례에 바위가 소리도 없이 내려앉았다.<br>허리까지 틈에 물렸다. 그리고 틈 아래가 비어 있었다. 무너진 돌과 함께 아래 어둠으로 쓸려 내려간다.<br><br>위에서 일행이 손을 뻗는다. 손가락이 닿을 듯 말 듯하다. 돌이 계속 내려온다.`,
        dieText:`틈은 완전히 메워졌다.<br><br>돌 틈 사이로 한동안 기도 소리가 올라왔다. 숨에 실은, 소리 없는 기도가 소리가 되어.<br>그 소리가 멎은 뒤에야 일행이 자리를 떴다.` },
      ok:`뛰려다 바위를 한 번 더 봤다. 흔들림의 박자가 변해 있다. 느리게, 크게.<br><br>떨어지기 직전의 박자다. 종루 대들보가 그랬다.<br>뛰기를 접고 쇠막대부터 박았다. 괴고 나서 건너는 데 반 식경. 건너자마자 막대가 부러지며 틈이 내려앉았다. 반 식경이 다섯 목숨이었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'어둠 — 머리맡의 밤',
  x:`다들 쓰러져 잔다. 지켜야 하는 밤이다.<br><br>
    수도원의 밤 기도는 시간을 재는 법이기도 했다. 구절 몇 번이면 초 하나가 탄다.<br>
    여기는 초가 없다. 어둠과 숨소리뿐이다.<br><br>
    조는 파수꾼이 제일 위험한 파수꾼이다. 깨어 있는 법이 필요하다.`,
  o:[
    { l:'① 기도 구절로 시간을 재며 깨어 있는다.', k:'steady', dc:24, wake:1,
      ok:`구절을 돌렸다. 백 번에 한 식경. 천 번에 한밤.<br><br>세는 입은 조는 법이 없다. 구절 사이사이 숨소리 다섯을 점검했다. 넷은 고르고 하나가 뒤척이면 가서 담요를 당겨 줬다.<br>새벽까지 구절이 끊기지 않았다. 기도가 등불 노릇을 한 밤이다.<br><br>깨어 지키는 것도 기도의 한 형식이라는 걸 알았다. 머리맡의 밤 기도. 수도원 책에는 없는 장이다.`,
      ng:`팔백을 넘기다 구절이 엉켰다. 엉킨 자리에서 깜빡 고개가 꺾였다.<br><br>화들짝 깨 보니 얼마가 지났는지 모르겠다.<br>숨소리를 셌다. 다섯. 다행히 다섯. 그런데 야영지 가장자리 흙에 긴 것이 쓸고 간 자국이 나 있었다. 고개 꺾인 사이의 일이다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 반 시진씩 둘이 같이 서는 당번을 짠다.', k:'fix', dc:23,
      ok:`혼자 서는 밤은 길고, 긴 밤은 존다. 둘씩 반 시진. 서로 조는 걸 보는 눈이 있게.<br><br>당번표를 흙에 그려 발로 익히게 했다.<br>밤이 다섯 토막 나니 토막마다 짧았다. 아무도 안 졸았다. 짧게 나눈 짐은 가볍다. 밤도 짐이다.`,
      ng:`셋째 당번 둘이 같이 졸았다. 둘이면 안 존다는 셈이 틀렸다. 둘이 같이 피곤하면 같이 존다.<br><br>넷째 당번이 깨서 보니 셋째 둘이 어깨를 맞대고 자고 있었다.<br>그 틈의 어둠이 무사히 지나갔기를 비는 수밖에. 다음부터는 피곤한 사람끼리 안 묶는 것까지가 당번표다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S', t:'쉬는 자리 — 줄어든 식량',
  x:`식량이 생각보다 빨리 줄었다. 오늘부터 한 끼를 줄여야 한다.<br><br>
    줄인 끼니 앞에서 눈들이 사나워진다. 배고픔은 사람을 깎는다.<br>
    금식은 수도원에서 철마다 하던 일이다. 배고픔의 생김새를 안다.<br><br>
    아는 사람이 앞장서는 게 금식의 법이다.`,
  o:[
    { l:'① 제 몫의 반을 먼저 내놓는다.', k:'heal', dc:24, wake:1,
      ok:`저녁 몫을 받아 반을 덜어 가운데 놓았다. 말없이. 제일 축난 사람 앞으로 밀었다.<br><br>그다음 끼니에 다른 하나가 반을 내놓았다. 그다음엔 둘이.<br>줄어든 끼니가 나누는 끼니가 됐다. 배는 덜 차도 눈은 순해졌다. 배고픔이 깎는 것을 나눔이 도로 메운다.<br><br>금식의 요체는 참는 게 아니라 내놓는 것이었다. 철마다 하고도 몰랐던 것을 여기 와서 배운다.`,
      ng:`내놓은 반을 아무도 안 받았다. 수도사 몫을 어떻게 받냐고.<br><br>선의가 벽이 됐다. 음식이 가운데서 식었다.<br>결국 도로 먹었다. 내놓는 데도 순서와 말이 필요하다. 말없이 미는 것이 늘 통하는 건 아니다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 배고픔을 잊는 법을 가르친다.', k:'fix', dc:24,
      ok:`허기가 제일 사나운 때는 끼니때다. 그 시간에 할 일을 만들었다. 장비 손질, 천 감기, 물 긷기.<br><br>손이 바쁘면 배가 조용하다. 수도원 금식철의 일과표가 그래서 빡빡했던 것이다.<br>줄인 한 끼의 자리에 일과 하나가 들어앉았다. 다들 저녁까지 허기를 잊었다. 반쯤은.`,
      ng:`일을 시키자 불평이 났다. 배도 고픈데 부려 먹느냐고.<br><br>속뜻을 설명하니 더 틀어졌다. 꾀로 허기를 속이려 했다는 게 들킨 셈이라.<br>그날은 다들 배고픔을 정면으로 앓았다. 빈속에 설익은 꾀는 얹힌다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'S', t:'길 — 무너진 벽',
  x:`길이 무너진 벽돌 더미로 막혔다. 돌아가는 길은 어둠이 더 짙다.<br><br>
    치울 수는 있다. 문제는 소리다. 벽돌 하나 구르는 소리가 여기서는 천둥이다.<br>
    수도원 담장을 쌓고 헐어 본 손이 있다. 돌은 던지면 울고 놓으면 조용하다.<br><br>
    힘쓰는 일을 조용히 하는 법. 그것도 수행이었다.`,
  o:[
    { l:'① 한 장씩 들어 소리 없이 옮겨 쌓는다.', k:'steady', dc:25, cost:{ might:32 },
      ok:`벽돌을 한 장씩 들었다. 들고, 돌고, 놓고. 놓을 때는 모서리부터 바닥에 대고 눕혔다.<br><br>한 식경 동안 팔이 두 배로 무거워졌다. 소리는 숨소리뿐이다.<br>사람 하나 지날 틈이 났다. 치운 벽돌은 길 옆에 가지런하다. 헌 자리도 쌓은 자리처럼. 그게 담장 일꾼의 손버릇이다.`,
      ng:`스무 장째에서 팔이 후들렸다. 벽돌 하나가 손에서 미끄러졌다.<br><br>쨍그랑 울렸다. 깨진 소리가 길 양쪽으로 달려갔다.<br>다들 더미 뒤에 엎드렸다. 어둠 저쪽에서 기척이 왔다가 한참 만에 돌아갔다. 남은 벽돌은 땀이 아니라 식은땀으로 치웠다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 다 치우지 않고 위쪽만 헐어 타 넘는다.', k:'fix', dc:24,
      ok:`길을 내는 게 아니라 문턱만 낮추기로 했다. 위쪽 석 줄만 걷어 냈다.<br><br>걷어 낸 자리로 한 사람씩 배를 깔고 넘었다. 짐은 손으로 넘겨 가며.<br>치울 돌이 반의반으로 줄었다. 길은 뚫는 것만이 아니라 넘는 것이기도 하다. 땀이 꾀를 이기는 날도 있지만 오늘은 꾀가 맞았다.`,
      ng:`타 넘던 셋째가 헐어 낸 자리의 들뜬 벽돌을 짚었다.<br><br>벽돌이 더미 안쪽으로 떨어지며 요란하게 울렸다.<br>셋째는 급한 김에 구르듯 넘어왔고, 남은 둘은 소리가 잦아들 때까지 반대편에 엎드려 있었다. 넘는 길에도 밟을 자리 검사가 먼저다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-15 } }
  ] },

{ at:'S', t:'쉬는 자리 — 같은 악몽',
  x:`둘이 같은 꿈을 꿨다고 한다. 어둠 속에서 누가 이름을 부르는 꿈.<br><br>
    같은 꿈은 우연일 수 있다. 사흘째 같은 꿈은 우연이 아니다.<br>
    꿈자리가 사나운 집에 불려 가던 일이 수도원 시절에 더러 있었다. 하던 일은 늘 같다.<br><br>
    잠든 머리맡을 지키는 것. 그리고 부르는 것에게 답하지 않게 하는 것.`,
  o:[
    { l:'① 잠들기 전에 귀에 한 구절씩 넣어 준다.', k:'heal', dc:25, wake:1,
      ok:`둘이 눕기 전에 머리맡에 앉아 낮은 구절 하나씩을 귀에 넣었다. 꿈에서 이름이 불리거든 이 구절로 답하라고.<br><br>한밤에 하나가 잠꼬대를 했다. 이름이 아니라 구절을. 웅얼웅얼.<br>아침에 둘 다 말했다. 불렸는데, 답했더니, 부르던 것이 조용해졌다고.<br><br>꿈속까지 따라 들어가는 말이 있다. 그 말을 미리 쥐여 보내는 것. 머리맡 기도의 쓸모를 하나 더 찾았다.`,
      ng:`구절을 넣어 줬는데 하나가 외우질 못했다. 꿈속에서 말이 안 나왔다고 한다.<br><br>대신 이름으로 답해 버렸다고. 제 이름으로.<br>그날부터 그 사람 꿈에서 부르는 소리가 또렷해졌다. 답한 이름은 주운 쪽이 쥔다. 밤마다 머리맡을 지키는 일이 하나 늘었다.`,
      win:{ exp:24, dream:3, spirit:8 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 둘의 잠자리를 떼어 놓고 사이에 눕는다.', k:'fix', dc:24,
      ok:`같은 꿈은 옮는 수가 있다. 붙어 자는 머리 사이로.<br><br>둘을 양 끝으로 떼고 그 사이에 이쪽이 누웠다. 옮는 길목에 돌 하나 놓듯.<br>그날 밤 이쪽 꿈에 낯선 어둠이 반 뼘 비쳤다 사라졌다. 길목 돌 노릇을 한 것이다. 둘은 꿈 없이 잤다.`,
      ng:`사이에 누웠는데 이쪽 꿈으로 그 부름이 통째로 건너왔다.<br><br>이름을 부르는 소리에 하마터면 답할 뻔했다. 꿈속에서 입을 틀어막았다.<br>새벽에 깨 보니 식은땀으로 흠뻑이다. 길목 돌은 밟히라고 있는 돌이다. 밟힌 자리가 아프다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 꿈에서 부르는 데가 어딘지 따라가 보게 한다.', k:'luck', dc:26,
      doom:{ title:'꿈의 길', what:'잠든 걸음에 이끌려 어둠으로 사라집니다', dc:19, sec:40,
        text:`부르는 것의 정체를 알아야 끝이 난다. 오늘 밤 꿈에서 도망치지 말고 소리 나는 쪽을 봐 두라고 일렀다.<br><br>한밤에 둘이 동시에 일어났다. 눈 감은 채. 같은 방향으로 걷는다.<br>따라가 깨우려는데 몸이 둘이다. 하나를 잡으면 하나가 간다. 잡은 하나도 끄는 힘이 사람 잠의 힘이 아니다.<br><br>양팔에 하나씩 매달린 채 같이 끌려간다. 꿈에 손을 대라고 시킨 건 이쪽이다. 그 빚이 세 몸으로 간다.`,
        dieText:`아침 자리에 담요 셋이 비어 있었다.<br><br>맨발 자국 둘과 신발 자국 하나가 나란히 어둠으로 갔다.<br>신발 자국은 끝까지 뒤꿈치가 깊다. 버티며 간 자국이다.` },
      ok:`일러 놓고 생각을 고쳤다. 보라고 시키는 건 꿈 쪽으로 한 발 들이미는 것이다.<br><br>밤에 둘이 눈 감은 채 일어나 걷기 시작했을 때, 미리 묶어 둔 발목 끈이 당겨졌다.<br>끈 끝의 방울 대신 이쪽 손가락이 울렸다. 둘을 하나씩 안아 눕혔다. 꿈은 들여다보는 게 아니라 못 나가게 지키는 것이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'어둠 — 이어 잡은 손',
  x:`빛 한 톨 없는 구간이다. 벽도 끊겨서 짚을 데가 없다.<br><br>
    이런 어둠에서는 다섯이 다섯 방향으로 흩어진다. 한 걸음씩 어긋나다 보면.<br>
    수도원 새벽 행렬이 이랬다. 불 없이, 앞사람 어깨만 잡고 걷던.<br><br>
    행렬을 짜는 법은 몸이 기억한다.`,
  o:[
    { l:'① 앞사람 허리끈을 잡는 행렬을 짠다.', k:'heal', dc:24, wake:1,
      ok:`한 줄로 세웠다. 손은 놓칠 수 있으니 앞사람 허리끈을 쥐게 했다. 끈은 땀에 안 미끄러진다.<br><br>맨 앞은 이쪽이다. 한 발로 바닥을 쓸어 확인하고 한 걸음. 뒤로 당김이 오면 서고, 두 번 당기면 간다.<br>말 한마디 없이 어둠을 다 건넜다. 다섯 몸이 한 줄의 염주 같았다.<br><br>행렬은 걸음이 아니라 믿음으로 간다. 끈 하나에 실리는 믿음의 무게를 손바닥이 배웠다.`,
      ng:`가운데서 끈 하나가 풀렸다. 셋째가 미끄러지며 놓친 것이다.<br><br>뒤의 둘이 어둠에 떨어져 나갔다. 부를 수도 없다.<br>제자리에 서서 바닥을 막대로 길게 두드렸다. 두 번, 쉬고, 두 번. 한 식경 만에 둘이 소리를 따라왔다. 끊어진 염주를 다시 꿰는 한 식경이었다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 제일 겁먹은 사람을 바로 뒤에 세운다.', k:'bond', dc:24,
      ok:`행렬 순서에도 법이 있다. 제일 떠는 사람을 맨 앞 바로 뒤에. 등이 보이는 자리, 끈이 제일 짧은 자리에.<br><br>그 사람 숨소리가 등에 닿았다. 거칠다가, 걸음이 쌓이자 고르게.<br>어둠을 다 건너고 그 사람이 말했다. 등만 보고 왔다고. 그러라고 있는 등이다.`,
      ng:`떠는 사람을 뒤에 세웠더니 그 떨림이 끈을 타고 왔다. 당김인지 떨림인지 신호가 안 읽힌다.<br><br>세 번을 잘못 서고 두 번을 잘못 갔다.<br>결국 멈춰서 그 사람 손을 허리끈에서 어깨로 옮겨 잡게 했다. 살이 닿으니 떨림이 가라앉았다. 끈보다 어깨가 나은 사람도 있다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S', t:'갈림길 — 고요한 쪽',
  x:`길이 둘이다. 왼쪽에서는 멀리 짐승 소리가 간간이 오고, 오른쪽은 아무 소리가 없다.<br><br>
    다들 오른쪽으로 몸이 기운다. 고요한 쪽으로.<br>
    수도원의 고요와 이 땅의 고요는 다르다. 수도원 고요는 비워서 고요하고, 여기 고요는 비워 내서 고요하다.<br><br>
    누가 비워 냈는가. 그 물음이 남는다.`,
  o:[
    { l:'① 소리 있는 쪽이 산 길이라고 말한다.', k:'sense', dc:24, wake:1,
      ok:`일행을 세웠다. 짐승 소리는 짐승이 산다는 소리다. 산 것들이 사는 길은 지나갈 수 있는 길이다. 아무것도 못 사는 길이 무서운 길이다.<br><br>왼쪽으로 갔다. 소리의 임자들은 작은 것들이었다. 사람을 피해 바위 틈으로 숨는.<br>오른쪽 길이 뒤에서 한 번 크게 울렸다. 고요하던 것이 내는 소리는 고요하지 않았다.<br><br>고요를 의심하는 법을 배웠다. 수도사가 고요를 의심하게 되다니. 이 땅의 수행은 거꾸로 간다. 그래도 수행은 수행이다.`,
      ng:`말은 했는데 오른쪽의 고요가 더 세게 당겼다. 다수결로 오른쪽이 됐다.<br><br>반 굽이 만에 다들 알았다. 벌레 소리 하나 없는 길의 뜻을.<br>바닥에 뼈가 나오기 시작했을 때 말없이 되돌았다. 되돌아 나오는 걸음이 제일 빨랐다. 고요가 등 뒤에서 듣고 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 고요한 쪽으로 먼저 발을 들인다.', k:'luck', dc:25,
      doom:{ title:'비워 낸 길', what:'고요 속의 것에게 끌려갑니다', dc:19, sec:44,
        text:`고요가 수상하면 먼저 들어가 확인하는 것도 맨 앞에 서는 자의 일이다. 혼자 들어갔다.<br><br>스무 걸음. 제 발소리만 크다. 서른 걸음. 제 발소리가 안 들린다. 소리가 안 나는 게 아니라 소리를 누가 거둬 가고 있다.<br>돌아서는데 몸이 안 돈다. 고요가 몸에 감겨 있다. 젖은 천처럼.<br><br>소리부터 거두고 몸을 거두는 것이었다. 길 안쪽으로 끌리며 입을 벌렸다. 비명이 나가지 않는다. 그것도 이미 거둬졌다.`,
        dieText:`오른쪽 길은 그날도 고요했다.<br><br>일행이 어귀에서 아무리 불러도 메아리 하나 안 돌아왔다.<br>그 길은 소리를 모은다. 모아서, 아주 가끔, 밤에 돌려준다. 아는 목소리로.` },
      ok:`열 걸음에서 멈췄다. 제 숨소리가 반으로 줄어 있었다. 숨은 그대로 쉬는데 소리만.<br><br>소리를 먹는 길이다. 들어갈수록 더 먹힐 것이다.<br>뒷걸음으로 열 걸음을 되짚어 나왔다. 어귀를 벗어나자 숨소리가 돌아왔다. 제 숨소리가 반가운 날은 흔치 않다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'표본실 — 병 속의 것들에게',
  x:`표본병이 늘어선 방이다. 액에 잠긴 것들. 사람이었던 것도 섞여 있다.<br><br>
    일행은 선반 사이를 빠르게 지나려고만 한다. 눈을 내리깔고.<br>
    보내는 일을 배운 사람은 그냥 못 지나간다. 여기는 무덤이다. 아무도 보내 주지 않은 무덤.<br><br>
    다 보낼 수는 없다. 그래도 지나는 길목만큼은.`,
  o:[
    { l:'① 지나는 선반마다 짧은 구절을 올린다.', k:'heal', dc:24, wake:1,
      ok:`걸음을 늦추지 않았다. 다만 선반 하나를 지날 때마다 숨에 구절 하나를 실었다. 잘 가라. 여기 일은 여기 두고.<br><br>스물두 선반, 스물두 구절.<br>방을 다 지나자 일행의 굳은 어깨가 풀려 있었다. 눈을 내리깐 채 지나친 것과 보내며 지나온 것은 등 뒤가 다르다.<br><br>걸으면서 올리는 예를 배웠다. 멈춰야 예가 아니다. 보내는 마음의 길이는 걸음과 상관없다.`,
      ng:`구절을 올리며 걷는데 한 병 앞에서 숨이 멎었다. 병 속의 것이 구절에 맞춰 고개를 든 것 같았다.<br><br>착각이다. 착각이어야 한다.<br>남은 선반은 구절 없이 지났다. 방을 나와서도 그 병 쪽을 한참 돌아봤다. 보내는 일에도 받는 쪽 사정이 있다는 걸 처음 생각했다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 사람이었던 병들만 천으로 가려 준다.', k:'fix', dc:24,
      ok:`다 보낼 수 없으면 덮기라도 한다. 사람 형상이 든 병 여섯에 천을 한 장씩 둘렀다.<br><br>구경거리로 두지 않는 것. 그것도 예의 반이다.<br>지나는 일행이 그 앞에서는 눈을 내리깔지 않았다. 가려 주면 볼 수 있다. 이상한 이치인데 사람 마음이 그렇다.`,
      ng:`천을 두르는데 병 하나가 선반에서 미끄러졌다. 받으려다 놓쳤다.<br><br>깨지는 소리가 방을 갈랐다. 쏟아진 액이 바닥에 퍼졌다.<br>예를 갖추려다 소란을 갖췄다. 쏟아진 그이에게 거듭 빌며 방을 떴다. 복도 저쪽에서 뭔가가 소리를 듣고 오는 기척이 났다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'S1', t:'격리 병동 — 밤의 고백',
  x:`가슴에 것이 든 사람이 잠을 미룬다. 잠들면 제가 저를 못 지킨다고.<br><br>
    한밤에 그 사람이 낮게 말을 꺼냈다. 무섭다고. 몸이 제 것이 아니게 되는 게 무섭다고.<br>
    들어 주는 것밖에 없는 밤이 있다. 수도원 문간에서 숱하게 겪었다.<br><br>
    듣는 일은 쉬워 보여서 다들 못 한다.`,
  o:[
    { l:'① 밤새 곁에 앉아 끝까지 듣는다.', k:'heal', dc:25, wake:1,
      ok:`고치겠다는 말도, 괜찮다는 말도 안 했다. 둘 다 거짓이 될 수 있는 밤이니까. 그냥 들었다.<br><br>무섭다는 말이 세 번 돌고, 집 얘기가 나오고, 웃긴 얘기가 하나 나오고, 그리고 잠들었다.<br>사람은 다 말하고 나면 잔다. 가슴속 것 위에다 제 말들을 이불처럼 덮고.<br><br>듣는 일이 치유의 첫 장이라는 걸 다시 배웠다. 손은 한 번도 안 썼는데 환자가 잤다. 몇 밤 만에 처음으로.`,
      ng:`듣다가 이쪽이 먼저 꾸벅 졸았다. 사흘 치 피로가 한꺼번에 왔다.<br><br>깨 보니 그 사람이 이쪽에 담요를 덮어 주고 있었다. 미안해서 얼굴이 달았다.<br>그 사람이 웃었다. 덕분에 남 걱정을 했더니 제 걱정을 잊었다고. 듣기에 실패하고 엉뚱하게 통했다. 이건 수행 일지에 뭐라고 적나.`,
      win:{ exp:24, dream:3, spirit:8 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 같이 지킬 테니 자라고 당번을 세운다.', k:'bond', dc:24,
      ok:`네가 너를 지키지 않아도 되게 하겠다고 했다. 당번 둘이 침상 양옆에 앉았다. 눈에 보이게.<br><br>그 사람이 양옆을 한 번씩 보고 눈을 감았다.<br>지켜 주는 눈이 보이면 몸이 긴장을 푼다. 가슴속 것도 숙주 따라 느슨해졌다. 잠이 약 노릇을 한 밤이다.`,
      ng:`당번을 세웠는데 그 사람이 오히려 미안해서 못 잤다. 저 하나 때문에 둘이 밤을 샌다고.<br><br>착한 사람이 제일 어렵다.<br>결국 다 같이 그 방에서 자는 걸로 바꿨다. 당번이 아니라 그냥 다섯이 한 방. 그제야 잤다. 지킴은 특별하지 않을 때 제일 잘 듣는다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 가슴속 것에게 직접 말을 걸어 본다.', k:'luck', dc:26,
      doom:{ title:'응답', what:'대답한 것에게 끌려 복도 어둠으로 사라집니다', dc:20, sec:38,
        text:`병자에게 하듯 그 가슴에도 말을 건넸다. 나가라고. 이 몸은 네 집이 아니라고. 문간의 악한 것들에게 하던 그대로.<br><br>가슴속 것이 멈췄다. 듣는 것이다. 통하나 싶었다.<br>그 사람 입이 열렸다. 나온 목소리는 그 사람 것이 아니었다. 집이 아니면, 하고 그 목소리가 말했다. 너는 집이 되겠느냐.<br><br>그 사람 손이 이쪽 손목을 쥐었다. 사람 손아귀가 아니다. 침상에서 복도로, 복도에서 어둠으로 끌린다. 말을 건 쪽이 문을 연 셈이 됐다.`,
        dieText:`병동 침상의 사람은 아침에 홀로 깨어났다. 가슴이 가볍다고 했다.<br><br>옮겨 앉은 것이다.<br>새 집이 어디로 걸어갔는지는 복도의 끌린 자국만 안다.` },
      ok:`말을 걸려다 입을 닫았다. 문간의 악한 것들에게도 법도가 있었다. 말을 섞는 순간 문지방이 낮아진다.<br><br>말 대신 구절을 올렸다. 그 사람을 위한 구절을, 그 사람 귀에만.<br>가슴속 것은 들을 자격이 없는 말이다. 자격 없는 말 앞에서 그것이 밤새 뒤척였다. 뒤척이느라 자라지 못했다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'기밀문 — 문을 받드는 몸',
  x:`기밀문이 반쯤 닫히다 멈춰 있다. 전기가 나갔다 들어왔다 하는 모양이다.<br><br>
    저 밑을 다섯이 지나야 한다. 문이 언제 마저 닫힐지 모른다.<br>
    쇠문은 바위보다 매끈해서 괼 데가 없다. 사람이 받드는 수밖에.<br><br>
    종루 대들보를 받던 등이 여기서 또 쓰인다.`,
  o:[
    { l:'① 문틀에 등을 대고 다섯을 통과시킨다.', k:'steady', dc:26, cost:{ might:38 }, wake:1,
      ok:`문 밑에 들어가 무릎을 굽히고 등으로 받쳤다. 쇠가 어깨뼈에 닿는 자리를 두 번 고쳐 잡았다. 받는 자리가 반이다.<br><br>지나가라. 손짓 한 번에 하나씩. 문이 두 번 부르르 떨며 내려오려 했고, 두 번 다 등이 거절했다.<br>넷이 지나고, 몸을 굴려 빠졌다. 문이 등 뒤에서 쾅 닫혔다.<br><br>받드는 등의 요체는 힘이 아니라 자리라는 것. 대들보가 가르치다 만 것을 쇠문이 마저 가르쳤다.`,
      ng:`둘째가 지날 때 문이 세게 떨렸다. 받친 등이 반 뼘 눌렸다.<br><br>남은 둘은 기다시피 빠져나갔다. 이쪽이 빠질 차례에 문이 또 내려왔다.<br>어깨가 문틀에 긁히며 겨우 굴러 나왔다. 등짝에 쇠문 자국이 시퍼렇게 앉았다. 자국값으로 다섯이 넘어왔으면 싼 것이다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-32, spirit:-16 } },
    { l:'② 문틈에 쇠 침대 다리를 부러뜨려 괸다.', k:'break', dc:25, cost:{ might:30 },
      ok:`병동 쇠 침대를 끌어와 다리 하나를 발로 꺾어 부러뜨렸다. 굵은 쇠토막이다.<br><br>문틈에 세워 박았다. 문이 내려오다 쇠토막을 물고 멈췄다.<br>다섯이 느긋하게 지났다. 등은 아껴 두는 게 맞다. 등보다 먼저 내놓을 것이 있으면.`,
      ng:`다리를 꺾는 소리가 병동에 울렸다. 쇠가 쇠를 꺾는 소리는 숨겨지지 않는다.<br><br>괴기는 괴었는데, 복도 끝에서 긁는 소리가 일어났다.<br>다섯이 뛰다시피 문을 지났다. 괸 쇠토막은 그대로 뒀다. 뒤쫓는 것한테도 열린 문이 된 건 셈에 없던 일이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S1', t:'복도 — 터지는 울음',
  x:`한 사람이 복도 한가운데서 무너졌다. 소리 없이 울기 시작하더니 어깨가 점점 커진다.<br><br>
    터지기 직전이다. 터지면 통곡이고, 통곡은 이 건물 전부를 부른다.<br>
    울음을 막으면 안에서 곪고, 터뜨리면 밖에서 죽는다.<br><br>
    울음을 받아 주되 소리만 거두는 법. 문간에서 배운 것 중 제일 어려운 기술이다.`,
  o:[
    { l:'① 끌어안아 울음을 가슴으로 받는다.', k:'heal', dc:25, cost:{ might:26 }, wake:1,
      ok:`마주 안았다. 그 사람 얼굴을 이쪽 어깨에 묻고, 팔로 등을 단단히 둘렀다.<br><br>울음이 터졌다. 소리가 이쪽 어깨 살에 다 먹혔다. 들썩임은 팔이 받았다.<br>복도에는 숨소리 비슷한 것만 샜다. 다 울 때까지 안고 서 있었다. 한 식경.<br>다 운 사람이 떨어지며 고맙다고도 미안하다고도 안 했다. 그 얼굴이면 됐다.<br><br>몸이 벽이 되고 그릇이 되는 법. 울음 한 그릇을 몸으로 받아 낸 건 처음이다. 무거웠다. 받을 만했다.`,
      ng:`안는 게 반 박자 늦었다. 첫 울음 한 가닥이 복도에 터져 나갔다.<br><br>길고, 사람의 것이 분명한 소리.<br>안은 채로 둘이 벽감에 몸을 구겼다. 복도 끝에서 기척이 왔다 갔다 했다. 품속의 울음은 그치지 않았다. 그치라고 할 수도 없었다. 제일 긴 한 식경이었다.`,
      win:{ exp:24, dream:3, spirit:8 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 빈 방 하나를 찾아 울 자리를 내준다.', k:'fix', dc:24,
      ok:`터지기 전에 팔을 끌었다. 두 방 건너 문 두꺼운 창고. 담요로 문틈까지 막았다.<br><br>여기서는 울어도 된다고 했다. 실컷.<br>창고가 반 시진 동안 울음을 다 받아 줬다. 나온 얼굴이 홀가분했다. 울 자리를 정해 주는 것도 돌봄이다. 울음에도 방이 필요하다.`,
      ng:`끌고 가는 중에 터졌다. 복도 한가운데서.<br><br>손바닥으로 입을 막고 반은 안고 반은 끌고 창고까지 갔다.<br>막힌 울음이 창고에서 두 배로 터졌다. 문 두꺼운 게 다행이었다. 반 박자 빠른 손이 이 일의 전부라는 걸 또 배운다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S1', t:'환기구 밑 — 잠든 다섯',
  x:`겨우 잡은 잠자리 천장에 환기구가 있다. 다른 자리는 없다.<br><br>
    밤중에 저 위로 무언가 지나다닐 것이다. 소리에 누가 깨서 소리를 내면 끝이다.<br>
    자기 전에 마음을 눕히는 것. 수도원에서는 저녁 기도가 그 일을 했다.<br><br>
    겁먹은 채 잠든 몸은 작은 소리에도 비명으로 깬다. 눕힌 마음은 눈만 뜬다.`,
  o:[
    { l:'① 눕기 전에 낮은 목소리로 마음을 눕힌다.', k:'heal', dc:25, wake:1,
      ok:`둘러앉혀 놓고 숨소리만 한 목소리로 말했다. 밤에 위에서 소리가 날 것이다. 그건 지나가는 소리다. 지나가는 것은 지나가게 두면 된다.<br><br>겁은 모르는 데서 자란다. 미리 알면 반으로 준다.<br>밤에 정말 위로 세 번 지나갔다. 다섯 다 눈만 떴다 감았다. 비명은 없었다.<br><br>무서운 밤의 저녁 기도는 내용이 아니라 예고라는 것. 알려 주는 것이 눕히는 것이다.`,
      ng:`말하는 중에 위에서 벌써 소리가 났다. 예고가 실황이 됐다.<br><br>다들 천장만 보느라 말이 귀에 안 들어갔다.<br>그 밤 둘이 설잠에 뒤척였고, 한 번은 잠꼬대가 크게 났다. 위의 것이 멈췄다 가는 간담 서늘한 순간도 한 번. 예고는 소리보다 먼저여야 예고다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 제일 겁 많은 사람을 벽 쪽 깊이 눕힌다.', k:'fix', dc:24,
      ok:`자리에도 법이 있다. 겁 많은 순서로 벽 쪽, 담대한 순서로 환기구 밑.<br><br>이쪽이 환기구 바로 밑에 누웠다. 밤에 깨도 비명 안 지를 사람이 거기 눕는 것이다.<br>새벽에 위에서 긁는 소리에 깼다. 눈만 뜨고 소리를 배웅했다. 자리 법 하나로 밤이 통째로 조용했다.`,
      ng:`자리를 정해 주자 겁 많다고 지목된 사람이 상했다. 제가 왜 벽 쪽이냐고.<br><br>자존심이 겁보다 큰 사람이 있다.<br>실랑이 끝에 그 사람이 환기구 밑을 맡았고, 밤에 소리에 깨 하마터면 소리칠 뻔했다. 옆에서 입을 막아 넘겼다. 자리 법은 맞는데 말 법이 틀렸다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S1', t:'둥지 어귀 — 어미 앞의 고요',
  x:`지나야 하는 복도 끝이 둥지 어귀다. 안쪽에서 큰 숨소리가 밀려온다. 어미의 숨이다.<br><br>
    깨어 있다. 다만 어두워서 눈보다 귀로 지킨다.<br>
    완전한 고요로 반 굽이를 건너야 한다. 발소리, 숨소리, 옷깃, 침 삼키는 소리까지.<br><br>
    수도원의 침묵 수행이 여기서 목숨값이 될 줄은 몰랐다.`,
  o:[
    { l:'① 침묵 수행의 법대로 다섯을 이끈다.', k:'heal', dc:26, wake:1,
      ok:`출발 전에 가르쳤다. 발은 뒤꿈치 들고 바깥날부터. 숨은 입 벌려 소리 죽여. 짐은 품에 안고. 침은 미리 삼켜 두고.<br><br>그리고 제일 중요한 것. 서두르려는 마음이 소리를 낸다. 느린 것이 고요한 것이다.<br>다섯이 반 굽이를 느리게, 완전한 침묵으로 건넜다. 어미의 숨소리가 한 번도 바뀌지 않았다.<br><br>침묵은 참는 게 아니라 하는 것이다. 수행으로 알던 것을 기술로 다시 배웠다. 목숨 걸고 하는 수행이 제일 빨리 는다.`,
      ng:`넷까지는 완벽했다. 다섯째 짐끈이 벽 모서리를 스쳤다. 사각.<br><br>어미의 숨이 멎었다. 듣는 멈춤.<br>다섯이 그 자리에 그대로 굳었다. 조각상 다섯. 어미 숨이 다시 돌 때까지 백을 셋 셌다. 마지막 열 걸음은 다들 울 것 같은 얼굴로 건넜다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 어미 숨의 박자에 걸음을 싣는다.', k:'hide', dc:26,
      ok:`큰 숨에는 큰 소리가 묻힌다. 어미가 숨을 내쉴 때만 걷기로 했다.<br><br>내쉬는 숨, 세 걸음. 들이쉬는 숨, 정지. 어미의 숨이 다섯의 걸음을 실어 날랐다.<br>반 굽이를 어미 제 숨에 묻혀 건넌 것이다. 지키는 자의 숨이 지나가는 자의 다리가 됐다.`,
      ng:`박자를 타던 중에 어미 숨이 길게 끊겼다. 잠든 것이 아니라 냄새를 맡는 것이다.<br><br>걸음도 끊겼다. 복도 한가운데서.<br>어미 코가 바람을 두 번 길게 당겼다. 다행히 바람이 이쪽 편이었다. 숨이 다시 돌고서야 남은 길을 건넜다. 등이 다 젖은 채.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'③ 혼자 소리를 내어 어미를 다른 쪽으로 꾄다.', k:'luck', dc:26,
      doom:{ title:'어미의 귀', what:'어미에게 붙들려 둥지 안으로 끌려갑니다', dc:20, sec:35,
        text:`다섯의 고요보다 하나의 소리가 낫다고 셈했다. 반대쪽 복도로 혼자 가서 벽을 두드렸다. 또박또박.<br><br>어미가 움직였다. 빠르다. 생각한 것의 세 배로.<br>소리 낸 자리에서 두 번째 모퉁이까지밖에 못 갔다. 어미는 소리가 아니라 소리 낸 것의 숨을 쫓아왔다.<br><br>복도가 좁아서 피할 데가 없다. 붙들렸다. 둥지 쪽으로 끌려가며 들었다. 일행이 건너는 소리를. 그 셈 하나는 맞았다.`,
        dieText:`어미는 제 둥지로 돌아가 다시 조용해졌다.<br><br>복도에는 두드리던 돌멩이 하나가 떨어져 있다.<br>일행은 건넜다. 그 값을 치른 사람만 돌아오지 못했다.` },
      ok:`벽을 두드리려다 손을 멈췄다. 어미의 숨이 너무 고르다. 저건 조는 숨이 아니라 기다리는 숨이다.<br><br>소리를 기다리는 것한테 소리를 주는 건 꾐이 아니라 배달이다.<br>돌아와 침묵 수행 쪽으로 정했다. 느리고 조용한 반 굽이. 어미는 끝까지 기다리기만 했다. 줄 것을 안 줬으니까.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'냉동 구역 — 견디는 법',
  x:`지나야 하는 냉동 구역이 길다. 숨이 하얗게 얼어붙는 추위다.<br><br>
    돌아가는 길은 둥지 쪽이다. 추위가 이빨보다 낫다.<br>
    겨울 수도원의 새벽 예배당이 이랬다. 견디는 법이 있다.<br><br>
    추위는 싸우면 지고 받아들이면 지나간다. 말은 쉽다.`,
  o:[
    { l:'① 견디는 법을 하나씩 일러 주며 앞장선다.', k:'heal', dc:25, wake:1,
      ok:`들어가기 전에 일렀다. 이를 악물지 말 것. 어깨를 움츠리지 말 것. 숨은 코로 짧게. 떨림은 참지 말고 떨 것. 떨림이 몸의 군불이다.<br><br>겨울 예배당에서 노승들이 가르친 그대로.<br>한 줄로 통과했다. 끝에서 세어 보니 다섯 다 손발이 제 색이다. 움츠린 몸이 먼저 어는 법인데, 아무도 안 움츠렸다.<br><br>견디는 것도 가르칠 수 있는 기술이라는 것. 수도원의 겨울이 여기서 다섯을 데리고 나왔다.`,
      ng:`일렀는데도 하나가 이를 악물고 어깨를 말았다. 몸이 겁을 먼저 배운 사람이다.<br><br>그 사람 손끝이 구역 반쯤에서 하얘졌다.<br>겨드랑이에 그 손을 끼고 남은 반을 끌다시피 걸었다. 나와서 반 시진을 주물렀다. 가르침이 안 닿는 몸에는 몸으로 가르치는 수밖에 없다.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ hp:-28, spirit:-16 } },
    { l:'② 둘씩 팔짱을 끼워 체온을 묶는다.', k:'bond', dc:24,
      ok:`둘씩 팔짱을 단단히 끼게 했다. 홀수 하나는 이쪽 팔에.<br><br>붙은 몸은 바람 닿는 면이 준다. 두 몸의 열이 한 겹 옷이 된다.<br>셋 쌍이 구역을 건넜다. 서로의 떨림이 서로의 군불이었다. 혼자 견디는 추위와 둘이 견디는 추위는 다른 추위다.`,
      ng:`팔짱 낀 둘의 걸음이 자꾸 엇갈렸다. 급한 쪽과 신중한 쪽이 묶인 것이다.<br><br>엇갈리다 한 쌍이 미끄러운 바닥에 같이 넘어졌다.<br>찬 바닥에 쏟은 체온이 컸다. 나와서 그 둘을 한참 녹였다. 묶는 데도 궁합이 있다. 그것까지 보는 게 묶는 사람 일이다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S2', t:'양치 숲 — 다섯 짐과 두 어깨',
  x:`진창길이다. 발이 빠지는 땅에서 짐이 걸음을 먹는다.<br><br>
    다친 둘의 짐까지 셋이 나눠 졌더니 다들 반걸음씩 늦다.<br>
    수도원 순례길에서 제일 힘센 자가 하던 일이 있다. 남의 짐을 지는 일. 그게 그 사람의 기도였다.<br><br>
    여기서는 그 기도가 속도가 된다.`,
  o:[
    { l:'① 짐 셋을 몰아 지고 행렬 가운데 선다.', k:'steady', dc:25, cost:{ might:34 }, wake:1,
      ok:`짐 셋을 끈으로 엮어 한 덩이로 만들어 졌다. 어깨가 한 번 내려앉고, 다시 올라왔다.<br><br>짐 벗은 셋이 다친 둘을 양쪽에서 부축했다. 행렬이 반걸음 빨라졌다.<br>진창 두 굽이를 그 짜임으로 건넜다. 어깨는 밤에 호되게 앓았다. 앓는 어깨로 올린 저녁 기도가 유난히 짧고 깊었다.<br><br>짐을 지는 것이 기도가 되는 순간을 몸으로 겪었다. 순례길 노역부들의 얼굴이 그제야 읽혔다.`,
      ng:`세 짐을 지고 진창에 발이 깊이 빠졌다. 무게가 발을 박은 것이다.<br><br>빼내느라 행렬이 통째로 섰다.<br>결국 짐 하나를 도로 내렸다. 지는 것도 셈이 먼저다. 두 짐이 이 진창의 정량이었다. 정량은 욕심이 아니라 발바닥이 정한다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-15 } },
    { l:'② 긴 막대 둘로 들것을 엮어 짐을 싣는다.', k:'fix', dc:24,
      ok:`굵은 양치 줄기 둘을 베어 천으로 엮었다. 들것이다. 짐 셋을 싣고 앞뒤로 둘이 멘다.<br><br>어깨 하나가 질 것을 어깨 넷이 나눴다.<br>메는 둘은 반 굽이마다 교대. 진창을 다 건널 때까지 아무 어깨도 내려앉지 않았다. 연장은 몸의 기도를 거드는 물건이다.`,
      ng:`엮은 천이 진창 반에서 풀렸다. 짐 셋이 흙탕에 쏟아졌다.<br><br>건지고, 닦고, 다시 엮고.<br>시간이 걸음을 다 먹었다. 매듭을 아는 손이 묶었어야 했다. 손재주도 아껴 쓰면 빚이 된다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S2', t:'울타리 — 문을 미는 것들',
  x:`울타리 쪽문을 넘자마자 그것들이 왔다. 문짝 하나를 사이에 두고.<br><br>
    빗장이 삭아 부러졌다. 문은 몸으로 미는 수밖에 없다.<br>
    문 너머에서 영리한 것들이 번갈아 부딪친다. 힘을 재 보는 것이다. 이쪽 힘을.<br><br>
    일행이 안쪽 빗장감을 찾는 동안 문이 버텨야 한다.`,
  o:[
    { l:'① 문에 등을 대고 버티며 빗장을 기다린다.', k:'steady', dc:26, cost:{ might:40 }, wake:1,
      ok:`문짝에 등을 대고 두 발을 바닥에 박았다. 첫 충돌. 받았다. 둘째. 받았다.<br><br>놈들이 박자를 바꿨다. 둘이 한꺼번에. 등이 반 뼘 밀렸다가 돌아왔다.<br>빗장감이 왔다. 쇠 지렛대 하나. 문고리에 꿰는 동안 마지막 충돌을 받았다.<br>빗장이 걸리자 놈들이 몇 번 더 밀어 보고 물러갔다.<br><br>버티는 등은 벽이 아니라 용수철이어야 한다는 걸 몸이 배웠다. 받고, 눌리고, 돌아오고. 그 반동이 수행의 호흡과 같았다.`,
      ng:`셋째 충돌이 박자를 속였다. 늦게 올 줄 알았는데 바로 왔다.<br><br>등이 문짝째 한 자나 밀렸다. 문틈으로 발톱 하나가 들어와 허공을 갈랐다.<br>소리를 지르며 도로 밀었다. 빗장이 걸린 건 다섯 숨 뒤다. 그 다섯 숨 동안 문틈의 발톱이 어깨를 한 번 스쳤다. 뜨겁다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-32, spirit:-18 } },
    { l:'② 문 대신 옆 울타리 틈새로 다 빼낸다.', k:'sense', dc:25,
      ok:`문을 버리기로 했다. 문은 저들이 아는 길이고, 아는 길에서 싸우면 진다.<br><br>울타리를 훑어 안쪽으로 덤불이 우거진 틈새를 찾았다. 하나씩 빠져나가게 하고 맨 뒤에 섰다.<br>다 빠지고 나서 문이 부서지는 소리가 났다. 부서진 문 앞에 아무도 없는 것. 그게 저들이 받은 답이다.`,
      ng:`틈새가 생각보다 좁았다. 짐 멘 채로는 안 빠진다.<br><br>짐을 벗고 넘기고 다시 메는 사이, 문짝이 쪼개지는 소리가 났다.<br>마지막 둘은 짐을 던지고 뛰었다. 울타리 안쪽 가시에 팔뚝이 다 긁혔다. 틈새도 재 보고 쓰는 것이다. 급할수록.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'③ 문을 열고 먼저 치고 나간다.', k:'luck', dc:26,
      doom:{ title:'열린 문', what:'문밖의 무리에게 물려 끌려갑니다', dc:20, sec:36,
        text:`버티는 건 끝이 없다. 차라리 문을 확 열고 기세로 밀어 버리기로 했다.<br><br>문을 당겼다. 문밖에 셋이 아니라 일곱이 있었다. 부딪치던 둘은 소리 담당이었다. 나머지는 문이 열리기를 조용히 기다리고 있었다.<br>기세는 수가 많은 쪽 것이다.<br><br>첫 놈은 주먹으로 받았다. 둘째는 못 받았다. 장딴지에 이빨이 박히고, 열린 문 밖으로, 수풀로 끌려 나간다. 문은 열어 준 꼴이 됐다. 양쪽 다에게.`,
        dieText:`울타리 쪽문이 활짝 열린 채 바람에 흔들렸다.<br><br>일행은 안쪽 헛간 지붕으로 올라가 밤을 났다.<br>문이란 버티라고 있는 것이다. 그 문이 밤새 삐걱삐걱, 빈 말을 했다.` },
      ok:`문고리를 쥐었다가 놓았다. 부딪침 소리를 다시 셌다. 둘이 번갈아, 박자가 고르다.<br><br>고른 박자는 꾐이다. 성난 짐승은 박자가 없다.<br>문밖에 조용한 머릿수가 더 있다는 뜻이다. 문을 더 세게 막고 빗장을 기다렸다. 열지 않은 문 너머에서 기다리다 지친 것들이 흩어지는 소리가 났다. 여럿이었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'물가 — 건지는 팔',
  x:`징검돌을 건너던 사람이 미끄러져 깊은 물에 빠졌다. 짐까지 멘 채다.<br><br>
    허우적대는 소리가 물을 두드린다. 이 물에서 그 소리는 종소리다. 큰 것이 듣는.<br>
    빠진 사람을 건지는 법은 물가 수도원에서 배웠다. 급한 손은 둘 다 빠뜨린다.<br><br>
    빠르되 급하지 않게. 그 사이가 좁다.`,
  o:[
    { l:'① 허리끈을 풀어 던져 끌어낸다.', k:'fix', dc:25, cost:{ might:29 }, wake:1,
      ok:`뛰어들고 싶은 다리를 눌렀다. 허리끈을 풀어 끝에 매듭을 짓고 던졌다. 손 닿는 데 정확히.<br><br>잡아라. 짧게 한 마디. 허우적대던 손이 끈을 잡았다.<br>버티고 서서 한 발씩 물러나며 끌었다. 사람이 물에서 뭍으로 끌려 나왔다. 짐째.<br>물소리는 두 번으로 끝났다. 빠진 소리와 나온 소리.<br><br>건지는 자는 마른 땅에 서 있어야 한다는 것. 물가 수도원의 첫 가르침이 여기서 사람을 건졌다.`,
      ng:`첫 던짐이 짧았다. 끈이 물만 때렸다.<br><br>그 물소리가 하나 더 보태졌다. 걷어 올려 다시 던지는 사이 빠진 사람이 한 번 가라앉았다 떠올랐다.<br>둘째 던짐에 겨우 잡았다. 끌어내고 보니 물 건너 멀리서 물결이 이쪽으로 길게 오고 있었다. 다들 물가에서 뛰어 물러났다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-16 } },
    { l:'② 얕은 데로 돌아 들어가 몸으로 받친다.', k:'heal', dc:25,
      ok:`물길을 봤다. 빠진 자리 아래쪽에 허리 깊이 얕은 턱이 있다. 흐름이 사람을 그리로 민다.<br><br>그 턱에 먼저 들어가 기다렸다. 떠내려온 사람을 받아 안았다.<br>둘이 물을 걸어 나왔다. 흐름과 싸우지 않고 흐름이 데려다주는 자리에서 받은 것이다. 물은 밀어내는 것이 아니라 읽는 것이다.`,
      ng:`턱을 잘못 짚었다. 받으려는 자리보다 흐름이 빨랐다.<br><br>스치는 손을 한 번 놓치고, 옷자락을 겨우 낚았다.<br>둘 다 물을 몇 모금 먹고 나왔다. 기침을 참느라 얼굴이 벌겠다. 물가에 오래 있었다. 너무 오래. 물결 하나가 다가오다 말았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-15 } }
  ] },

{ at:'S2', t:'들판 — 굳은 발',
  x:`들판 한가운데서 한 사람이 멈췄다. 발이 안 떨어진다고 한다.<br><br>
    다친 게 아니다. 겁이 다리를 가둔 것이다. 멀리서 그것들 울음이 겹쳐 들린 뒤부터다.<br>
    몸이 가두면 말로는 못 연다.<br><br>
    문간에서 굳어 버린 사람들을 숱하게 봤다. 여는 법도 몇 가지 봤다.`,
  o:[
    { l:'① 손을 잡고 한 걸음만 세어 준다.', k:'heal', dc:25, wake:1,
      ok:`멀리 승강기를 보라고 하지 않았다. 먼 것이 가둔 다리다. 발끝 한 뼘 앞에 돌 하나를 가리켰다.<br><br>저기까지만. 한 걸음. 같이 세자. 하나.<br>한 걸음이 나왔다. 다음 돌, 또 하나. 열 걸음부터는 세지 않아도 걸었다.<br>굳은 다리는 목적지가 아니라 다음 한 걸음이 푼다.<br><br>천 리를 보여 주지 말고 한 뼘을 보여 줄 것. 문간의 법이 들판에서도 통했다.`,
      ng:`하나, 를 셌는데 발 대신 눈물이 먼저 나왔다. 그 사람이 주저앉아 버렸다.<br><br>앉은 사람은 세워지지 않는다. 업는 수밖에.<br>업고 반 들판을 건넜다. 등에서 그 사람이 연신 미안하다고 했다. 미안함은 들판 건너서 받겠다고 했다. 지금은 꽉 잡기만 하라고.`,
      win:{ exp:24, dream:3, spirit:8 }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 등에 업고 그냥 간다.', k:'steady', dc:25, cost:{ might:31 },
      ok:`말 걸 시간이 없다. 등을 내밀었다. 업혀라.<br><br>업히는 것도 용기다. 그 사람이 업혔다.<br>들판 반을 업고 걸었다. 등 위에서 그 사람 숨이 차츰 가라앉더니, 내려 달라고 했다. 남은 반은 제 발로 걸었다. 등이 반, 발이 반. 그렇게도 건넌다.`,
      ng:`업고 가는데 수풀 울음이 또 겹쳤다. 등 위의 몸이 돌처럼 굳으며 목을 조여 왔다.<br><br>숨이 막혀 둘 다 멈췄다.<br>팔을 풀어 다시 잡히는 데 한참. 겁은 업어도 따라온다. 그걸 등으로 배웠다. 그래도 끝까지 업고 갔다. 따라오는 겁째로.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S2', t:'풀밭 — 불 없는 밤의 차례',
  x:`울타리 안쪽 헛간에서 나는 밤이다. 불은 못 피운다.<br><br>
    어둠 속에서 밤이 길면 마음이 제멋대로 간다. 수풀 소리 하나하나가 다 이빨이 된다.<br>
    수도원의 밤샘 기도에는 차례가 있었다. 시간을 토막 내고 토막마다 할 일을 두는.<br><br>
    할 일이 있는 마음은 제멋대로 가지 않는다.`,
  o:[
    { l:'① 밤을 토막 내 차례표를 짠다.', k:'fix', dc:24, wake:1,
      ok:`밤을 다섯 토막으로 갈랐다. 토막마다 둘은 망, 하나는 장비 점검, 둘은 잠. 토막이 바뀔 때마다 역할이 돈다.<br><br>차례표가 돌자 밤이 짧아졌다. 다들 제 토막의 제 일만 보면 되니까.<br>수풀 소리는 밤새 났지만 아무도 소리에 잡아먹히지 않았다. 일이 마음의 울타리가 된 것이다.<br><br>밤샘 기도의 차례법이 들판 헛간에서 다시 쓰였다. 형식이 사람을 지킨다. 그래서 형식이다.`,
      ng:`차례표를 말로만 돌렸더니 둘째 토막에서 순서가 엉켰다. 둘이 같이 자고 망이 비었다.<br><br>빈 망 시간에 울타리 밖에서 킁킁대는 소리가 다녀갔다.<br>아침에 울타리 밑 흙이 파헤쳐져 있는 걸 봤다. 표는 흙바닥에라도 그려야 표다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 토막마다 깨어 있는 이들과 속말 기도를 돈다.', k:'heal', dc:24,
      ok:`망 서는 둘 곁에 번갈아 앉았다. 소리 없는 기도를 같이 돌렸다. 숨에 실어서.<br><br>혼자 서는 망과 곁이 있는 망은 길이가 다르다.<br>밤이 다섯 토막 다 지나갔다. 마지막 토막의 둘이 말했다. 이상하게 안 무서웠다고. 이상할 것 없다. 곁이 있었으니까.`,
      ng:`셋째 토막에서 이쪽 몸이 바닥났다. 모든 토막을 다 돌 수는 없는 몸이다.<br><br>넷째 토막 둘은 곁 없이 섰다. 그 토막이 제일 길었다고 했다.<br>곁이 되는 일도 양이 있다. 바닥난 곁은 곁이 아니다. 제 잠도 차례표에 넣는 것. 그걸 빼먹었다.`,
      win:{ exp:20, dream:3, spirit:8 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S2', t:'승강기 앞 — 녹슨 문',
  x:`승강기가 내려왔다. 그런데 문이 반 뼘 열리다 만다. 홈에 녹이 들어찬 것이다.<br><br>
    수풀이 울타리 밖에서 울렁인다. 승강기 소리를 들은 것이다.<br>
    반 뼘 틈에 손가락을 걸고 벌리는 수밖에 없다.<br><br>
    종루 문도 겨울마다 이랬다. 요령은 손가락이 아니라 허리다.`,
  o:[
    { l:'① 틈에 어깨를 박고 허리로 민다.', k:'break', dc:26, cost:{ might:37 }, wake:1,
      ok:`틈에 손끝을 걸고, 팔꿈치, 어깨 순으로 박아 넣었다. 그리고 허리를 틀며 밀었다.<br><br>끼이익. 문이 한 뼘, 두 뼘. 녹 가루가 머리 위로 쏟아졌다.<br>사람 하나 들어갈 폭이 나자 넷을 먼저 밀어 넣고 마지막에 몸을 구겨 넣었다.<br>문은 안에서 둘이 당기자 도로 닫혔다. 수풀이 울타리를 넘는 소리가 그 직후에 났다.<br><br>문은 손이 아니라 몸통으로 여는 것이다. 종루의 겨울들이 오늘을 위한 연습이었던 셈이다.`,
      ng:`어깨를 박고 밀었는데 문이 아니라 어깨가 먼저 소리를 냈다. 우두둑.<br><br>한 번 쉬고, 각도를 바꿔 다시. 두 번째에 열렸다.<br>그 한 번의 사이에 수풀이 울타리까지 왔다. 마지막 사람은 발뒤꿈치로 흙을 차며 들어왔다. 문틈이 닫히는 순간 밖에서 쿵 소리가 났다. 늦은 이빨이다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-32, mind:-15 } },
    { l:'② 쇠막대를 틈에 꽂아 지렛대로 연다.', k:'fix', dc:25,
      ok:`맨 어깨보다 연장이다. 울타리 쇠살 하나를 뽑아 틈에 꽂고 다 같이 눌렀다.<br><br>다섯 무게가 지렛대 끝에 실렸다. 문이 비명을 지르며 열렸다.<br>지렛대는 힘을 다섯 배로 만든다. 다섯 사람이면 스물다섯이다. 녹슨 문 따위가 버틸 수가 없다.`,
      ng:`쇠살이 반쯤 열다가 뚝 부러졌다. 삭은 쇠였다.<br><br>부러진 반 토막이 홈에 끼어 문이 그 자리에 섰다.<br>낀 토막을 빼느라 손끝이 다 까졌다. 결국 몸으로 마저 열었다. 연장도 골라 쓰는 것이다. 삭은 울타리의 쇠는 울타리만큼만 쇠다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-15 } },
    { l:'③ 문은 두고 바구니 지붕 위로 오른다.', k:'luck', dc:26,
      doom:{ title:'지붕 위', what:'뛰어오른 것에게 낚여 수풀로 끌려갑니다', dc:20, sec:35,
        text:`문과 씨름할 시간이 없다. 바구니 지붕으로 올라 천장 뚜껑으로 들어가기로 했다. 먼저 지붕에 올라 손을 내렸다.<br><br>둘을 끌어올렸을 때 수풀이 터졌다. 그것들은 달리는 속도로 뛴다. 울타리를 디딤돌 삼아.<br>지붕 위는 틈도 가림도 없는 자리다.<br><br>셋째를 끌어올리던 팔이 공중에서 낚였다. 지붕에서 울타리로, 울타리에서 수풀로. 손에 쥐었던 셋째의 손목이 마지막까지 따뜻했다.`,
        dieText:`승강기 지붕에 손자국이 남았다.<br><br>안으로 들어간 넷이 천장 뚜껑을 밤새 붙들고 있었다.<br>바구니가 올라가는 동안 수풀은 조용했다. 식사 중의 조용함이었다.` },
      ok:`지붕에 오르려다 수풀을 봤다. 울렁임이 울타리 바로 밑까지 와 있다. 뛰면 닿는 거리다.<br><br>지붕은 저들 사정거리 안이다.<br>내려와서 문틈에 어깨를 박았다. 긁히고 끼이면서도 문이 맞는 길이었다. 높은 데가 늘 안전한 건 아니다. 뛰는 것들의 땅에서는.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'승강기 — 올라가며 세는 수',
  x:`쇠 바구니가 올라간다. 발밑 창살 너머로 정원이 가라앉는다.<br><br>
    다들 바닥에 늘어져 숨만 쉰다.<br>
    수도원에서는 돌아온 순례자들을 문간에서 셌다. 하나, 둘. 이름을 부르며.<br><br>
    세는 것으로 끝나는 길이 있고, 세어 줘야 끝나는 사람이 있다.`,
  o:[
    { l:'① 한 사람씩 이름을 부르며 손을 잡는다.', k:'heal', dc:24, wake:1,
      ok:`첫째 이름을 불렀다. 네. 손을 잡았다. 둘째, 셋째, 넷째. 네 번의 대답, 네 번의 손.<br><br>다섯째는 이쪽이다. 넷째가 이쪽 이름을 불러 줬다.<br>다섯 번째 대답이 바구니 안에 떨어지자 그제야 다들 울었다. 웃으면서. 수가 맞는 것. 그게 이 땅에서 제일 큰 기적이라는 걸 다들 알아서.<br><br>세어 주는 것이 끝맺음이라는 걸 배웠다. 길은 발이 끝내지만 사람은 이름이 끝낸다.`,
      ng:`둘째를 부르는데 목이 메어 이름이 안 나왔다.<br><br>참았던 것이 세는 중에 올라온 것이다.<br>넷이 가만히 기다려 줬다. 숨을 고르고 다시 셌다. 끝까지 셌다. 메는 목으로 세는 수도 수는 수다. 다만 오래 걸렸을 뿐이다.`,
      win:{ exp:24, dream:4, spirit:8 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 소리 없이 감사의 구절을 올린다.', k:'steady', dc:23,
      ok:`숨에 구절을 실었다. 다섯이 올라갑니다. 다섯 그대로.<br><br>옆에서 하나가 눈치채고 고개를 숙였다. 하나씩 번져 다섯이 다 고개를 숙였다. 각자의 방식으로, 각자의 데에.<br>바구니 쇠 소리가 그동안만은 종소리 비슷했다. 올라가는 내내.`,
      ng:`구절을 올리는데 바구니가 덜컹하며 한 번 멈췄다.<br><br>다섯 심장이 같이 멈췄다. 삭은 줄이 버티는 소리가 머리 위에서 길게 났다.<br>바구니는 다시 올라갔다. 구절은 감사에서 간청으로 바뀌었다. 끝까지 간청이었다. 땅을 밟고서야 감사로 돌아왔다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-18, spirit:-16 } }
  ] }

]);
